window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s6-1414","number":1414,"surah":6,"verses":[128],"references":[{"surah":6,"verses":[128]},{"surah":11,"verses":[107]}],"verseLabel":"الأنعام: 128؛ هود: 107","question":"ما دلالة صيغة ﴿فعال﴾ في قوله: ﴿إن ربك فعال لما يريد﴾؟","answer":"صيغة المبالغة تدل على كمال نفاذ إرادته وكثرة ما يقع منها؛ فلا يعجزه شيء يريده ولا يخرج حكم عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص728، تحت «دلالة صيغة ﴿فعال﴾»","url":""}]},{"id":"s6-880","number":880,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"لماذا وصف طرفا الولاية في قوله تعالى: ﴿نولي بعض الظالمين بعضًا﴾ بأنهما ظالمان؟","answer":"لأن المتبوع ظلم بقيادته إلى الفساد، والتابع ظلم بقبول ولايته ومشاركته؛ فاجتماعهما نتيجة تشابه اختيارهما، والظلم المتكرر يفضي إلى ظلم عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص83، تحت عنوان «علة جعل الفريقين ظالمين»","url":""}]},{"id":"s6-881","number":881,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"لماذا كرر ﴿بعض﴾؟","answer":"تكرار ﴿بعض﴾ يبين تبادل الولاية بين فريقين من جنس الظالمين: بعضهم يتولى بعضًا، فلا تختص العلاقة بطرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص82، تحت «توجيه تعدية فعل التولية»","url":""}]},{"id":"s6-882","number":882,"surah":6,"verses":[129],"references":[{"surah":6,"verses":[129]}],"verseLabel":"الأنعام: 129","question":"ما بلاغة التعبير عن الكسب بالمضارع في قوله تعالى: ﴿يكسبون﴾؟","answer":"صوّر المضارع تجدد كسبهم للظلم والمعاصي واستمرارهم فيه مرة بعد مرة؛ فناسب تجدد الجزاء عليهم بهذا الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص84، تحت عنوان «بلاغة التعبير عن الكسب بالمضارع»","url":""}]},{"id":"s6-883","number":883,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا وُجه نداء واحد إلى ﴿معشر الجن والإنس﴾؟","answer":"لأن الفريقين اشتركا في التكليف والتكذيب والجزاء، وبلغتهما الرسالة؛ فجمعهما النداء في موقف واحد تقريعًا وإقامةً للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص89، تحت عنوان «توجيه نداء الجن والإنس»","url":""}]},{"id":"s6-884","number":884,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"كيف وُصف الرسل بأنهم ﴿منكم﴾ مع أن الرسل من الإنس؟","answer":"لأن الخطاب جمع الإنس والجن جماعتين، والرسل من أحد الفريقين، ولأن رسل الإنس بلغوا الجميع وقام من الجن منذرون ينقلون دعوتهم؛ فصح الوصف باعتبار المجموع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص90، تحت عنوان «بديع وصف الرسل بمنكم»","url":""}]},{"id":"s6-885","number":885,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا جُمع الرسل في قوله تعالى: ﴿رسل منكم يقصون عليكم آياتي﴾؟","answer":"لأن دعوة الرسل واحدة وآيات الله التي يبلغونها يصدق بعضها بعضًا؛ فجمعهم أبرز وحدة الرسالة وإقامة الحجة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص91، تحت عنوان «علة جمع الرسل بقوله تعالى: ﴿يقصون عليكم آياتي﴾»","url":""}]},{"id":"s6-1353","number":1353,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا اختير لفظ ﴿ينذرونكم﴾ في الحديث عن لقاء يوم القيامة؟","answer":"الإنذار إخبار مقرون بالتخويف والتحذير؛ فناسب لقاء يوم يحمل عاقبة التكذيب، وجمع مع قص الآيات بين بيان الحجة والتنبيه إلى جزائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص93، تحت عنوان «علة اصطفاء لفظ الإنذار»","url":""}]},{"id":"s6-886","number":886,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا عبّروا عن إقرارهم بقولهم ﴿شهدنا على أنفسنا﴾؟","answer":"لأن الشهادة تفيد تحقق الخبر وثبوته؛ فقد أقروا بأن الرسل بينوا لهم، وأنهم خالفوا هذا البيان. فصار اعترافهم شهادة ثابتة عليهم تقطع الاعتذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص96، تحت «دلالة استعمال الشهادة بمعنى الإقرار»","url":""}]},{"id":"s6-887","number":887,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"لماذا تكرر: ﴿وشهدوا على أنفسهم أنهم كانوا كافرين﴾؟","answer":"الجملة الأولى جوابهم عند السؤال وإقرارهم بقيام الحجة، والثانية حكاية من الله تثبت حقيقة شهادتهم وكفرهم بعد أن غرتهم الحياة الدنيا؛ فليست تكرارًا خاليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص98، تحت «سر تكرار ذكر شهادتهم على أنفسهم»","url":""}]},{"id":"s6-888","number":888,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"إلى ماذا يشير اسم الإشارة ﴿ذلك﴾، وما أثر افتتاح الآية به؟","answer":"يشير إلى إرسال الرسل وإنذار الأمم وإقامة الحجة؛ فجمع ما سبق في أمر عظيم، ثم بين أن ذلك من عدل الله كيلا يهلك قومًا قبل البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص103، تحت عنوان «توجيه الافتتاح باسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s6-889","number":889,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"لماذا اختير اسم الفاعل ﴿مهلك﴾؟","answer":"اسم الفاعل ﴿مهلك﴾ يدل على ثبوت الشأن والصفة في المقام، وينفي أن يكون من سنته إهلاك القرى على تلك الحال دون إنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص106، تحت «براعة التعبير باسم الفاعل مهلك»","url":""}]},{"id":"s6-890","number":890,"surah":6,"verses":[131],"references":[{"surah":6,"verses":[131]}],"verseLabel":"الأنعام: 131","question":"لماذا قُيّد نفي الإهلاك بحال ﴿وأهلها غافلون﴾؟","answer":"لأن الغفلة هنا عدم بلوغ إنذار الرسل؛ فلا يكون الهلاك قبل إقامة الحجة. فإذا جاءهم البيان زالت هذه الحال، فلا يبقى التعلل بالغفلة عذرًا للإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص110، تحت «وجه التعبير عن الفاصلة باسم الفاعل المجموع»","url":""}]},{"id":"s6-891","number":891,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل درجات مما عملوا﴾، فجمع الدرجات للفريقين؟","answer":"الدرجات تشمل مراتب الثواب والعقاب صعودًا وهبوطًا تغليبًا، فلكل من الإنس والجن منزلة تناسب عمله، ولا يستوي المحسن والمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص117–118، تحت «سر استعمال لفظ درجات مقابل لفظ دركات»","url":""}]},{"id":"s6-892","number":892,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"ما الذي يضيفه ربط الدرجات بالأعمال في ﴿ولكل درجات مما عملوا﴾؟","answer":"يجعل العمل منشأ المرتبة وسببها؛ فـ﴿من﴾ هنا للتعليل: لكل فريق درجات بسبب أعماله. وبذلك يرتبط التفاوت في الجزاء بما قدموه، فلا تكون المنازل اعتباطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص118، تحت «دلالة من في قوله تعالى مما عملوا»","url":""}]},{"id":"s6-893","number":893,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"لماذا نُفيت الغفلة باسم الفاعل في قوله تعالى: ﴿وما ربك بغافل﴾؟","answer":"أفاد اسم الفاعل ثبات نفي الغفلة ودوامه، فليس علم الله بأعمالهم علمًا عارضًا؛ وفي ذلك ضمان للجزاء ووعيد لمن ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص119، تحت عنوان «سر التعبير عن نفي الغفلة باسم الفاعل»","url":""}]},{"id":"s6-1354","number":1354,"surah":6,"verses":[132],"references":[{"surah":6,"verses":[132]}],"verseLabel":"الأنعام: 132","question":"كيف أكدت جملة ﴿وما ربك بغافل عما يعملون﴾ إحاطة علم الله؟","answer":"اجتمع فيها النفي والجملة الاسمية والباء الزائدة في خبرها واسم الرب المضاف إلى النبي؛ فاشتد نفي الغفلة وثبت أن أعمالهم كلها محصاة للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص123، تحت عنوان «بلاغة التوكيد في جملة الفاصلة»","url":""}]},{"id":"s6-894","number":894,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما بلاغة الاحتراس بقوله تعالى: ﴿ذو الرحمة﴾ بعد وصف الله بالغنى؟","answer":"منع هذا الوصف أن يُفهم من غناه عن الخلق أنه يهملهم أو يمنع فضله؛ فهو غني عنهم ومع ذلك يعاملهم برحمة وإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص129، تحت عنوان «بلاغة الاحتراس في قوله ذو الرحمة»","url":""}]},{"id":"s6-1355","number":1355,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"لماذا اقترنت صفتا ﴿الغني﴾ و﴿ذو الرحمة﴾ في هذا الموضع؟","answer":"الغنى يثبت أنه لا يحتاج إلى طاعتهم، والرحمة تبين أن إمهالهم وإحسانه إليهم فضل خالص؛ فاجتمعت القدرة على الاستبدال مع فتح باب التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص132–133، تحت عنوان «نكتة اختيار صفتي الغنى والرحمة واقترانهما في هذا الموضع»","url":""}]},{"id":"s6-895","number":895,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"لماذا قيل ﴿يذهبكم﴾ ولم يقل: يهلككم؟","answer":"الإذهاب أوسع؛ فقد يكون بالإهلاك أو بإزالة سلطان قوم واستخلاف غيرهم، ويصور زوالهم حتى يغيب أثرهم، فناسب سياق القدرة على الاستبدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص137، تحت عنوان «علة التعبير بلفظ يذهبكم دون غيره»","url":""}]},{"id":"s6-896","number":896,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿ويستخلف من بعدكم ما يشاء﴾، واستعمل ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لتعميم المستخلَف وإبهام جنسه وصفته؛ فالله قادر أن يأتي بعدهم بما يشاء من خلق لا يحيطون به، وفي ذلك تهديد أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص140، تحت «إيثار الموصول ما المستعمل لغير العاقل»","url":""}]},{"id":"s6-897","number":897,"surah":6,"verses":[133],"references":[{"surah":6,"verses":[133]}],"verseLabel":"الأنعام: 133","question":"ما بلاغة التشبيه في قوله تعالى: ﴿كما أنشأكم من ذرية قوم آخرين﴾؟","answer":"جعل نشأتهم بعد أمم سابقة شاهدًا محسوسًا على إمكان إذهابهم واستخلاف غيرهم؛ فما وقع في أصل وجودهم دليل على تحقق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص141، تحت عنوان «بلاغة التشبيه في الإنشاء»","url":""}]},{"id":"s6-898","number":898,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"لماذا كثرت أدوات التوكيد في قوله تعالى: ﴿إن ما توعدون لآت﴾؟","answer":"أكد الخبر بإن واللام والجملة الاسمية لأن المخاطبين ينكرون البعث والجزاء؛ فجاء التوكيد لمواجهة إنكارهم وتثبيت حتمية الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص150، تحت عنوان «بلاغة التوكيد بإن واللام والجملة الاسمية»","url":""}]},{"id":"s6-1356","number":1356,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"ما الصورة التي يرسمها قوله تعالى: ﴿إن ما توعدون لآت﴾؟","answer":"صوّر الموعود بشيء آتٍ يتجه إليهم لا محالة؛ فانتقل الوعد من معنى مؤجل إلى مشهد يقترب ويقع يقينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص151، تحت عنوان «بلاغة الاستعارة في قوله لآت»","url":""}]},{"id":"s6-899","number":899,"surah":6,"verses":[134],"references":[{"surah":6,"verses":[134]}],"verseLabel":"الأنعام: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أنتم بمعجزين﴾، دون أن يقال: ولن تفلتوا؟","answer":"المعجز هو الذي يفوت طالبه ويجعله عاجزًا عن إدراكه؛ فنفى أن يستطيعوا الإفلات من قدرة الله أينما كانوا، وهو أبلغ من مجرد نفي الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص154، تحت «بلاغة المجاز في لفظ معجزين»","url":""}]},{"id":"s6-900","number":900,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما دلالة الأمر في قوله تعالى: ﴿قل يا قوم اعملوا﴾ في الأنعام؟","answer":"الأمر للتهديد لا للإباحة؛ أي امضوا في طريقكم إن أصررتم، فستكشف العاقبة من تكون له الدار ومن يكون على الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص158–159، تحت «دلالة الأمر في المطلع، بقوله تعالى: ﴿قل يا قوم اعملوا﴾»","url":""}]},{"id":"s6-1415","number":1415,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما الكناية في قوله تعالى: ﴿اعملوا على مكانتكم﴾؟","answer":"كُنّي بالمكانة عن الحال والطريقة التي تمكنوا منها؛ فالمعنى: اثبتوا على أقصى ما تستطيعون من شأنكم، وستظهر العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص161، تحت «بلاغة الكناية في قوله تعالى: ﴿اعملوا على مكانتكم﴾»","url":""}]},{"id":"s6-1416","number":1416,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما غرض الأمر في قول شعيب: ﴿اعملوا﴾؟","answer":"هو تهديد بعد استنفاد النصح، لا إذن بالمعصية؛ أي استمروا على طريقكم إن أبيتم، فستعلمون من يأتيه الخزي ومن هو كاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص614، تحت «غرض الأمر في قوله تعالى: ﴿اعملوا﴾»","url":""}]},{"id":"s6-1417","number":1417,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"كيف يجمع التعبير بـ﴿مكانتكم﴾ بين الاستعارة والكناية؟","answer":"صوّر حالتهم وطريقتهم في الضلال كأنها مكان ثابت يقفون عليه، وكُنّي بذلك عن تمكنهم منها وإصرارهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص615، تحت «التعبير بـ﴿مكانتكم﴾ بين الاستعارة والكناية»","url":""}]},{"id":"s6-1418","number":1418,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]},{"surah":11,"verses":[93]}],"verseLabel":"الأنعام: 135؛ هود: 93","question":"ما سر التعبير باسم الفاعل في قوله: ﴿إني عامل﴾؟","answer":"يفيد ثبات شعيب على عمله واستمراره فيه، ويقابل إصرار قومه بإظهار رسوخ عزمه ويقينه بالعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص617، تحت «سر التعبير باسم الفاعل»","url":""}]},{"id":"s6-901","number":901,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"ما أثر توكيد قول الرسول: ﴿إني عامل﴾؟","answer":"ثبت بإن مضيه في العمل بما أمره الله به، وأزال توهم أن تهديد المعاندين قد يثنيه؛ فجمع ثباته مع تخويفهم من العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص163، تحت عنوان «توكيد العمل بإن في قوله إني عامل»","url":""}]},{"id":"s6-1357","number":1357,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا عبّر الرسول عن عمله باسم الفاعل فقال: ﴿إني عامل﴾؟","answer":"دل اسم الفاعل على ثبوت العمل واستمراره، فكأن ملازمته طريق الله صفة راسخة فيه لا قرارًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص164، تحت عنوان «توجيه صيغة التعبير عن العمل باسم الفاعل»","url":""}]},{"id":"s6-902","number":902,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا لم يُصرح بالعذاب في قوله تعالى: ﴿فسوف تعلمون﴾؟","answer":"حذف ما سيعلمونه لأن المقام يدل عليه، فزاد الإبهام رهبةً وترك النفس تتوقع ألوان الوعيد، مع بقاء العبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص165، تحت عنوان «سر عدم التصريح بالعذاب»","url":""}]},{"id":"s6-1358","number":1358,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا سيقت العاقبة في صورة محتملة: ﴿من تكون له عاقبة الدار﴾؟","answer":"جاءت العبارة في صورة منصفة لا تصرح من أولها بالفائز، مع يقين الرسول بالنتيجة؛ فجمعت حسن المحاورة والثقة بأن الواقع سيكشف الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص167، تحت عنوان «بلاغة الترديد»","url":""}]},{"id":"s6-1359","number":1359,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"لماذا قيل ﴿إنه لا يفلح الظالمون﴾ بدل: لا تفلحون؟","answer":"عدل إلى الاسم الظاهر ليجعل الحكم قاعدة عامة معللة بالظلم، وليدخل المخاطبون فيها بوصفهم لا بمجرد خطابهم؛ فكان أبلغ في التعريض والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص172، تحت عنوان «نكتة العدول عن المضمر إلى المظهر في جملة الفاصلة»","url":""}]},{"id":"s6-903","number":903,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"ما بلاغة التعريض في قوله تعالى: ﴿إنه لا يفلح الظالمون﴾؟","answer":"لم يقل لهم مباشرة إنكم لا تفلحون، بل قرر قاعدة عامة تشمل كل ظالم؛ فدخلوا فيها من طريق وصفهم، وكان ذلك أبلغ في تقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص170، تحت عنوان «بلاغة التعريض في إنه لا يفلح الظالمون»","url":""}]},{"id":"s6-1360","number":1360,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"كيف عللت جملة ﴿إنه لا يفلح الظالمون﴾ الوعيد السابق؟","answer":"بينت أن عاقبة الدار ليست لهم لأن الشرك والتكذيب ظلم، وسنة الله أن الظالم لا يبلغ الفلاح؛ فربطت النتيجة بسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص172، تحت عنوان «دلالة التعليل في جملة التذييل»","url":""}]},{"id":"s6-904","number":904,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا اختير لفظ ﴿ذرأ﴾ في قوله تعالى: ﴿مما ذرأ من الحرث والأنعام﴾؟","answer":"الذرء خلق مع إظهار وإكثار وبث؛ فذكّرهم اللفظ بأن الحرث والأنعام التي قسموها خلقها الله ونشرها لهم، فلا حق لهم في التشريع من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص179، تحت عنوان «إيثار لفظ ذرأ من الآية الكريمة»","url":""}]},{"id":"s6-1361","number":1361,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما بلاغة قوله تعالى: ﴿مما ذرأ من الحرث والأنعام﴾ بدل الاكتفاء بذكر الحرث والأنعام؟","answer":"أضاف الوصف تذكيرًا بأن المقسوم من خلق الله وملكه، ففضح تناقضهم حين جعلوا لبعض ما خلقه نصيبًا لشركائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص180، تحت عنوان «بلاغة الإطناب في عبارة مما ذرأ»","url":""}]},{"id":"s6-905","number":905,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما دلالة قولهم: ﴿هذا لله بزعمهم وهذا لشركائنا﴾ مع تكرار اسم الإشارة؟","answer":"تكرار اسم الإشارة يفصل النصيبين فصلًا حسيًا كأنهما موضوعان أمامهم، ويكشف اصطناعهم قسمة بين الله وشركائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص183، تحت «علة التعبير باسمي الإشارة في الآية الكريمة»","url":""}]},{"id":"s6-906","number":906,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا قُيّد نصيب الله وحده بـ﴿بزعمهم﴾؟","answer":"قُيّد نصيب الله بـ﴿بزعمهم﴾ لأن أصل جعل نصيب لله على هذا الوجه تشريع باطل من عندهم، أما نسبة القسم الآخر لشركائهم فهي حكاية مباشرة لمقصودهم الفاسد، والزعم ينسحب على القسمة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص185–186، تحت «نكتة مجيء لفظ الزعم إثر قولهم هذا لله دون قولهم وهذا لشركائنا»","url":""}]},{"id":"s6-907","number":907,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما المحذوف في قوله تعالى: ﴿فما كان لشركائهم فلا يصل إلى الله﴾، ولماذا حُذف؟","answer":"حُذف جواب صورة اختلاط نصيب الشركاء بنصيب الله، أي أبقوه للشركاء ولم يردوه؛ دل عليه السياق، فكان الحذف أوجز وأشد كشفًا لانحيازهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص187، تحت عنوان «بيان الحذف في فما كان لشركائهم»","url":""}]},{"id":"s6-908","number":908,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"لماذا أوثر ﴿ساء﴾ على ﴿بئس﴾ في قوله تعالى: ﴿ساء ما يحكمون﴾؟","answer":"لأن ﴿ساء﴾ تجري مجرى الفعل وتستدعي حكمًا متجددًا قبيحًا، فناسبت تقريعهم على فعل الحكم نفسه، مع شمولها ذم حكمهم ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص189، تحت عنوان «علة إيثار ساء على بئس»","url":""}]},{"id":"s6-1362","number":1362,"surah":6,"verses":[136],"references":[{"surah":6,"verses":[136]}],"verseLabel":"الأنعام: 136","question":"ما بلاغة تذييل الآية بقوله تعالى: ﴿ساء ما يحكمون﴾؟","answer":"ختمت القصة بحكم جامع يذم قسمة المشركين كلها؛ فهي تشريع بلا إذن، وجور في التطبيق، وإساءة إلى أنفسهم ودينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص190، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s6-909","number":909,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا أُسند تزيين قتل الأولاد إلى ﴿شركائهم﴾؟","answer":"لأن الشياطين والكهنة وسدنة الأصنام هم الذين حسّنوا لهم الجريمة وشرعوها وأشاعوا مبرراتها؛ فكشف الإسناد أن الشرك كان طريقهم إلى هذا الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص199، تحت عنوان «نكتة إسناد التزيين إلى الشركاء»","url":""}]},{"id":"s6-910","number":910,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا قُدّم ﴿قتل أولادهم﴾ على فاعل التزيين ﴿شركاؤهم﴾؟","answer":"لأن القتل هو موضع العناية والتعجيب: كيف يزيّن لهم قتل أحب الناس إليهم؟ فإبرازه أولًا يكشف بشاعة ما أقدموا عليه، ثم يأتي ذكر الشركاء الذين زينوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص198–199، تحت «نكتة تقديم المفعول قتل على الفاعل شركاؤهم»","url":""}]},{"id":"s6-911","number":911,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"لماذا قُدّم الإرداء على إلباس الدين في قوله تعالى: ﴿ليردوهم وليلبسوا عليهم دينهم﴾؟","answer":"لأن الإرداء يصور الغاية الأشد، وهي إهلاكهم وإسقاطهم، ثم جاء إلباس الدين لبيان الطريق المؤدي إليها من خلط الحق بالباطل؛ فرتب الغاية الخطرة قبل وسيلتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص201، تحت عنوان «سر تقديم (الإرداء) على (الإلباس)»","url":""}]},{"id":"s6-1363","number":1363,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"ما الصورة التي يرسمها الجمع بين ﴿ليردوهم﴾ و﴿ليلبسوا عليهم دينهم﴾؟","answer":"يجمع التعبيران بين إسقاط الإنسان في الهلاك وإلباس دينه حتى يختلط عليه؛ فصُوّر إفساد النفس والدين معًا، بما في الإرداء من استعارة للسقوط وفي الإلباس من تصوير للخلط والستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص202، تحت عنوان «توجيه لفظي: (الإرداء)، و(الإلباس) بين التورية، والاستعارة، والمجاز»","url":""}]},{"id":"s6-912","number":912,"surah":6,"verses":[137],"references":[{"surah":6,"verses":[137]}],"verseLabel":"الأنعام: 137","question":"هل يعني قوله تعالى: ﴿فذرهم وما يفترون﴾ ترك دعوتهم إلى الحق؟","answer":"المراد الإعراض عن باطلهم وترك الاهتمام بغرورهم، مع وعيدهم على افترائهم؛ وليس المراد الكف عن دعوتهم إلى الحق، فالإعراض عن الافتراء لا يلغي البلاغ والتذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص205، تحت «اصطفاء كلمة: ﴿فذرهم﴾، ودلالته في الجملة الإنشائية»","url":""}]},{"id":"s6-913","number":913,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا وصفوا الأنعام والحرث بـ﴿حجر﴾؟","answer":"الحِجر هو المنع والتحجير؛ وصفوا الأنعام والحرث به لأنهم جعلوها محظورة لا يأكلها إلا من يختارونه، كأن المنع صفة ثابتة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص217–218، تحت «سر اختيار كلمة: ﴿حجر﴾»","url":""}]},{"id":"s6-914","number":914,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا تكرر ﴿أنعام﴾ ثلاث مرات؟","answer":"تكررت ﴿أنعام﴾ لأن كل جملة تتناول طائفة ذات حكم مستقل اخترعوه: ممنوعة الأكل، أو محرمة الظهور، أو لا يذكرون اسم الله عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص230، تحت «الغرض من تكرار لفظ (أنعام)، في سياق النكرة»","url":""}]},{"id":"s6-915","number":915,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ماذا يكشف إسناد المنع إلى مشيئتهم في قولهم: ﴿لا يطعمها إلا من نشاء﴾؟","answer":"يكشف أنهم جعلوا التحليل والتحريم تابعين لأهوائهم، واغتصبوا حق التشريع من غير وحي؛ ففضح لفظ المشيئة تحكمهم في رزق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص222، تحت عنوان «دلالة اصطفاء فعل المشيئة وإيحاءاته المعنوية»","url":""}]},{"id":"s6-1364","number":1364,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا قالوا ﴿نشاء﴾ بالمضارع لا بالماضي؟","answer":"لأن المضارع يصور مشيئة تتجدد كلما أرادوا منع أحد أو الإذن له، فكأن التشريع عندهم قرار متكرر تحكمه الأهواء لا حكم ثابت من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص223، تحت عنوان «نكتة اختيار الفعل ﴿نشاء﴾ مضارعًا لا ماضيًا»","url":""}]},{"id":"s6-916","number":916,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"لماذا اقتصر التحريم المزعوم على ذكر ﴿ظهورها﴾؟","answer":"لأن الظهر موضع الركوب والحمل، وهما أبرز وجوه الانتفاع التي منعوها؛ فذكر الظهور كناية عن حظر استعمال تلك الأنعام في الحمل والركوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص232، تحت عنوان «علة الاقتصار على ذكر (الظهور) دون سائرها»","url":""}]},{"id":"s6-917","number":917,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ما الذي يضيفه قوله تعالى: ﴿افتراء عليه﴾ إلى وصف تحريمهم للأنعام؟","answer":"يبين أن جريمتهم لم تقف عند تحريم الرزق، بل تجاوزته إلى اختلاق حكم ونسبته إلى الله؛ فصار فعلهم كذبًا متعمدًا على المشرّع سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص237–238، تحت عنوان «مغزى قوله سبحانه في الآية: ﴿افتراء عليه﴾»","url":""}]},{"id":"s6-1365","number":1365,"surah":6,"verses":[138],"references":[{"surah":6,"verses":[138]}],"verseLabel":"الأنعام: 138","question":"ما دلالة تذييل الآية بقوله تعالى: ﴿سيجزيهم بما كانوا يفترون﴾؟","answer":"حوّل كشف افترائهم إلى وعيد بالجزاء، وربط العقوبة بما داوموا على اختلاقه؛ فختم بيان الجريمة بإثبات عاقبتها المحتومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص239، تحت عنوان «مغزى تذييل الآية بجملة الجزاء، ودلالة ذلك»","url":""}]},{"id":"s6-918","number":918,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا عبّروا بقولهم ﴿خالصة لذكورنا﴾ بدل حلال أو خاص؟","answer":"لأن ﴿خالصة﴾ تفيد أنهم زعموا قصر ما في البطون على الذكور قصرًا تامًا لا تشاركهم فيه النساء؛ فتكشف شدة تحكمهم في القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص254، تحت عنوان «وجه التعبير بـ﴿خالصة﴾ على (حلال) و(خاص)»","url":""}]},{"id":"s6-1366","number":1366,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"كيف عرّضت الآية بذم أصحاب هذا التحريم ومن يتبعهم؟","answer":"حكت تناقض حكمهم نفسه: يخصون الذكور بما في البطون، ويحرمونه على النساء، ثم يشركونهم فيه إن خرج ميتًا؛ فكان عرض التناقض أبلغ في ذمهم وذم من يسلك طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص261، تحت عنوان «بلاغة الآية في التعريض بذم القائلين، ومن لف لفهم»","url":""}]},{"id":"s6-919","number":919,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا قالوا: ﴿خالصة لذكورنا﴾ بالتأنيث ثم ﴿ومحرم على أزواجنا﴾ بالتذكير؟","answer":"من توجيه ذلك أن التأنيث في ﴿خالصة﴾ راعى معنى ﴿ما﴾، أي الأجنة، ثم راعى التذكير في ﴿محرم﴾ لفظ ﴿ما﴾. ويذكر المصدر وجهًا آخر: أن التاء في ﴿خالصة﴾ للمبالغة؛ فلا تكون المقابلة حينئذ اختلافًا في مراعاة جنس الموصوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص254–255، تحت «علة تأنيث ﴿خالصة﴾، وتذكير ﴿ومحرم﴾»","url":""}]},{"id":"s6-920","number":920,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"لماذا قيل في الميتة ﴿فهم فيه شركاء﴾ بدل أن يقال: فهم سواء؟","answer":"لأن الشراكة تصور اجتماع الذكور والإناث في الانتفاع بالشيء نفسه بعد أن زعموا اختصاص الذكور به حيًا؛ فكان اللفظ أكشف لتناقض حكمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص260–261، تحت عنوان «علة إيراد الخبر كلمة ﴿شركاء﴾ دون (سواء)»","url":""}]},{"id":"s6-921","number":921,"surah":6,"verses":[139],"references":[{"surah":6,"verses":[139]}],"verseLabel":"الأنعام: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿سيجزيهم وصفهم﴾، فجعل الوصف نفسه مجزيًا؟","answer":"فيه حذف مضاف أو مجاز؛ أي سيجزيهم جزاء وصفهم الكاذب، وجُعل الوصف نفسه كأنه الجزاء لمبالغة في تحقق العقوبة وملازمتها لافترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص263–264، تحت «نكتة الإيجاز بالحذف، في جعل الجزاء متعديًا للوصف بنفسه»","url":""}]},{"id":"s6-922","number":922,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا وصف قتل الأولاد وتحريم الرزق بأنه ﴿سفهًا﴾؟","answer":"لأن السفه خفة عقل تحمل صاحبها على ما يضره؛ وقتل الأولاد وإبطال نعم الله خسارة لا تصدر عن رأي رشيد، ففضح اللفظ فساد تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص274، تحت عنوان «علة إيثار لفظ السفه»","url":""}]},{"id":"s6-1367","number":1367,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"ماذا يضيف الجمع بين ﴿سفهًا﴾ و﴿بغير علم﴾؟","answer":"كشف القيدان فسادهم من جهتين: السفه يبين خفة العقل وسوء القصد، وغياب العلم ينفي الوحي والبرهان؛ فلا حكمة في فعلهم ولا حجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص275–276، تحت عنوان «دلالة الجمع بين الحالين ﴿سفهًا﴾ و﴿بغير علم﴾»","url":""}]},{"id":"s6-923","number":923,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا صُرّح باسم ﴿الله﴾ في قوله تعالى: ﴿ما رزقهم الله﴾؟","answer":"ليظهر التناقض بين رازق النعمة ومن يحرمها؛ فما دام الله هو الذي رزقهم فلا يملك أحد أن ينسب إليه منعها بغير وحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص277، تحت عنوان «إيثار الاسم الأعظم ﴿الله﴾ في قوله تعالى ﴿رزقهم الله﴾»","url":""}]},{"id":"s6-924","number":924,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا وُضع اسم ﴿الله﴾ ظاهرًا في قوله تعالى: ﴿افتراء على الله﴾ بدل الضمير؟","answer":"لتهويل جريمتهم؛ فهم لم يكذبوا على مجهول، بل نسبوا تشريعهم إلى الله صاحب الحق وحده في التحليل والتحريم، فكان التصريح أبلغ في التقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص279، تحت عنوان «سر وضع الاسم الظاهر ﴿الله﴾ موضع الضمير»","url":""}]},{"id":"s6-925","number":925,"surah":6,"verses":[140],"references":[{"surah":6,"verses":[140]}],"verseLabel":"الأنعام: 140","question":"لماذا جمع بين ﴿قد ضلوا﴾ و﴿وما كانوا مهتدين﴾؟","answer":"﴿قد ضلوا﴾ يثبت وقوعهم في الضلال، و﴿وما كانوا مهتدين﴾ ينفي عنهم أصل الاهتداء واستمراره؛ فجمع إثبات الفساد ونفي ضده توكيدًا لتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص281–282، تحت «الوصل بين الجملتين الأخيرتين بالواو العاطفة؛ دلالة النفي بـ(ما) دون (لم)، قبل (كان) الماضية»","url":""}]},{"id":"s6-926","number":926,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما مغزى الوصف بلفظي ﴿معروشات وغير معروشات﴾؟","answer":"المعروشات ما يُرفع نباتها على عروش أو ما يعتني الناس بإنشائه، وغير المعروشات ما يقوم على سوقه أو ينبت دون تعريش؛ فالمقابلة تستوعب صور الجنات وتنوع الصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص295–296، تحت «مغزى الوصف بلفظي ﴿معروشات وغير معروشات﴾»","url":""}]},{"id":"s6-927","number":927,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما الحكمة من ترتيب النخل والزرع والزيتون والرمان في الآية؟","answer":"قُدّم النخل والزرع لأنهما أصل القوت وأوسع نفعًا، وقدم النخل لما له من ثمرة وغذاء متجدد، ثم جاء الزيتون والرمان من الفواكه المكملة؛ فانتظم التعداد بحسب الحاجة والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص298–299، تحت عنوان «بلاغة ترتيب المتعاطفات»","url":""}]},{"id":"s6-928","number":928,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما بلاغة التعقيب بقوله تعالى: ﴿مختلفًا أكله﴾ بعد ذكر أصناف النبات؟","answer":"نقل النظر من مجرد تعداد النبات إلى تنوع طعمه ولونه وهيئته ومنافعه، فصار الاختلاف نفسه آية تدعو إلى التفكر في دقة الخلق وسعة النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص301–302، تحت عنوان «بلاغة التعقيب بالحال على أصناف المأكولات»","url":""}]},{"id":"s6-929","number":929,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"لماذا قيل في آية: ﴿انظروا إلى ثمره﴾، وفي الأخرى: ﴿كلوا من ثمره﴾؟","answer":"لأن الأولى في سياق الاستدلال بخلق النبات فناسبها النظر والاعتبار، والثانية في سياق إباحة الطيبات وإبطال التحريم المفتَرى فناسبها الأكل؛ فاختار كل موضع ما يخدم غرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص309–310، تحت عنوان «بيان التشابه بين الفعلين: ﴿كلوا﴾ و﴿انظروا﴾»","url":""}]},{"id":"s6-930","number":930,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما دلالة الأمر في قوله تعالى: ﴿كلوا من ثمره إذا أثمر﴾؟","answer":"هو إذن بالانتفاع وإبطال لما ابتدعه المشركون من التحريم، وفيه امتنان بالرزق مع تذكيرهم أن الإباحة من الله لا من أهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص309، تحت عنوان «دلالة الأمر في قوله: ﴿كلوا﴾»","url":""}]},{"id":"s6-931","number":931,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"لماذا أعقب الأمر بالأكل وإيتاء الحق بالنهي عن الإسراف؟","answer":"حتى لا تتحول النعمة أو الصدقة إلى تجاوز للحد؛ فالمطلوب انتفاع معتدل وأداء للحق بلا تبذير ولا إتلاف ولا منع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص311، تحت عنوان «دلالة النهي عن الإسراف»","url":""}]},{"id":"s6-1368","number":1368,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما أثر توكيد الفاصلة: ﴿إنه لا يحب المسرفين﴾؟","answer":"ثبّت أن النهي ليس إرشادًا عابرًا، بل حد يحبه الله لعباده؛ وربط الإسراف بحرمان محبته فاشتد الزجر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص312، تحت عنوان «بلاغة التوكيد في جملة الفاصلة»","url":""}]},{"id":"s6-932","number":932,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا سميت كبار الأنعام ﴿حمولة﴾؟","answer":"لأنها تحمل الأثقال ويركبها الناس، فاختار لها الاسم الذي يستحضر أبرز منفعتها وقوتها، ويذكّر بما سخره الله لهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص321، تحت عنوان «توجيه التعبير بـ﴿حمولة﴾ في الآية الكريمة»","url":""}]},{"id":"s6-1369","number":1369,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا عبّر عن صغار الأنعام بلفظ ﴿فرشًا﴾؟","answer":"لأنها لقربها من الأرض وصغرها كأنها مفروشة عليها، وقيل لما يُفرش من أصوافها؛ فجمع اللفظ صورة صغرها وما ينتفع به منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص322–323، تحت عنوان «علة التعبير بالفرش من الإبل»","url":""}]},{"id":"s6-933","number":933,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"ما بلاغة التصريح باسم ﴿الله﴾ في قوله تعالى: ﴿مما رزقكم الله﴾؟","answer":"ذكّر بأن الأنعام والرزق عطية من الله، فاستوجب شكره واتباع حكمه، وفضح من ينسب إلى نفسه حق تحريم ما رزقه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص325، تحت عنوان «بلاغة التصريح بلفظ الجلالة ﴿الله﴾»","url":""}]},{"id":"s6-934","number":934,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا صُورت وساوس الشيطان بـ﴿خطوات﴾؟","answer":"تصور اتباع الشيطان في التحريم الباطل بصورة من يتبع آثار سائر في طريق معوج وخطر؛ فالمقصود التحذير من سلوك طريقه كما يحذر العاقل من تقفي خطوات من يسلك مسلك الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص326، تحت «بلاغة الاستعارة التمثيلية في ﴿خطوات الشيطان﴾»","url":""}]},{"id":"s6-935","number":935,"surah":6,"verses":[142],"references":[{"surah":6,"verses":[142]}],"verseLabel":"الأنعام: 142","question":"لماذا وُصفت عداوة الشيطان بأنها ﴿مبين﴾؟","answer":"لأن آثارها ظاهرة في إغوائه وإفساده وعداوته للإنسان، فلا عذر لمن يتبع خطوات عدو انكشف قصده وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص327، تحت عنوان «نكتة وصف عداوة الشيطان بأنه ﴿مبين﴾»","url":""}]},{"id":"s6-936","number":936,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا فُصّلت الأنعام نوعًا نوعًا بعد إجمالها في ﴿ثمانية أزواج﴾؟","answer":"لإحاطة الحجة بكل صنف ومنع المشركين من الاحتماء بإجمال الدعوى؛ فذُكر من الضأن والمعز والإبل والبقر ذكر وأنثى، ثم سئلوا عن دليل تحريم أي واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص333، تحت عنوان «دلالة الإطناب بالتفصيل بعد الإجمال»","url":""}]},{"id":"s6-1370","number":1370,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"ما الصورة التي أفادها إطلاق ﴿أزواج﴾ على أصناف الأنعام؟","answer":"استعمل الزوج في كل فرد يقترن بنظيره من ذكر وأنثى، فصوّر الأنواع في نظام من التقابل والتكامل، وبيّن أن الثمانية أربعة أصناف من كل صنف اثنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص334–335، تحت عنوان «بلاغة الاستعارة في لفظ ﴿أزواج﴾»","url":""}]},{"id":"s6-937","number":937,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا بدأ بالضأن ثم المعز؟","answer":"يذكر المصدر تقديم الضأن لطيب لحمها وعظم الانتفاع بصوفها؛ فالتقديم يلفت إلى ما تمتاز به من منفعة محسوسة، ضمن تفصيل الأنعام التي أبطل القرآن تحريمها بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص335، تحت «فائدة التفصيل في قوله: ﴿من الضأن اثنين ومن المعز اثنين﴾»","url":""}]},{"id":"s6-938","number":938,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"كيف يبطل سؤال ﴿قل آلذكرين حرم أم الأنثيين﴾ دعوى المشركين؟","answer":"يحصر أمامهم وجوه التحريم: أللذكورة أم للأنوثة أم لما في الأرحام؟ وكل جواب يلزمهم بتعميم لا يقولون به؛ فينكشف أن تخصيصهم بعض الأنعام بلا دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص336–337، تحت عنوان «دلالة الوضع البياني لقوله: ﴿قل آلذكرين حرم﴾»","url":""}]},{"id":"s6-939","number":939,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا نُكّر لفظ ﴿علم﴾ في قوله تعالى: ﴿نبئوني بعلم﴾؟","answer":"ليطالبهم بأي قدر معتبر من البرهان، ولو كان قليلًا؛ فلما عجزوا عن أدنى علم ظهر أن تحريمهم دعوى لا أصل لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص340–341، تحت عنوان «نكتة تنكير لفظ (علم)»","url":""}]},{"id":"s6-1371","number":1371,"surah":6,"verses":[143],"references":[{"surah":6,"verses":[143]}],"verseLabel":"الأنعام: 143","question":"لماذا قيل ﴿نبئوني﴾ ولم يكتف بطلب الخبر؟","answer":"لأن النبأ خبر ذو شأن وفائدة يقتضي العلم والوضوح، فناسب تحديهم أن يأتوا بخبر عظيم موثق يثبت دعوى التحريم، لا بمجرد قول يتناقلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص343–344، تحت عنوان «(النبأ) و(الخبر)»","url":""}]},{"id":"s6-940","number":940,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"ما دلالة الانتقال بقوله تعالى: ﴿ومن الإبل اثنين ومن البقر اثنين﴾؟","answer":"أتم الانتقال استيعاب الأزواج الثمانية، ونقل الحجة نفسها من الضأن والمعز إلى الإبل والبقر حتى لا يبقى صنف تعلق به تحريمهم خارج المحاكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص348–349، تحت عنوان «دلالة العطف في قوله تعالى: ﴿ومن الإبل اثنين﴾»","url":""}]},{"id":"s6-941","number":941,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا انتقل الخطاب إلى سؤالهم: ﴿أم كنتم شهداء إذ وصاكم الله بهذا﴾؟","answer":"بعد إسقاط حجتهم العقلية سألهم عن آخر طريق ممكن للعلم: هل شهدوا وحي الله؟ والاستفهام الإنكاري يفضح أنهم لا يملكون دليلًا ولا شهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص350–351، تحت عنوان «دلالة الاستفهام في قوله: ﴿أم كنتم شهداء﴾»","url":""}]},{"id":"s6-942","number":942,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا قُيّد إضلال الناس بقوله تعالى: ﴿بغير علم﴾؟","answer":"ليكشف أن من نسب التحريم إلى الله لم يعتمد وحيًا ولا برهانًا، بل أضل الناس بجهل وافتراء؛ فالقيد يسجل فساد المصدر وسوء الأثر معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص357–358، تحت عنوان «علة مجيء القيد ﴿بغير علم﴾»","url":""}]},{"id":"s6-943","number":943,"surah":6,"verses":[144],"references":[{"surah":6,"verses":[144]}],"verseLabel":"الأنعام: 144","question":"لماذا ختمت الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"لأن افتراء التشريع وإضلال الناس ظلم، ومن يصر على هذا الطريق يسد على نفسه باب هداية التوفيق؛ فجاءت الفاصلة جزاء مناسبًا للفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص358–359، تحت عنوان «مناسبة الفاصلة لما قبلها»","url":""}]},{"id":"s6-944","number":944,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ما الصورة التي يفيدها قوله تعالى: ﴿لا أجد فيما أوحي إلي محرمًا﴾؟","answer":"صوّر مراجعة الوحي والبحث فيه حتى كأن الحكم شيء يطلب ويعثر عليه؛ والنتيجة أنه لا تحريم فيه إلا لما نص الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص369، تحت عنوان «نكتة المجاز في الفعل ﴿لا أجد﴾»","url":""}]},{"id":"s6-1372","number":1372,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"كيف أدمجت الآية الرد على المشركين في بيان المحرمات للمسلمين؟","answer":"بينما تسرد الآية ما حُرّم حقًا، جاء قول ﴿لا أجد﴾ ردًا ضمنيًا على تحريم المشركين؛ فجمع السياق تعليم المؤمنين وإبطال الافتراء في عبارة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص369–370، تحت عنوان «بلاغة إدماج في سياق ذكر ما حرم على المسلمين»","url":""}]},{"id":"s6-945","number":945,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قيل ﴿على طاعم يطعمه﴾ بدل آكل يأكله؟","answer":"لأن الطعم يشمل كل ما يتناوله الإنسان غذاءً، ويستحضر الذوق والانتفاع؛ فعمم الحكم في كل طاعم وأكد أن التحريم متعلق بتناول الشيء طعامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص371–372، تحت عنوان «سر التعبير بـ﴿على طاعم يطعمه﴾ بدل (آكل يأكله)»","url":""}]},{"id":"s6-946","number":946,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قُيد الدم بـ﴿مسفوحًا﴾؟","answer":"المسفوح هو الدم الجاري المصبوب عند الذبح؛ فالقيد يخرج الدم الباقي في العروق واللحم مما لا يمكن الاحتراز منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص375، تحت «علة تقييد الدم بـ(المسفوح)»","url":""}]},{"id":"s6-947","number":947,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا وصف لحم الخنزير بأنه ﴿رجس﴾؟","answer":"لأن الرجس ما تستقذره الفطرة ويجب اجتنابه، فبيّن اللفظ خبث المحرّم وشدة النفرة منه، ولم يكتف بمجرد ذكر المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص377، تحت عنوان «نكتة ذكر لفظ ﴿رجس﴾»","url":""}]},{"id":"s6-948","number":948,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا وصف ما أُهل لغير الله به بأنه ﴿فسقًا﴾؟","answer":"لأن الفسق خروج عن طاعة الله، والذبح باسم غيره يجمع المعصية والشرك؛ فجعله اللفظ عين الفسق مبالغة في كشف قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص378، تحت عنوان «سر التعبير بلفظ (الفسق)»","url":""}]},{"id":"s6-949","number":949,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ماذا يفيد ختم حكم المضطر بقوله تعالى: ﴿غفور رحيم﴾؟","answer":"يبين أن الله رفع الإثم عمن ألجأته الضرورة من غير بغي ولا تجاوز؛ فالمغفرة تمحو المؤاخذة، والرحمة أباحت ما يحفظ الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص384–385، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿غفور رحيم﴾»","url":""}]},{"id":"s6-950","number":950,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ما دلالة التعريف في كلمة ﴿والدم﴾ في آية المائدة؟","answer":"التعريف للعهد؛ فالمراد الدم المعهود الذي بينته آية الأنعام بأنه المسفوح، لا كل أثر من الدم يبقى في اللحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص533–534، تحت «دلالة (الـ) في كلمة ﴿والدم﴾»","url":""}]},{"id":"s6-1419","number":1419,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"لماذا قُيِّد الدم في آية الأنعام بكونه ﴿مسفوحًا﴾؟","answer":"ليختص التحريم بالدم السائل المصبوب، ويخرج الدم الذي يبقى في العروق أو يخالط اللحم ولا يمكن الاحتراز منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص375، تحت «علة تقييد الدم بـ(المسفوح)»","url":""}]},{"id":"s6-951","number":951,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا خص ﴿الذين هادوا﴾ بتحريم كل ذي ظفر؟","answer":"خُص اليهود لأن التحريم كان عقوبة لهم على بغيهم، لا حكمًا أصليًا عامًا في جميع الأمم؛ فالتخصيص يمهد لتعليل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص392–393، 396–397، تحت «نكتة تقديم شبه الجملة على متعلقها؛ الموقع البياني لقوله: ﴿ذلك جزيناهم ببغيهم﴾؛ معنى الباء في عبارة ﴿ببغيهم﴾»","url":""}]},{"id":"s6-952","number":952,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا جُمعت شحوم البقر والغنم ثم استثنيت ثلاثة مواضع؟","answer":"ذُكر التحريم أولًا، ثم فُصلت مواضع الاستثناء: ما تعلق بالظهور، والحوايا، وما اختلط بعظم. فانتقل البيان من الإجمال إلى تعيين المستثنى، ليُعرف موضع التحريم وموضع الإباحة، ولا يعمم أحد الحكمين على جميع الشحوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص394–396، تحت «دلالة الاستثناء في قوله: ﴿إلا ما حملت ظهورهما﴾؛ إفادة ﴿أو﴾ معنى العطف أو الإباحة في قوله ﴿أو الحوايا﴾؛ معنى الباء في قوله: ﴿أو ما اختلط بعظم﴾»","url":""}]},{"id":"s6-953","number":953,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"لماذا جُعل تحريم بعض الطيبات على اليهود جزاءً لبغيهم؟","answer":"لأنه عقوبة على تجاوزهم وعصيانهم؛ فسُلبوا بعض ما كان حلالًا لهم، وربط قوله ﴿ببغيهم﴾ شدة الحكم بسببها حتى لا يظن أنه تشريع عام أصلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص396–397، تحت عنوان «الموقع البياني لقوله: ﴿ذلك جزيناهم ببغيهم﴾»","url":""}]},{"id":"s6-954","number":954,"surah":6,"verses":[146],"references":[{"surah":6,"verses":[146]}],"verseLabel":"الأنعام: 146","question":"ما أثر تتابع المؤكدات في قوله تعالى: ﴿وإنا لصادقون﴾؟","answer":"اجتمعت إن واللام والجملة الاسمية لتثبيت صدق الخبر والرد على تكذيب اليهود وتحريفهم سبب التحريم؛ فلا يبقى مجال للشك في أن الحكم جزاء بغيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص397–398، تحت عنوان «بلاغة تتابع المؤكدات للمبالغة»","url":""}]},{"id":"s6-955","number":955,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"لماذا أُخبر المكذبون بأن ربهم ﴿ذو رحمة واسعة﴾؟","answer":"ليفتح لهم باب الرجاء قبل الوعيد؛ فإمهالهم مع التكذيب مظهر من رحمته ودعوة إلى التوبة، لا علامة رضا عن باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص406، تحت عنوان «فائدة الإخبار عن الرب بقوله ﴿ذو رحمة واسعة﴾»","url":""}]},{"id":"s6-1373","number":1373,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"ما الذي يوحي به وصف رحمة الله بأنها ﴿واسعة﴾؟","answer":"يوحي بأنها تعم الخلق وتسبق العقوبة، فلا يضيق بها ذنب من رجع إلى الله؛ ومع سعتها لا يجوز الاغترار بها والإصرار على التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص408، تحت عنوان «نكتة وصف رحمة الله تعالى بالاتساع»","url":""}]},{"id":"s6-956","number":956,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"ما الذي تضيفه كلمة ﴿ذو﴾ في قوله: ﴿ربكم ذو رحمة واسعة﴾؟","answer":"يبين المصدر أن ﴿ذو﴾ تدل هنا على ملازمة الصفة وثبوتها، وتضاف إلى اسم يدل على معنى كالرحمة والعلم. فالتعبير يقرر أن الرحمة صفة ثابتة لله، ثم يأتي وصفها بالسعة ليزيد الرجاء في رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص407، تحت «نكتة التعبير بـ﴿ذو﴾ دون (صاحب)»","url":""}]},{"id":"s6-957","number":957,"surah":6,"verses":[147],"references":[{"surah":6,"verses":[147]}],"verseLabel":"الأنعام: 147","question":"لماذا عُبر عن الرحمة بالجملة الاسمية وعن البأس بالجملة الفعلية؟","answer":"لأن الرحمة صفة ثابتة واسعة لربهم، فناسبها الأسلوب الدال على الثبوت؛ أما البأس فوعيد بحدث يقع إذا أصر المجرمون، فناسبه التعبير بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص409، تحت عنوان «مناسبة التعبير عن اتساع رحمة الله بالجملة الاسمية، وعن الترهيب بالجملة الفعلية»","url":""}]},{"id":"s6-958","number":958,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما دلالة احتجاج المشركين بقولهم: ﴿لو شاء الله ما أشركنا﴾؟","answer":"أرادوا أن يجعلوا وقوع الشرك والتحريم دليلًا على رضا الله بهما، وأن يسقطوا مسؤوليتهم بالمشيئة؛ فخلطوا بين مشيئة وقوع الشيء وبين محبته والأمر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص417، تحت عنوان «دلالة احتجاج المشركين بالمشيئة»","url":""}]},{"id":"s6-1374","number":1374,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا سمّى القرآن احتجاجهم بالمشيئة تكذيبًا؟","answer":"لأنهم لم يكتفوا بالمعصية، بل نسبوا إلى الله الرضا بها واتخذوا مشيئته حجة على باطلهم؛ فكذبوا الرسل وخالفوا ما جاءهم من أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص420–421، تحت عنوان «نكتة التعبير بالكذب عن احتجاجهم»","url":""}]},{"id":"s6-1375","number":1375,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا جُعل ذوق البأس غاية لتكذيب الأمم السابقة؟","answer":"لأنهم استمروا على التكذيب حتى انتهى بهم إلى معاينة العقوبة؛ فبيّن التعبير أن الإمهال لم يكن رضا، وأن عاقبة الإصرار كانت ذوق البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص421، تحت عنوان «علة جعل ﴿حتى ذاقوا بأسنا﴾ غاية للتكذيب»","url":""}]},{"id":"s6-1376","number":1376,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ماذا يفيد الاستفهام في قوله تعالى: ﴿قل هل عندكم من علم﴾؟","answer":"يتحداهم أن يبرزوا أي علم يثبت دعواهم، وفيه إنكار أن يكون عندهم وحي أو برهان؛ فلا يبقى لهم إلا الظن والافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص423، تحت عنوان «دلالة الاستفهام في ﴿قل هل عندكم﴾»","url":""}]},{"id":"s6-959","number":959,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا أدخل المشركون آباءهم في قولهم: ﴿ولا آباؤنا﴾؟","answer":"ليجعلوا قدم ما ورثوه وكثرة من سبقهم إليه سندًا لدعواهم؛ فجمعوا تقليد الآباء إلى الاحتجاج بالمشيئة، مع أن شيوع الباطل لا يصيره حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص419، تحت عنوان «علة ذكر آبائهم معهم»","url":""}]},{"id":"s6-960","number":960,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما وجه البلاغة في المجاز في قوله: ﴿حتى ذاقوا بأسنا﴾؟","answer":"الذوق أصله إدراك المطعوم مباشرة، فاستعير لمباشرة العذاب ومعاناة أثره؛ ليبين أن حجتهم لم تمنع عن السابقين بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص421، تحت «بلاغة المجاز في قوله: ﴿حتى ذاقوا بأسنا﴾»","url":""}]},{"id":"s6-961","number":961,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما الصورة في قوله تعالى عن العلم: ﴿فتخرجوه لنا﴾؟","answer":"صوّر العلم بحجة مخبوءة يمكن إخراجها وإظهارها للناس؛ وفي هذا تحدٍّ يكشف أنهم لا يملكون شيئًا يخرجونه دليلًا على دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص425، تحت عنوان «بلاغة الاستعارة التصريحية في قوله ﴿فتخرجوه﴾»","url":""}]},{"id":"s6-962","number":962,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"لماذا قُدّم اتباع الظن على الخرص في وصف حجتهم؟","answer":"لأن الظن هو الأصل الفاسد الذي اعتمدوه، ثم نشأ عنه الخرص والكلام بلا علم؛ فرتبت الآية فساد الاعتقاد قبل فساد القول الناتج منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص429، تحت عنوان «نكتة تقديم اتباع الظن على الخرص»","url":""}]},{"id":"s6-963","number":963,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"ما سرّ تقديم ﴿لله﴾ في ﴿فلله الحجة البالغة﴾؟","answer":"تقديم ﴿لله﴾ يفيد الاختصاص: الحجة الكاملة له وحده، لا لمن يحتج بالظن على الشرك والمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص435، تحت «دلالة الفاء في قوله: ﴿فلله﴾، وتقديم المسند على المسند إليه»","url":""}]},{"id":"s6-964","number":964,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"لماذا عُرّفت ﴿الحجة﴾ ووُصفت بأنها ﴿البالغة﴾؟","answer":"لأنها حجة الله المعهودة التي تبلغ غاية البيان والإلزام وتقطع العذر؛ فقد منح الاختيار وأرسل الرسل وبيّن الطريق، فلا تبقى حجة لمخالف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص435–436، تحت عنوان «بلاغة تعريف لفظ ﴿الحجة﴾، وعلة وصفها بـ﴿البالغة﴾»","url":""}]},{"id":"s6-965","number":965,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"لماذا عبّر بالمشيئة في قوله تعالى: ﴿فلو شاء لهداكم أجمعين﴾؟","answer":"لأن المشيئة تتعلق بوقوع الهداية في الكون؛ فلو شاء الله إلجاء الناس إليها لوقعت، لكنه شاء أن يكلّفهم ويختبر اختيارهم بعد إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص437، تحت عنوان «سر إيثار فعل المشيئة دون الإرادة، والتعبير بصيغة الماضي»","url":""}]},{"id":"s6-1377","number":1377,"surah":6,"verses":[149],"references":[{"surah":6,"verses":[149]}],"verseLabel":"الأنعام: 149","question":"ما الفرق بين قول الله: ﴿فلو شاء لهداكم أجمعين﴾ وقول المشركين: ﴿لو شاء الله ما أشركنا﴾؟","answer":"قول الله يقرر قدرته على هداية الإلجاء مع إبقاء التكليف والاختيار، أما قولهم فيجعل المشيئة عذرًا للشرك ودليلًا على الرضا به؛ فالأول حجة عليهم والثاني تهرب من المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص437–438، تحت عنوان «الفرق بين الجملتين: ﴿فلو شاء لهداكم﴾ و﴿لو شاء الله ما أشركنا﴾»","url":""}]},{"id":"s6-966","number":966,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿هلم شهداءكم﴾، دون أن يقال: أحضروا؟","answer":"﴿هلم﴾ لفظ دعوة واستحضار، ومعناه هنا: أحضروا شهداءكم. ويذكر المصدر أن فيه استدعاءً للمأمور وتقريبًا له للإقبال على الأمر؛ فالمقام ينقل دعواهم إلى امتحان مباشر: من يشهد أن الله حرم هذا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص443–444، تحت «معنى ﴿هلم﴾، ودلالة التعبير به دون غيره»","url":""}]},{"id":"s6-967","number":967,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا قيل: ﴿فإن شهدوا فلا تشهد معهم﴾ مع أن شهادتهم باطلة؟","answer":"لأن الموافقة الظاهرة قد توهم تصديقهم، فنُهي الرسول عن مشاركتهم شهادتهم أو إقرارها؛ فصدور الشهادة منهم لا يمنح الباطل حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص448، تحت عنوان «علة التعبير بقوله تعالى: ﴿فإن شهدوا فلا تشهد معهم﴾»","url":""}]},{"id":"s6-968","number":968,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا عُطف النهي عن اتباع أهوائهم على النهي عن موافقتهم في الشهادة؟","answer":"لأن شهادتهم الباطلة ثمرة أهوائهم؛ فبعد منع تصديق القول نهى عن اتباع الأصل الذي ولّده، ليُغلق طريق الباطل من جذره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص448، تحت عنوان «دلالة عطف جملة ﴿ولا تتبع﴾ على ما قبلها»","url":""}]},{"id":"s6-1378","number":1378,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا قيل: ﴿أهواء الذين كذبوا بآياتنا﴾ ولم يقل: أهواءهم؟","answer":"ليبيّن الوصف سبب النهي: أهواؤهم قادتهم إلى تكذيب الآيات، وليعم التحذير كل من جعل الهوى مقدمًا على الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص449، تحت عنوان «وضع المظهر موضع المضمر»","url":""}]},{"id":"s6-969","number":969,"surah":6,"verses":[150],"references":[{"surah":6,"verses":[150]}],"verseLabel":"الأنعام: 150","question":"لماذا صُرّح بلفظ ﴿ربهم﴾ في قوله تعالى: ﴿وهم بربهم يعدلون﴾؟","answer":"ليستحضر ما للرب من تربية وإنعام عليهم، فيشتد استنكار أن يسووا به من لا يخلق ولا يرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص451، تحت عنوان «دلالة التعبير بالاسم الظاهر في ﴿وهم بربهم يعدلون﴾»","url":""}]},{"id":"s6-970","number":970,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا افتتح بيان المحرمات بقوله تعالى: ﴿تعالوا﴾؟","answer":"لأنها دعوة إلى الإقبال والارتفاع عن افتراء التحريم إلى تلقي حكم الله، وفيها استدعاء للسامعين كي يصغوا إلى الوصايا الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص460، تحت عنوان «إيثار التعبير بقوله: ﴿تعالوا﴾، والعدول عن مرادفاته»","url":""}]},{"id":"s6-1379","number":1379,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"ما دلالة اختيار الفعل ﴿أتل﴾ في قوله تعالى: ﴿أتل ما حرم ربكم عليكم﴾؟","answer":"يدل على أن البيان وحي يُقرأ ويتبع، لا رأي يبتدعه البشر؛ فالمتكلم يتلو أمر الله في الحلال والحرام كما أُنزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص461–462، تحت عنوان «دلالة الفعل ﴿أتل﴾ ووجه جزمه»","url":""}]},{"id":"s6-1380","number":1380,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا بدأت الوصايا بالنهي عن الشرك؟","answer":"لأن التوحيد أصل صلاح الاعتقاد والعمل، فإذا فسد الأصل لم تنفع الأعمال المبنية عليه؛ فكان إصلاحه مقدمًا على سائر الوصايا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص466، تحت عنوان «بلاغة البدء بالنهي عن الشرك دون ما بعده»","url":""}]},{"id":"s6-971","number":971,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا جاء الإحسان إلى الوالدين بعد النهي عن الشرك؟","answer":"لأن حق الوالدين أعظم حقوق الخلق بعد حق الله، فانتقل من إصلاح الاعتقاد إلى الوفاء بمن كانا سبب الوجود والرعاية، ليجتمع صلاح الدين وصلاح الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص466–467، تحت عنوان «دلالة عطف جملة ﴿وبالوالدين إحسانًا﴾ على ما قبلها»","url":""}]},{"id":"s6-972","number":972,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا قال في الأنعام: ﴿نحن نرزقكم وإياهم﴾، وفي الإسراء: ﴿نحن نرزقهم وإياكم﴾؟","answer":"في الأنعام كان الفقر واقعًا بالآباء فقدم ضمان رزقهم، أما في الإسراء فكان الخوف من فقر متوقع بسبب الأولاد فقدم ضمان رزقهم؛ فجاء كل ترتيب على موضع القلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص471–472، تحت عنوان «بلاغة فن التغاير بين آيتي الأنعام والإسراء»","url":""}]},{"id":"s6-973","number":973,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا نهى الله عن قرب الفواحش لا عن فعلها فقط؟","answer":"لأن النهي عن القرب يسد المقدمات والذرائع التي تقود إليها، فيحمي الإنسان قبل الوقوع بدل أن يقتصر على تحريم الفعل بعد بلوغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص473، تحت عنوان «بلاغة النهي عن قرب الفواحش»","url":""}]},{"id":"s6-974","number":974,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا ذُكر ﴿ما ظهر﴾ و﴿ما بطن﴾ بعد النهي العام عن الفواحش؟","answer":"لتأكيد استيعاب النهي للفواحش المعلنة والمستترة، ولأعمال الجوارح وخفايا القلوب؛ فلا يخفف قبح المعصية أن تُستر عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص474، تحت عنوان «النهي عما ظهر وما بطن بعد النهي العام عن الفواحش»","url":""}]},{"id":"s6-975","number":975,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"لماذا خُتمت هذه الوصايا بـ﴿لعلكم تعقلون﴾، واختلفت عن الفواصل اللاحقة؟","answer":"لأن هذه الوصايا أصول يدرك العقل قبح أضدادها، فدعت الفاصلة إلى تشغيل العقل فيها؛ ثم جاءت التذكر والتقوى في المواضع اللاحقة بحسب مضمون كل مجموعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص480–481، تحت عنوان «بلاغة التذييل هنا وسر اختلافه عن لواحقه»","url":""}]},{"id":"s6-976","number":976,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تقربوا مال اليتيم﴾ كما قال في الفواحش؟","answer":"النهي عن القرب يمنع كل تصرف يعرض مال اليتيم للنقص، لا مجرد أكله؛ ثم استثنى التصرف الذي يحقق مصلحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص492، تحت «بلاغة الكناية في قوله: ﴿ولا تقربوا مال اليتيم﴾»","url":""}]},{"id":"s6-977","number":977,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"لماذا قيل في مال اليتيم: ﴿إلا بالتي هي أحسن﴾؟","answer":"ليجعل المسموح به أخصّ وجوه التصرف وأنفعها لليتيم، فلا يكفي أن يكون التصرف حسنًا في الجملة، بل يجب أن يكون هو الأبعد عن الضرر والأقرب إلى تنمية ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص495، تحت عنوان «نكتة التعبير بالاسم الموصول في قوله: ﴿إلا بالتي هي أحسن﴾»","url":""}]},{"id":"s6-1381","number":1381,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما دلالة قوله: ﴿هي أحسن﴾ في حماية مال اليتيم؟","answer":"الجملة تثبت أن الخصلة المختارة هي الأحسن على وجه مستقر، واسم التفضيل يلزم الولي بموازنة البدائل واختيار أصلحها لليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص496، تحت عنوان «دلالة اسمية الجملة واختيار اسم التفضيل في قوله: ﴿هي أحسن﴾»","url":""}]},{"id":"s6-978","number":978,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ماذا يفيد قوله تعالى في مال اليتيم: ﴿حتى يبلغ أشده﴾؟","answer":"يجعل بلوغ القوة والرشد غايةً للمنع من تسليم المال؛ فإذا اكتمل استعداد اليتيم لحسن التصرف دُفع إليه ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص497، تحت عنوان «دلالة تركيب ﴿حتى يبلغ أشده﴾ ونوع المجاز فيه»","url":""}]},{"id":"s6-1382","number":1382,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما الفرق بين أشد اليتيم وأشد الرجل؟","answer":"أشد اليتيم هو بلوغه حدّ الرشد الذي يؤهله لتدبير ماله، أما أشد الرجل فهو اكتمال قوته ونضجه بعد ذلك؛ فلكل سياق الغاية المناسبة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص498، تحت عنوان «الفرق بين أشد اليتيم وأشد الرجل»","url":""}]},{"id":"s6-979","number":979,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما بلاغة قوله تعالى: ﴿لا نكلف نفسًا إلا وسعها﴾ بعد الأمر بالعدل في الكيل والميزان؟","answer":"هو احتراس يرفع الحرج عن الخطأ الذي لا يمكن التحرز منه بعد بذل الجهد، من غير أن يرخّص في التطفيف؛ فجمع وجوب العدل وسماحة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص502–503، تحت عنوان «بلاغة الاحتراس في قوله: ﴿لا نكلف نفسًا إلا وسعها﴾»","url":""}]},{"id":"s6-980","number":980,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو كان ذا قربى﴾، دون أن يقال: ولو كان قريبًا؟","answer":"يذكر المصدر أن التعبير يتسع لأنواع الصلة، كقرابة النسب والمصاهرة وغيرها، فيشمل ما قد يميل بسببه الإنسان إلى صاحبه. والمعنى أن هذه الروابط كلها لا تسوغ المحاباة في القول والحكم؛ فالعدل واجب معها أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص512–513، تحت «نكتة التعبير بقوله: ﴿ذا قربى﴾»","url":""}]},{"id":"s6-981","number":981,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"لماذا خُتمت الوصايا بقوله تعالى: ﴿لعلكم تذكرون﴾؟","answer":"لأن الوصايا عهد مركوز في الفطرة وتؤكده الرسالات، فالمطلوب أن يستحضرها الإنسان ولا تغلبه الغفلة والهوى؛ وجاء التذييل حاثًا على دوام التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص517–518، تحت عنوان «سر ختم الآية بقوله: ﴿لعلكم تذكرون﴾»","url":""}]},{"id":"s6-982","number":982,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا أُفرد ﴿الصراط﴾ وجُمعت ﴿السبل﴾؟","answer":"لأن الحق طريق واحد مستقيم يوصل إلى الله، أما طرق البدع والضلال فكثيرة متفرقة؛ فدل اختلاف العدد على وحدة الهدى وتشعب الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص530، تحت عنوان «غرض العدول من الصراط إلى السبل بالجمع»","url":""}]},{"id":"s6-983","number":983,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا أضيف الصراط إلى الله: ﴿صراطي﴾؟","answer":"إضافته إلى الله تشريف وتعيين لمصدره: هذا طريقه الذي شرعه الموصل إليه، فلا يلتبس بطرق البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص527، تحت «نكتة إضافة الصراط إلى الياء»","url":""}]},{"id":"s6-984","number":984,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"ما الصورة التي يرسمها قوله تعالى: ﴿فتفرق بكم عن سبيله﴾؟","answer":"يمثل السبل المتشعبة بطرق تسحب سالكيها بعيدًا عن الطريق المستقيم، فتفرّق الجماعة وتبعدها عن الغاية؛ فتتحول الضلالة إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص530–531، تحت عنوان «بلاغة التمثيل»","url":""}]},{"id":"s6-985","number":985,"surah":6,"verses":[153],"references":[{"surah":6,"verses":[153]}],"verseLabel":"الأنعام: 153","question":"لماذا خُتمت وصية الصراط بقوله تعالى: ﴿لعلكم تتقون﴾؟","answer":"لأن لزوم الطريق الواحد وترك السبل هو العمل الذي يحمي من الضلال ويجدد التقوى؛ فجاء الرجاء متعلقًا باستمرارهم على أسباب الوقاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص534، تحت عنوان «نكتة التعبير بـ(لعل) دون غيرها في قوله: ﴿لعلكم تتقون﴾»","url":""}]},{"id":"s6-986","number":986,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا بدأ بـ﴿ثم آتينا موسى الكتاب﴾ مع أن إيتاء موسى أسبق زمنًا؟","answer":"﴿ثم﴾ لترتيب الأخبار أو للانتقال الرتبي إلى شاهد آخر على تمام الحجة، لا للترتيب الزمني؛ فإيتاء موسى سابق معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص538–539، تحت «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s6-987","number":987,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا وُصف إيتاء موسى الكتاب بأنه ﴿تمامًا﴾؟","answer":"لأنه أتم النعمة والبيان لبني إسرائيل، فجمع لهم أصول الشريعة وما يحتاجون إليه من الهداية والتفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص541، تحت عنوان «نكتة التعبير بـ﴿تمامًا﴾»","url":""}]},{"id":"s6-1383","number":1383,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"من الذي يشمله قوله تعالى: ﴿على الذي أحسن﴾، وما فائدة التعبير بالموصول؟","answer":"يحتمل موسى الذي أحسن الطاعة، ويحتمل جنس المحسنين؛ وفي الحالتين يعلق الموصول تمام النعمة بصفة الإحسان، فيفتح المعنى لكل من تحققت فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص541–542، تحت عنوان «غرض التعبير بالاسم الموصول»","url":""}]},{"id":"s6-988","number":988,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"ماذا يضيف قوله تعالى عن الكتاب: ﴿وتفصيلًا لكل شيء﴾؟","answer":"يبين أن الكتاب لم يأت مجملًا مبهمًا، بل فصل لبني إسرائيل ما يحتاجون إليه في شريعتهم وأحكامهم؛ فتم به البيان بعد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص542، تحت عنوان «دلالة العطف في ﴿وتفصيلًا لكل شيء﴾»","url":""}]},{"id":"s6-1384","number":1384,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"لماذا جمع في وصف الكتاب بين ﴿هدى ورحمة﴾؟","answer":"لأنه يرشد إلى الحق فيكون هدى، ويثمر النجاة والخير لمن اتبعه فيكون رحمة؛ فجمع الدلالة على الطريق وأثر سلوكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص543–544، تحت عنوان «دلالة العطف والتنكير في قوله ﴿وهدى ورحمة﴾»","url":""}]},{"id":"s6-989","number":989,"surah":6,"verses":[154],"references":[{"surah":6,"verses":[154]}],"verseLabel":"الأنعام: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿لعلهم بلقاء ربهم يؤمنون﴾ بتقديم ﴿بلقاء ربهم﴾؟","answer":"قُدّم الجار والمجرور للاهتمام بلقاء الله وما فيه من بعث وجزاء؛ فاستحضار هذا اللقاء يدفع إلى الإيمان والاستقامة على شرعه والعمل بهدى الكتاب. ويذكر المصدر أيضًا مراعاة الفواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص546، تحت «بلاغة تقديم شبه الجملة في قوله: ﴿بلقاء ربهم يؤمنون﴾»","url":""}]},{"id":"s6-990","number":990,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"لماذا جاء قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾ بعد ذكر كتاب موسى؟","answer":"ليصل القرآن بسلسلة الوحي قبله، ويبين أن مصدر الكتابين واحد، ثم ينتقل من خبر الكتاب السابق إلى دعوة المخاطبين لاتباع الكتاب المنزل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص550، تحت عنوان «وجه عطف جملة ﴿وهذا كتاب﴾ على ما تقدم»","url":""}]},{"id":"s6-1385","number":1385,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"ما فائدة تنكير ﴿كتاب﴾ في قوله تعالى: ﴿وهذا كتاب أنزلناه مبارك﴾؟","answer":"للتعظيم؛ فهو كتاب عظيم الشأن كثير البركة، مهيمن على ما سبقه وجدير بأن يُتبع ويُعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص551، تحت عنوان «فائدة تنكير لفظ ﴿كتاب﴾»","url":""}]},{"id":"s6-991","number":991,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"لماذا فُرّع على بركة القرآن قوله تعالى: ﴿فاتبعوه واتقوا﴾؟","answer":"لأن كونه كتابًا منزلًا مباركًا يقتضي العمل به: اتباع أوامره وهديه، واتقاء مخالفته وما حذر منه؛ فكانت الأوامر ثمرة مباشرة لوصفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص552–553، تحت عنوان «التفريع في قوله تعالى: ﴿فاتبعوه واتقوا﴾»","url":""}]},{"id":"s6-992","number":992,"surah":6,"verses":[155],"references":[{"surah":6,"verses":[155]}],"verseLabel":"الأنعام: 155","question":"ما وجه الترقي في قوله تعالى: ﴿فاتبعوه واتقوا لعلكم ترحمون﴾؟","answer":"بدأ باتباع الكتاب عملًا، ثم بالتقوى وقايةً من المخالفة، ثم جعل الرحمة ثمرة لذلك؛ فانتقل من السبب إلى كماله ثم إلى الجزاء المرجو.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص554–555، تحت عنوان «الترقي في قوله: ﴿فاتبعوه واتقوا لعلكم ترحمون﴾»","url":""}]},{"id":"s6-993","number":993,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"ما الغرض البلاغي من حذف لام التعليل في قوله: ﴿أن تقولوا﴾، وما وجه البلاغة في المجاز المرسل في قوله: ﴿عن دراستهم﴾؟","answer":"أنزل القرآن لقطع عذرهم أن الكتب السابقة نزلت على اليهود والنصارى وحدهم وأن العرب غافلون عن قراءتها وفهمها؛ فقد جاءهم كتاب بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص558، 561–562، تحت «غرض حذف لام التعليل في قوله: ﴿أن تقولوا﴾؛ المجاز المرسل في قوله: ﴿عن دراستهم﴾»","url":""}]},{"id":"s6-994","number":994,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"لماذا قيل: ﴿على طائفتين من قبلنا﴾ من غير تسمية اليهود والنصارى؟","answer":"لأن الطائفتين معلومتان للمخاطبين بكونهما أهل التوراة والإنجيل، فدل التنكير عليهما مع إبراز أنهما جماعتان سبقتا العرب إلى تلقي الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص559، تحت عنوان «دلالة التنكير في لفظ ﴿طائفتين﴾»","url":""}]},{"id":"s6-995","number":995,"surah":6,"verses":[156],"references":[{"surah":6,"verses":[156]}],"verseLabel":"الأنعام: 156","question":"ماذا تكني عبارة ﴿عن دراستهم لغافلين﴾؟","answer":"تكني عن بعد العرب عن قراءة كتب الطائفتين وفهمها واتباع ما فيها، فلا يملكون علمًا مباشرًا بها؛ وقد جاءهم القرآن بلسانهم فقطع هذا العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص562، تحت عنوان «الكناية عن الاتباع أو عدمه في لفظ ﴿لغافلين﴾»","url":""}]},{"id":"s6-996","number":996,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"كيف تدرجت أعذار المشركين قبل نزول القرآن؟","answer":"انتقلوا من الاحتجاج بأن الكتاب نزل على طائفتين غيرهم، إلى دعوى الغفلة عن دراسته، ثم إلى زعم أنهم لو نزل عليهم كتاب لكانوا أهدى؛ فقطع القرآن الأعذار درجة بعد درجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص567، تحت عنوان «الترقي والتدرج في الاعتلال»","url":""}]},{"id":"s6-1386","number":1386,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة قولهم على سبيل الشرط: ﴿لو أنا أنزل علينا الكتاب لكنا أهدى منهم﴾؟","answer":"صاغوا وعدًا مفترضًا يزعمون فيه أن نزول كتاب عليهم سيجعلهم أشد اهتداء، فلما جاءتهم البينة صار قولهم حجة عليهم لا عذرًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص568، تحت عنوان «غرض التعبير بالشرطية في قولهم: ﴿لو أنا أنزل﴾»","url":""}]},{"id":"s6-997","number":997,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"لماذا كُنّي عن القرآن بقوله تعالى: ﴿بينة من ربكم﴾؟","answer":"لأن القرآن هو الحجة الواضحة التي تكشف الحق وتقطع العذر، فدل وصف البينة عليه بما اشتمل عليه من بيان وإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص572، تحت عنوان «البينة كناية عن موصوف هو القرآن في هذه الآية الكريمة»","url":""}]},{"id":"s6-1387","number":1387,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما فائدة الجمع بين ﴿البينة﴾ و﴿الهدى﴾ في وصف القرآن؟","answer":"هو بينة تقيم الحجة وتظهر صدق الرسالة، وهدى يرشد من يقبلها إلى الطريق؛ فجمع وضوح الدليل وثمرة الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص572–573، تحت عنوان «فائدة الجمع بين البينة والهدى»","url":""}]},{"id":"s6-998","number":998,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة الاستفهام في قوله تعالى: ﴿فمن أظلم ممن كذب بآيات الله﴾؟","answer":"هو إنكار ونفي أن يكون أحد أشد ظلمًا ممن عرف الآيات ثم كذب بها وأعرض عنها؛ فقد جمع رد الحق ومنع النفس من الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص574، تحت عنوان «بلاغة الاستفهام الإنكاري ودلالته في قوله: ﴿فمن أظلم﴾»","url":""}]},{"id":"s6-1388","number":1388,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما الفرق بين الإعراض والصد والصدوف؟","answer":"الإعراض ترك الالتفات إلى الشيء، والصد قد يكون انصرافًا عنه أو منعًا لغيره، أما الصدوف فهو أشدها دلالة على الميل والانحراف عن الحق؛ فاختياره يصور قوة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص580، تحت عنوان «(الإعراض) و(الصد) و(الصدوف)»","url":""}]},{"id":"s6-999","number":999,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ماذا تفيد صيغة ﴿يصدفون﴾ والانتقال إلى الحديث عنهم بضمير الغائب؟","answer":"المضارع يصور إعراضهم فعلًا يتجدد، والالتفات يبعدهم عن مقام الخطاب كأنهم غير أهل للمواجهة بعد إصرارهم؛ فيتجدد مشهد الجريمة ويشتد تقريعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص577، تحت عنوان «فعلية جملة ﴿يصدفون﴾ ودلالة الالتفات»","url":""}]},{"id":"s6-1389","number":1389,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"لماذا أعيد فعل الصدوف في قوله تعالى: ﴿بما كانوا يصدفون﴾ بدل الإضمار؟","answer":"ليصرح بسبب الجزاء ويثبته في الذهن: سوء العذاب نتيجة صدوفهم نفسه، لا أمر آخر؛ فكان تكرار الفعل أبلغ في التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص577، تحت عنوان «الذكر في موضع الإضمار توكيدًا»","url":""}]},{"id":"s6-1000","number":1000,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة القصر في قوله تعالى: ﴿هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك﴾؟","answer":"يبين أنه لم يبق لهم بعد قيام الحجة إلا انتظار ما ينهي زمن الاختيار: حضور الملائكة، أو أمر الله، أو بعض العلامات الحاسمة؛ فهو قصر تهديد لا عذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص585، تحت عنوان «نكتة أسلوب القصر»","url":""}]},{"id":"s6-1001","number":1001,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة ترتيب إتيان الملائكة ثم ﴿يأتي ربك﴾ ثم إتيان بعض آياته في مشهد الوعيد؟","answer":"يذكر المصدر أن ترتيب هذه الجمل يرفع وقع التهديد في النفس؛ فالمشهد يتدرج في ذكر ما يواجه المكذبين من هول، ولا يبقى مجرد انتظار لآية يقترحونها. فالغرض تفخيم الوعيد وتخويفهم من عاقبة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587–588، تحت «سر تقديم بعض الجمل على بعض في الآية الكريمة»","url":""}]},{"id":"s6-1002","number":1002,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا أبهمت الآية علامات القيامة بقولها: ﴿بعض آيات ربك﴾؟","answer":"لأن المقصود ليس تعداد العلامات، بل التحذير من آية حاسمة ينتهي عند ظهورها زمن الاختيار وقبول الإيمان؛ فالإبهام يوقظ الترقب والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587، تحت عنوان «غرض إبهام علامات القيامة»","url":""}]},{"id":"s6-1390","number":1390,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا أعيد لفظ ﴿بعض آيات ربك﴾ ظاهرًا بدل الضمير؟","answer":"للاحتراس من توهم أن المقصود في الموضع الثاني آية أخرى، ولتثبيت أن الحكم متعلق بتلك العلامة الحاسمة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص590، تحت عنوان «دلالة الاحتراس في التعبير بالظاهر بدل المضمر»","url":""}]},{"id":"s6-1003","number":1003,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"كيف أوجزت الآية أحوال الناس عند مجيء بعض آيات الله؟","answer":"قسمتهم إلى نفس لم تؤمن من قبل، ونفس آمنت لكنها لم تكسب خيرًا؛ فاستوعبت بإيجاز من فاتها أصل الإيمان ومن فرّط في ثمرة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص595، تحت عنوان «بلاغة الإيجاز في استعمال أسلوب التقسيم»","url":""}]},{"id":"s6-1391","number":1391,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما الذي أدمجه قوله تعالى: ﴿أو كسبت في إيمانها خيرًا﴾ في الوعيد؟","answer":"أدخل تحذير المؤمن من تأخير العمل الصالح داخل وعيد المكذب؛ فليس المطلوب سبق الإيمان وحده، بل أن يثمر خيرًا قبل فوات زمن الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص595، تحت عنوان «بلاغة الإدماج في قوله ﴿أو كسبت في إيمانها خيرًا﴾»","url":""}]},{"id":"s6-1004","number":1004,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما الغرض من الأمر في قوله تعالى: ﴿قل انتظروا﴾؟","answer":"هو تهديد للمكذبين: امضوا في انتظار الآيات والعقاب بعد قيام الحجة، فستظهر عاقبة التكذيب التي لا تنفع عندها المعاذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص596، تحت عنوان «الغرض البياني من الأمر بالانتظار»","url":""}]},{"id":"s6-1392","number":1392,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما دلالة جواب المؤمنين: ﴿إنا منتظرون﴾؟","answer":"يثبت يقينهم بوعد الله؛ فكما ينتظر المكذبون ما اقترحوه، ينتظر المؤمنون نصر الله ووقوع وعيده، والجملة الخبرية تؤكد ثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص597، تحت عنوان «غرض الجملة الخبرية في قوله ﴿إنا منتظرون﴾»","url":""}]},{"id":"s6-1005","number":1005,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"لماذا عبّر عن مجيء الآيات بالفعل المضارع؟","answer":"ليستحضر المشهد المنتظر كأنه يتجدد أمام السامع، فيظل الوعيد حاضرًا في النفس ولا يتحول إلى خبر بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص586، تحت عنوان «سر التعبير بالمضارع بدلًا من الاسم»","url":""}]},{"id":"s6-1393","number":1393,"surah":6,"verses":[158],"references":[{"surah":6,"verses":[158]}],"verseLabel":"الأنعام: 158","question":"ما أثر إسناد الإتيان إلى لفظ ﴿الرب﴾؟","answer":"يهوّل الموقف لأن الآتي هو ربهم المالك المدبر الذي لا يعجزه شيء، ويذكّرهم بأن من كفروا بآياته هو صاحب الحكم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص587، تحت عنوان «أثر إسناد فعل الإتيان إلى لفظ (الرب)»","url":""}]},{"id":"s6-1006","number":1006,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا صُوّر صنيعهم بالدين بقوله تعالى: ﴿فرقوا دينهم﴾؟","answer":"صُوّر الدين الجامع كشيء واحد مزقوه أجزاء؛ إذ أخذوا بعضه وتركوا بعضه وخلطوا الحق بالباطل، فبددوا وحدته بعد أن كان سبب اجتماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص603، تحت عنوان «دلالة المجاز من باب الاستعارة في قوله: ﴿فرقوا دينهم﴾»","url":""}]},{"id":"s6-1394","number":1394,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا قيل بعد تفريق الدين: ﴿وكانوا شيعًا﴾؟","answer":"لأن تفريق الدين لم يبق خلافًا عابرًا، بل حوّلهم فرقًا يتبع بعضها بعضًا ويناصر كل فريق رأيه؛ فبيّن التعبير ثمرة التفريق في واقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص604، تحت عنوان «نكتة التعبير بقوله ﴿شيعًا﴾ بعد وصفهم بتفريق الدين»","url":""}]},{"id":"s6-1007","number":1007,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا أعقب وصف المفرقين لدينهم بقوله تعالى: ﴿لست منهم في شيء﴾؟","answer":"ليعلن براءة الرسول ﷺ الكاملة من طريقتهم، ويقطع توهم أن التفرق والتحزب يمكن أن ينتسبا إلى الدين الذي جاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص607، تحت عنوان «الموقع البياني لقوله: ﴿لست منهم في شيء﴾»","url":""}]},{"id":"s6-1395","number":1395,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما الذي يفيده تنكير ﴿شيء﴾ في قوله تعالى: ﴿لست منهم في شيء﴾؟","answer":"يفيد عموم البراءة: ليست بين منهجه وبين تفريقهم للدين أدنى صلة، فلا يلتقي معهم في قليل ولا كثير من باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص608، تحت عنوان «نكتة تنكير ﴿شيء﴾»","url":""}]},{"id":"s6-1396","number":1396,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما دلالة القصر في قوله تعالى: ﴿إنما أمرهم إلى الله﴾؟","answer":"يقصر الفصل في شأنهم وجزاءهم على الله وحده؛ فالرسول يبلّغ ويتبرأ من التفرق، أما السرائر والحساب النهائي فإلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص609، تحت عنوان «القصر وطريقته ونوعه في جملة ﴿إنما أمرهم إلى الله﴾»","url":""}]},{"id":"s6-1008","number":1008,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم ينبئهم بما كانوا يفعلون﴾؟","answer":"تنقل من إمهالهم في الدنيا إلى حسابهم بعد مهلة؛ فالتراخي لا يعني إهمال العمل، بل يؤكد أن الجزاء آت في موعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص609، تحت عنوان «دلالة الحرف ﴿ثم﴾ في قوله: ﴿ثم ينبئهم﴾»","url":""}]},{"id":"s6-1397","number":1397,"surah":6,"verses":[159],"references":[{"surah":6,"verses":[159]}],"verseLabel":"الأنعام: 159","question":"لماذا عُبّر بالإنباء في قوله تعالى: ﴿ثم ينبئهم بما كانوا يفعلون﴾؟","answer":"لأن إخبارهم بأعمالهم يوم القيامة ليس خبرًا مجردًا، بل كشف لها وإقامة للحجة ثم معاقبة عليها؛ فكنّى الإنباء عن تمام المحاسبة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص610، تحت عنوان «التعبير بـ﴿ينبئهم﴾ كناية عن معاقبتهم جزاء أفعالهم»","url":""}]},{"id":"s6-1009","number":1009,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"لماذا أُفردت ﴿الحسنة﴾ و﴿السيئة﴾ في آية الجزاء؟","answer":"ليدخل في الحكم أدنى عمل من الجنسين: فالحسنة الواحدة تنال التضعيف، والسيئة الواحدة لا يزاد في جزائها على مثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص618، تحت عنوان «نكتة إفراد الحسنة والسيئة في الآية الكريمة»","url":""}]},{"id":"s6-1398","number":1398,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما دلالة القصر في قوله تعالى عن السيئة: ﴿فلا يجزى إلا مثلها﴾؟","answer":"يحصر جزاء السيئة في قدرها، فيطمئن إلى عدل الله: لا يضاعف العقوبة كما تضاعف الحسنة، ولا يحمل أحد فوق ما عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص622، تحت عنوان «بلاغة القصر ونوعه في الاستثناء بعد النفي»","url":""}]},{"id":"s6-1010","number":1010,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما سرّ تقديم ﴿له﴾ في قوله تعالى: ﴿فله عشر أمثالها﴾؟","answer":"قُدّم للاختصاص والاهتمام: جزاء صاحب الحسنة ثابت له، وفيه إشعار بمنزلته حتى نال هذا التضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص620، تحت «غرض تقديم شبه الجملة في ﴿فله عشر أمثالها﴾»","url":""}]},{"id":"s6-1011","number":1011,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما سرّ بناء ﴿فلا يجزى﴾ للمجهول في جزاء السيئة؟","answer":"لأن المقصود إبراز مقدار الجزاء وعدله، لا ذكر المجازي المعلوم من السياق؛ فالسيئة لا يقابلها إلا مثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص622، تحت «نكتة التعبير عن فعل الجزاء بالبناء للمفعول في ﴿يجزى﴾»","url":""}]},{"id":"s6-1012","number":1012,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿وهم لا يظلمون﴾؟","answer":"يقرر عدل الجزاء: لا تُنقص حسنة ولا تُزاد سيئة على مثلها؛ فالتضعيف فضل، وعدم زيادة العقاب عدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص623–624، تحت «معنى الواو في ﴿وهم لا يظلمون﴾ وموقع الجملة بعدها؛ دلالة الضمير (هم) ومرجعيته في قوله: ﴿وهم لا يظلمون﴾»","url":""}]},{"id":"s6-1013","number":1013,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"كيف تكون مضاعفة الحسنة بين العشر والسبع مئة؟","answer":"العشر أصل عام لمضاعفة الحسنة، ثم تزيد المضاعفة إلى سبع مئة وأكثر بحسب العمل والإخلاص وفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص621، تحت «مضاعفة الحسنات بين العشر والسبع مئة»","url":""}]},{"id":"s6-1420","number":1420,"surah":6,"verses":[160],"references":[{"surah":6,"verses":[160]}],"verseLabel":"الأنعام: 160","question":"لماذا أطلقت آية البقرة المضاعفة من غير تقييدها بعشر أمثالها؟","answer":"لأن الخيرات تتفاوت باختلاف العاملين ونياتهم وأعمالهم، فناسب الإطلاق ما يفتحه الله من زيادة تبلغ سبع مئة أو أكثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص202، تحت «سر إطلاق المضاعفة دون تقييدها بعشر أمثالها»","url":""}]},{"id":"s6-1014","number":1014,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا انتقل ختام السورة من محاجة المشركين إلى إعلان الهداية في قوله: ﴿قل إنني هداني ربي﴾؟","answer":"لأن الحجج قد استوفت غرضها، فطُوي سجل الجدال بإعلان الطريق الذي ثبّت الله رسوله عليه، ليكون الختام موقفًا عمليًا واضحًا لا جدلًا ممتدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص628، تحت عنوان «طي سجل المحاجة مؤذن باختتام السورة الكريمة»","url":""}]},{"id":"s6-1399","number":1399,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما أثر المؤكدات في قوله تعالى: ﴿قل إنني هداني ربي﴾؟","answer":"تثبت يقين الرسول ﷺ بهداية ربه أمام إنكار المشركين، وتبرز رسوخ موقفه من غير تردد أو احتمال لمساومتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص629، تحت عنوان «نكتة اشتمال جملة ﴿إنني هداني﴾ على مؤكدات عدة»","url":""}]},{"id":"s6-1015","number":1015,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا استُعير ﴿الصراط المستقيم﴾ للدين الحق؟","answer":"لأن الدين يوصل سالكه إلى رضوان الله كما يوصل الطريق المستقيم إلى الغاية، ولا يضل سالكه بتعرج أو تشعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص630، تحت عنوان «بلاغة استعارة الصراط للدين القويم بجامع المشاكلة»","url":""}]},{"id":"s6-1400","number":1400,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا عُرّف الدين بأنه ﴿ملة إبراهيم﴾ بطريق الإضافة؟","answer":"لإبراز صلته بإبراهيم عليه السلام الذي يعظمه العرب وأهل الكتاب، وإقامة الحجة بأن التوحيد الخالص هو ملته الحقيقية لا ما نسبه المشركون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص632–633، تحت عنوان «حكمة التعبير بملة إبراهيم بطريق الإضافة»","url":""}]},{"id":"s6-1016","number":1016,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا وُصف الدين بأنه ﴿قِيَمًا﴾؟","answer":"للمبالغة في استقامته وثباته على الحق، فهو دين مستقيم في ذاته ومقيم لمصالح من يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص632، تحت عنوان «وصف الدين بأنه قيم من باب الاستعارة»","url":""}]},{"id":"s6-1017","number":1017,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"لماذا عُدل من نفي الشرك عن إبراهيم مفردًا إلى قوله: ﴿وما كان من المشركين﴾؟","answer":"لينفي عنه الانتماء إلى جماعة المشركين ومنهجهم كله، لا مجرد وقوع فعل شرك منه؛ وفيه إبطال لادعائهم أنهم على ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص635، تحت عنوان «نكتة العدول عن نفي الإشراك إفرادًا إلى نفي الإشراك جمعًا»","url":""}]},{"id":"s6-1018","number":1018,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما الفرق بين قوله في الأنعام: ﴿دينًا قيمًا﴾ وقوله في الفاتحة: ﴿الصراط المستقيم﴾؟","answer":"في الفاتحة طلب للهداية إلى ﴿الصراط المستقيم﴾ والثبات عليه. أما في الأنعام فالمقام بيان مزية الدين الذي هدى الله إليه نبيه؛ فجاء ﴿دينًا قِيَمًا﴾ وصفًا بالمصدر للمبالغة، كأن الدين هو الاستقامة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص401، تحت «مستقيم وقيم»","url":""}]},{"id":"s6-1019","number":1019,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"ما دلالة التعبير بالمصدر الميمي في قوله تعالى: ﴿محياي ومماتي﴾؟","answer":"يجمع زمن الحياة وما يقع فيه من أعمال، وحال الموت وما يتصل به من مصير؛ ليعلن أن الوجود كله لله لا لحظة عبادة منفصلة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص640–641، تحت عنوان «دلالات التعبير بالمصدر الميمي ﴿ومحياي ومماتي﴾»","url":""}]},{"id":"s6-1020","number":1020,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"لماذا قُدمت الصلاة والنسك على المحيا والممات؟","answer":"لأن العبادة هي المقصد الذي ينبغي أن تنتظم به الحياة كلها، فبدأ بأظهر أعمال الإخلاص ثم عمّ الحياة والموت وما يتصل بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص639، تحت عنوان «بلاغة الترتيب بين (الصلاة) و(النسك) و(المحيا) و(الممات)»","url":""}]},{"id":"s6-1401","number":1401,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"لماذا عُطف ﴿نسكي﴾ على ﴿صلاتي﴾؟","answer":"لإبراز إخلاص النسك لله مع الصلاة؛ فإن أريد به الذبح خُص بعد أعظم العبادات، وإن أريد مطلق العبادة جمع الخاص والعام لتأكيد الشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص640، تحت عنوان «نكتة عطف النسك على الصلاة»","url":""}]},{"id":"s6-1021","number":1021,"surah":6,"verses":[162],"references":[{"surah":6,"verses":[162]}],"verseLabel":"الأنعام: 162","question":"ما سرّ الجمع بين الألوهية والربوبية في قوله تعالى: ﴿لله رب العالمين﴾؟","answer":"إفراد العبادة له يقتضيه كونه رب العالمين؛ فهو المستحق لها بما تفضل به من الخلق والرزق، وبيده الحياة والموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص642، تحت «نكتة الجمع بين الألوهية والربوبية في ﴿لله رب العالمين﴾»","url":""}]},{"id":"s6-1022","number":1022,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"لماذا جاءت جملة ﴿لا شريك له﴾ بعد إعلان أن العبادة والمحيا والممات لله؟","answer":"لتبين أن هذا الإخلاص خالص من كل مشاركة؛ فلا يتوجه شيء من العبادة أو الحياة أو المصير إلى غير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص642، تحت عنوان «الموقع النحوي والبياني لجملة التوحيد ﴿لا شريك له﴾»","url":""}]},{"id":"s6-1023","number":1023,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"ما سرّ بناء ﴿وبذلك أمرت﴾ للمجهول؟","answer":"لم يسم الآمر لأن كونه الله معلوم من السياق لا يلتبس بغيره؛ فحذف الفاعل يحقق الإيجاز ويعتمد على شدة ظهوره في المقام. وبهذا يعلن الرسول أن هذا الإخلاص امتثال لما أمره الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص644، تحت «سر العدول في فعل الأمر إلى البناء للمفعول ﴿أمرت﴾»","url":""}]},{"id":"s6-1024","number":1024,"surah":6,"verses":[163],"references":[{"surah":6,"verses":[163]}],"verseLabel":"الأنعام: 163","question":"ما فائدة إضافة ﴿أول﴾ إلى ﴿المسلمين﴾ في قوله تعالى: ﴿وأنا أول المسلمين﴾؟","answer":"تحدد الأولية داخل جماعة المخاطبين وأمة النبي ﷺ؛ أي أنه أسبقهم استجابة وامتثالًا، من غير نفي إسلام الأنبياء قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص645، تحت عنوان «فائدة الإضافة في قوله تعالى: ﴿وأنا أول المسلمين﴾»","url":""}]},{"id":"s6-1025","number":1025,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا قُدّم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أبغي ربًا﴾؟","answer":"لأنه موضع الإنكار والتوبيخ؛ فطلب رب غير الله هو المستنكر مع أنه رب كل شيء، فقدم لإبراز بطلانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص651، تحت عنوان «تقديم المفعول به على الفعل والفاعل»","url":""}]},{"id":"s6-1026","number":1026,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما دلالة القصر في قوله تعالى: ﴿ولا تكسب كل نفس إلا عليها﴾؟","answer":"يحصر تبعة الكسب في صاحبه؛ فلا يحمل الإنسان غيره نتيجة شره، ولا يتجاوز ذنبه إلى نفس بريئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص654، تحت عنوان «بلاغة القصر في ﴿ولا تكسب كل نفس إلا عليها﴾»","url":""}]},{"id":"s6-1027","number":1027,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما الغرض من الإخبار بقوله تعالى: ﴿ولا تزر وازرة وزر أخرى﴾؟","answer":"يقرر عدل المسؤولية الفردية: لا تحمل نفس إثم غيرها ولا تنجو بإلقاء تبعتها عليه، فكل إنسان يلقى أثر اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص655، تحت عنوان «غرض الإخبار بنفي الوزر»","url":""}]},{"id":"s6-1402","number":1402,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا صُوّر الإثم بالوزر في قوله تعالى: ﴿ولا تزر وازرة وزر أخرى﴾؟","answer":"لأن الوزر حمل ثقيل، فصورت الاستعارة الذنب عبئًا يثقل صاحبه ولا يستطيع أن ينقله إلى سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص656، تحت عنوان «تشبيه الإثم بالوزر في الآية الكريمة من باب الاستعارة»","url":""}]},{"id":"s6-1028","number":1028,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إلى ربكم مرجعكم﴾؟","answer":"تفيد الانتقال بعد انقضاء الحياة إلى الرجوع والحساب؛ فمهما طال الإمهال تبقى النهاية الموعودة آتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص656، تحت عنوان «دلالة ﴿ثم﴾ العاطفة في قوله: ﴿ثم إلى ربكم مرجعكم﴾»","url":""}]},{"id":"s6-1403","number":1403,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا قُدّم قوله تعالى: ﴿إلى ربكم﴾ على ﴿مرجعكم﴾؟","answer":"للاهتمام والاختصاص: المرجع النهائي إلى الله وحده، وفي وصفه بربهم تذكير بسلطانه وتربيته ووعده ووعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص657، تحت عنوان «بلاغة تقديم الجار والمجرور»","url":""}]},{"id":"s6-1029","number":1029,"surah":6,"verses":[164],"references":[{"surah":6,"verses":[164]}],"verseLabel":"الأنعام: 164","question":"لماذا عُبّر بالموصول العام ﴿ما﴾ في قوله تعالى: ﴿بما كنتم فيه تختلفون﴾؟","answer":"ليشمل كل ما وقع فيه اختلاف من أمر الدين والحق والباطل، من غير حصر في مسألة واحدة؛ وسيكشف الله حقيقته ويحكم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص659، تحت عنوان «دلالة التعبير بالموصول (ما)»","url":""}]},{"id":"s6-1030","number":1030,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما دلالة التعبير بقوله تعالى: ﴿جعلكم خلائف الأرض﴾؟","answer":"يصور الناس أجيالًا يخلف بعضها بعضًا في عمارة الأرض، وفيه تكريم بالتمكين وتذكير بأن المقام مؤقت ينتقل إلى من بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص665، تحت عنوان «نكتة التعبير بقوله ﴿خلائف﴾ مادة وصيغة»","url":""}]},{"id":"s6-1404","number":1404,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما الغرض من إخبار الناس بأن الله جعلهم خلائف الأرض؟","answer":"ليوقظهم إلى نعمة التمكين ومسؤوليته؛ فمن ورث الأرض ممن قبله سيتركها لمن بعده ويحاسب على ما صنع فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص667، تحت عنوان «غرض المجيء بخبر جعلهم خلائف»","url":""}]},{"id":"s6-1031","number":1031,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما الصورة في قوله تعالى: ﴿ورفع بعضكم فوق بعض﴾؟","answer":"استعير الرفع الحسي لتفاوت الناس في المواهب والرزق والمكانة، ليصبح اختلاف أحوالهم كدرجات يعلو بعضها بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص668، تحت عنوان «بلاغة الاستعارة في رفع الدرجات في الآية الكريمة»","url":""}]},{"id":"s6-1405","number":1405,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا جاءت ﴿درجات﴾ جمعًا منكرة؟","answer":"لتدل على كثرة مراتب التفاوت وتنوعها، فهي ليست منزلة واحدة ولا نوعًا واحدًا من العطاء، بل درجات لا يحصيها وصف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص669، تحت عنوان «نكتة ورود كلمة درجات بالجمع والتنكير»","url":""}]},{"id":"s6-1032","number":1032,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ماذا يكشف قوله تعالى: ﴿ليبلوكم﴾ عن حكمة تفاوت العطايا؟","answer":"يكشف أن التفاوت امتحان لا معيار كرامة مطلقًا؛ ليظهر شكر من وُسّع عليه وصبر من ضُيق عليه، ويحاسب كلٌ على ما أُعطي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص669، تحت عنوان «دلالة (اللام) في قوله: ﴿ليبلوكم﴾ على التعليل»","url":""}]},{"id":"s6-1406","number":1406,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما دلالة التعبير بالإيتاء في قوله تعالى: ﴿فيما آتاكم﴾؟","answer":"يصوّر ما في أيدي الناس عطية من الله لا ملكًا مستقلًا، فيستدعي الشكر وحسن التصرف ويمنع الاغترار بالتفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص670، تحت عنوان «بلاغة التعبير بالإيتاء مادة وصيغة»","url":""}]},{"id":"s6-1033","number":1033,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما سرّ وصف العقاب بالسرعة مع تأخره أحيانًا؟","answer":"استعيرت السرعة لعدم التردد وكمال القدرة حين يحين وقت العقاب؛ فليس المراد وجوب وقوعه فورًا في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص671، تحت «غرض إضافة الصفة إلى الموصوف في ﴿سريع العقاب﴾»","url":""}]},{"id":"s6-1034","number":1034,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا خُتمت السورة بصفات العقاب والمغفرة والرحمة معًا؟","answer":"ليظل العبد بين الخوف والرجاء: لا يغتر بسعة الرحمة، ولا يقنط بسبب الذنب، بل يبادر إلى التوبة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص671، تحت عنوان «نكتة ختم الآية بصفات العقاب والمغفرة والرحمة»","url":""}]},{"id":"s6-1407","number":1407,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا قُدّم الوعيد ﴿سريع العقاب﴾ على الوعد ﴿لغفور رحيم﴾؟","answer":"لأن السياق يواجه التكذيب ويحذر من عاقبته، فناسب تقديم الزجر؛ ثم أعقبه الوعد ليفتح باب الرجوع ولا يختم السورة على اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص672، تحت عنوان «نكتة تقديم الوعيد على الوعد في أسمائه»","url":""}]},{"id":"s6-1035","number":1035,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"لماذا دخلت اللام على ﴿لغفور﴾ ولم تدخل على ﴿سريع العقاب﴾؟","answer":"لترجيح جانب المغفرة والرحمة وتوكيده بعد الوعيد؛ فالعقاب ثابت في موضعه، لكن باب الرجاء أُبرز بتوكيد زائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص672، تحت عنوان «دخول اللام على لفظ ﴿لغفور﴾ وعدم دخولها على ﴿سريع﴾»","url":""}]},{"id":"s6-1421","number":1421,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما سر ختم ﴿وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾، وفي يونس ﴿وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ﴾؟","answer":"آية الأنعام في افتراض مسّ الخير، وآية يونس في افتراض إرادته. والإرادة من غير الله قد لا تتحقق لحائل يحول دونها، أما إرادته سبحانه فلا رادّ لها. ولما اتفق الافتراضان في مسّ الضر اتفق الجوابان ﴿فَلَا كَاشِفَ لَهُ إِلَّا هُوَ﴾، ولما اختلفا في الخير اختلف التعقيبان.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص56.","url":""}]},{"id":"s6-1422","number":1422,"surah":6,"verses":[20,21],"references":[{"surah":6,"verses":[20,21]}],"verseLabel":"الأنعام: 20، 21","question":"ما سر الختم بـ﴿إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ﴾ بعد وصفهم بأنهم ﴿خَسِرُوا أَنفُسَهُمْ﴾؟","answer":"لما وصفهم بأنهم خسروا أنفسهم، وهي أثمن شيء، ناسب أن ينفي عنهم الفلاح؛ فمن خسر مالًا قد يأتيه الفلاح من جهة أخرى، أما من خسر نفسه فمن أين يأتيه الفلاح ولم تعد له نفس؟ ولذلك أكّد الكلام بـ«إنّ» وجاء بضمير الشأن للدلالة على عِظَم الخسارة وانتفاء الفلاح.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص217.","url":""}]},{"id":"s6-1423","number":1423,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما سر التعبير بـ﴿أَرَأَيْتَكُمْ إِنْ أَتَاكُمْ عَذَابُ اللَّهِ﴾، وفي مريم ﴿أَن يَمَسَّكَ عَذَابٌ مِّنَ الرَّحْمَٰنِ﴾؟","answer":"التحذير في آية الأنعام أشد من أوجه: ف«أرأيتكم» بحرف الخطاب مع الضمير آكد من «أرأيتم»، والإتيان أشد من مجرد المسّ، وأضاف العذاب إلى الله ولم يجعله من «الرحمن». وزاد ﴿بَغْتَةً أَوْ جَهْرَةً﴾، وجعل العذاب مهلكًا مستأصلًا ﴿هَلْ يُهْلَكُ إِلَّا الْقَوْمُ الظَّالِمُونَ﴾. ثم إن اسم «الرحمن» لم يرد في الأنعام، وورد لفظ الجلالة فيها نحو سبع وثمانين مرة، فناسب سمتها التعبيرية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص44–45.","url":""}]},{"id":"s6-1424","number":1424,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر مجيء الفعل تامًّا بتاءين في ﴿أَفَلَا تَتَذَكَّرُونَ﴾؟","answer":"الكلام في محاجّة إبراهيم لقومه العريقين في الشرك، وهم محتاجون إلى طول التذكر وإدامة التفكر ليهتدوا إلى التوحيد، كما تأمل إبراهيم في ملكوت السماوات والأرض. فجاء بالفعل كاملًا لم يحذف منه شيئًا، وناسب ذلك أيضًا مقامَ التفصيل والإطالة فيما حُكي عن اهتدائه من الكوكب إلى القمر إلى الشمس.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص17.","url":""}]},{"id":"s6-1425","number":1425,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما سر التعبير بـ﴿أَجْرًا … إِنْ هُوَ إِلَّا ذِكْرَىٰ﴾ هنا، وفي يوسف ﴿مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ﴾؟","answer":"«الذِّكر» أعم من «الذكرى»، فهو يشمل الحفظ والشرف إلى جانب التذكير، وهذا يناسب ما في قصة يوسف من سعة. وآية الأنعام مفردة في سياقها، أما سياق يوسف فأوسع، فناسبه «مِن» الاستغراقية. ثم إن ﴿مِنْ أَجْرٍ﴾ أكثر حروفًا، فقابل السعةَ بالسعة والإيجازَ بالإيجاز.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص46–47.","url":""}]},{"id":"s6-1426","number":1426,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما سر تقديم ﴿لَا إِلَٰهَ إِلَّا هُوَ﴾ على ﴿خَالِقُ كُلِّ شَيْءٍ﴾ هنا، وعكسه في غافر؟","answer":"السياق في الأنعام سياق الإنكار على الشرك والدعوة إلى التوحيد الخالص ونفي الصاحبة والولد، فقد سبقها ﴿وَجَعَلُوا لِلَّهِ شُرَكَاءَ الْجِنَّ﴾ و﴿أَنَّىٰ يَكُونُ لَهُ وَلَدٌ﴾، فقدّم كلمة التوحيد لأنها المناسبة للمقام. ونظيره أنه أخّر ﴿وَخَلَقَ كُلَّ شَيْءٍ﴾ في الآية السابقة بعد نفي الولد والصاحبة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص67.","url":""}]},{"id":"s6-1427","number":1427,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما دلالة التشبيه في ﴿يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ﴾؟","answer":"السماء هنا بمعنى الجوّ العالي، ومن يصعد في الجو يضيق صدره ويحرج لاختلاف الضغط وقلّة الهواء كلما ارتفع. فشبّه ضيق صدر الضال بحال المتصعّد في الجو، وهذا من الإعجاز العلمي فوق ما في التعبير من إعجاز لغوي، إذ لم يكن ذلك معروفًا وقت التنزيل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص43.","url":""}]},{"id":"s6-1428","number":1428,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"ما دلالة التضعيف في ﴿ذَٰلِكُمْ وَصَّاكُم بِهِ﴾ دون «أوصاكم»؟","answer":"يستعمل القرآن «وصّى» بالتضعيف في الأمور المعنوية وأمور الدين، و«أوصى» في الأمور المادية كالميراث. وما في هذه الآيات من توحيد وبرّ وتحريم للفواحش والقتل من أصول الدين، فناسبه الفعل المضعّف الدال على الاهتمام والتوكيد.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص59.","url":""}]},{"id":"s6-1429","number":1429,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سر اقتران الوزن بـ«القسط» في ﴿وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ﴾؟","answer":"الغرض من الوزن أن يأخذ كل شخص حصته ونصيبه، وهذا من معاني القسط. ولذلك لم يرد مع الوزن في القرآن إلا لفظ «القسط» ولم يستعمل معه «العدل»، كما في هود والأنبياء والرحمن، بل إن من أسماء الميزان «القسطاس».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص289.","url":""}]},{"id":"s6-1430","number":1430,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سر تقديم الجار والمجرور في ﴿وَبِعَهْدِ اللَّهِ أَوْفُوا﴾، وفي الإسراء ﴿وَأَوْفُوا بِالْعَهْدِ﴾؟","answer":"التقديم في الأنعام للاهتمام والعناية، لأنه أضاف العهد إلى الله فازداد تفخيمًا. وهو عهد مطلق يشمل ما عهده الله إلى عباده وما تعاهد عليه الخلق فيما بينهم، بخلاف آية النحل ﴿وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدتُّمْ﴾ فهي مقيّدة بما يلتزمه الإنسان باختياره، فقدّم فيها الفعل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص287.","url":""}]},{"id":"s6-1431","number":1431,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة التعبير بـ«صدف» في ﴿مِمَّن كَذَّبَ بِآيَاتِ اللَّهِ وَصَدَفَ عَنْهَا﴾، وبـ«أعرض» في الكهف والسجدة؟","answer":"الصُّدوف إعراض شديد، مأخوذ من الصَّدَف وهو جانب الجبل الصلب. وفي آية الأنعام اجتمع التكذيب مع الإعراض، وهو أشد من الإعراض وحده، فاختار اللفظ الأشد، ولذلك كان الجزاء أشد أيضًا ﴿سَنَجْزِي الَّذِينَ يَصْدِفُونَ عَنْ آيَاتِنَا سُوءَ الْعَذَابِ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص51–52.","url":""}]},{"id":"s6-1432","number":1432,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما سر الوصف بالمصدر في ﴿دِينًا قِيَمًا مِّلَّةَ إِبْرَاهِيمَ حَنِيفًا﴾، وفي التوبة ﴿ذَٰلِكَ الدِّينُ الْقَيِّمُ﴾؟","answer":"«قِيَم» مصدر، والوصف بالمصدر آكد من الوصف بالصفة «القيّم»، كأن الدين هو الاستقامة نفسها. وهذا يناسب سعة السياق ﴿إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ﴾. وقد أكّد الاستقامة بثلاثة تعبيرات: ﴿صِرَاطٍ مُّسْتَقِيمٍ﴾ و﴿قِيَمًا﴾ و﴿حَنِيفًا﴾، وفي الآية قراءة متواترة «قَيِّمًا».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص53–55.","url":""}]},{"id":"s6-1433","number":1433,"surah":6,"verses":[1,164],"references":[{"surah":6,"verses":[1,164]}],"verseLabel":"الأنعام: 1، 164","question":"ما سر المناسبة بين مطلع السورة ﴿ثُمَّ الَّذِينَ كَفَرُوا بِرَبِّهِمْ يَعْدِلُونَ﴾ وختامها ﴿قُلْ أَغَيْرَ اللَّهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ﴾؟","answer":"ذكر في البدء أن الذين كفروا بربهم يعدلون، وفي الختام أن الرسول لا يعدل بربه شيئًا، حتى كأن التعبيرين آية واحدة. وتناظر التعبيران: فقدّم في الأول متعلق «يعدلون» وهو ﴿بِرَبِّهِمْ﴾، وقدّم في الآخر مفعول «أبغي» وهو ﴿أَغَيْرَ اللَّهِ﴾. ثم قال في البدء ﴿الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ﴾، وفي الختام ﴿وَهُوَ رَبُّ كُلِّ شَيْءٍ﴾، والذي خلق ذلك هو رب كل شيء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص257.","url":""}]},{"id":"s6-1434","number":1434,"surah":6,"verses":[5],"references":[{"surah":6,"verses":[5]}],"verseLabel":"الأنعام: 5","question":"ما سر ذكر ﴿بِالْحَقِّ﴾ والتعبير بـ«سوف» في ﴿فَقَدْ كَذَّبُوا بِالْحَقِّ لَمَّا جَاءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنبَاءُ﴾، وفي الشعراء ﴿فَقَدْ كَذَّبُوا فَسَيَأْتِيهِمْ﴾؟","answer":"ترددت كلمة «الحق» في الأنعام اثنتي عشرة مرة ولم ترد في الشعراء، فناسب ذكرها جوَّ السورة. و«سوف» أبعد في الاستقبال من السين: فالمعنيون في الشعراء قوم الرسول ﷺ خاصة فناسب تعجيل الوعيد، وفي الأنعام عموم الكافرين. ثم إن سورة الأنعام مبنية على تأخير العقوبة: ﴿كَتَبَ عَلَىٰ نَفْسِهِ الرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ الْقِيَامَةِ﴾، و﴿مَا عِندِي مَا تَسْتَعْجِلُونَ بِهِ﴾، فناسب ذلك «سوف».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص188–190.","url":""}]},{"id":"s6-1435","number":1435,"surah":6,"verses":[7,8],"references":[{"surah":6,"verses":[7,8]}],"verseLabel":"الأنعام: 7–8","question":"ما سر التعبير بـ﴿نَزَّلْنَا﴾ في ﴿وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَابًا فِي قِرْطَاسٍ﴾، ثم بـ﴿أَنزَلْنَا﴾ في ﴿وَلَوْ أَنزَلْنَا مَلَكًا﴾؟","answer":"«فعّل» أهم وآكد من «أفعل»، كـ«وصّى» و«أوصى». وتنزيل القرطاس إما أن ينزل بنفسه حتى يصل إلى الرسول وهو عجب، أو يكون بإنزال ملك به، فهو إنزال قرطاس وملك معًا، وهو أهم وأعجب من إنزال الملك وحده. ولذلك قالوا فيه ﴿إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ﴾، ولم يقولوا نحو ذلك في إنزال الملك.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص42.","url":""}]},{"id":"s6-1436","number":1436,"surah":6,"verses":[10],"references":[{"surah":6,"verses":[10]}],"verseLabel":"الأنعام: 10","question":"ما الفرق بين «الاستهزاء» و«السخرية» في ﴿وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِالَّذِينَ سَخِرُوا مِنْهُم﴾؟","answer":"الاستهزاء هو الاستخفاف والاستحقار والتنبيه على العيوب على وجه يُضحك منه، وقد يكون من غير أن يسبق من المُستهزَأ به فعل. أما السخرية فتدل على فعل يسبق من المسخور منه، ولم ترد في القرآن إلا من الأشخاص. فذكر الاستهزاء والسخرية معًا ليشمل الأفعال والأشخاص، وما سبق منهم من فعل وما لم يسبق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص42–43.","url":""}]},{"id":"s6-1437","number":1437,"surah":6,"verses":[21],"references":[{"surah":6,"verses":[21]}],"verseLabel":"الأنعام: 21","question":"ما سر تنكير «كذبًا» في ﴿وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا﴾، وتعريفه في الصف ﴿افْتَرَىٰ عَلَى اللَّهِ الْكَذِبَ﴾؟","answer":"إذا كان الافتراء في أمر معيَّن عُرِّف، وإذا كان عامًّا لا ينحصر في شيء نُكِّر. فآية الصف في افتراء متعلق بصفة النبي ﷺ والتبشير به فعرّفه، أما في الأنعام فهم يفترون على الله في أمور متعددة ونواحٍ مختلفة لا تنحصر في أمر معين، فنكّره.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص217.","url":""}]},{"id":"s6-1438","number":1438,"surah":6,"verses":[32],"references":[{"surah":6,"verses":[32]}],"verseLabel":"الأنعام: 32","question":"ما سر الاقتصار على اللعب واللهو في ﴿وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا لَعِبٌ وَلَهْوٌ﴾، مع زيادة الزينة والتفاخر والتكاثر في سورة الحديد؟","answer":"ما ذُكر في الحديد من زينة وتفاخر وتكاثر في الأموال والأولاد يندرج تحت اللهو، فالزينة قد تلهي، والتفاخر قد يلهي، والتكاثر قد يلهي. ولما فصّل في الحديد في حقيقة الحياة الدنيا فصّل في وصفها وعاقبتها، ولما أجمل في الأنعام اكتفى باللعب واللهو ثم انتقل إلى ذكر الآخرة ﴿وَلَلدَّارُ الْآخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص277.","url":""}]},{"id":"s6-1439","number":1439,"surah":6,"verses":[37],"references":[{"surah":6,"verses":[37]}],"verseLabel":"الأنعام: 37","question":"ما سر التضعيف في ﴿وَقَالُوا لَوْلَا نُزِّلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ﴾، وفي العنكبوت ﴿لَوْلَا أُنزِلَ عَلَيْهِ آيَاتٌ مِّن رَّبِّهِ﴾؟","answer":"موقف الشدة والمجادلة بالباطل والعنت والتكذيب في سياق الأنعام أظهر وأوضح، فاستعمل الفعل المضعّف «نزّل» في مقام الشدة وقوة المواجهة. ونقل السامرائي عن صاحب «ملاك التأويل» أن آية العنكبوت لم يتقدمها من التهديد وشديد الوعيد ما تقدم آية الأنعام، فناسبها الفعل غير المضعّف.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص63–64.","url":""}]},{"id":"s6-1440","number":1440,"surah":6,"verses":[48],"references":[{"surah":6,"verses":[48]}],"verseLabel":"الأنعام: 48","question":"ما سر التعبير بـ﴿فَمَنْ آمَنَ وَأَصْلَحَ﴾، وفي الأعراف ﴿فَمَنِ اتَّقَىٰ وَأَصْلَحَ﴾؟","answer":"ورد الإيمان ومشتقاته في الأنعام أربعًا وعشرين مرة، وفي الأعراف إحدى وعشرين. ووردت التقوى ومشتقاتها في الأعراف إحدى عشرة مرة، وفي الأنعام سبع مرات. فوُضعت كل مفردة في السورة التي تتردد فيها أكثر.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص182.","url":""}]},{"id":"s6-1441","number":1441,"surah":6,"verses":[51],"references":[{"surah":6,"verses":[51]}],"verseLabel":"الأنعام: 51","question":"ما سر النفي بـ«ليس» في ﴿لَيْسَ لَهُم مِّن دُونِهِ وَلِيٌّ وَلَا شَفِيعٌ﴾، وفي السجدة ﴿مَا لَكُم مِّن دُونِهِ مِن وَلِيٍّ وَلَا شَفِيعٍ﴾؟","answer":"النفي في السجدة أقوى، فهي جملة اسمية منفية بـ«ما»، والاسمية أقوى من الفعلية و«ما» أقوى من «ليس»، مع «مِن» الاستغراقية. والكلام في آيتي الأنعام على أصناف خاصة، كالذين يخافون أن يُحشروا إلى ربهم. أما آية السجدة ففي قوم كذّبوا الرسول وأنكروا الحشر، فاقتضى السياق توكيد نفي الولي والشفيع.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص56–57؛ والتعبير القرآني، ص142.","url":""}]},{"id":"s6-1442","number":1442,"surah":6,"verses":[62],"references":[{"surah":6,"verses":[62]}],"verseLabel":"الأنعام: 62","question":"ما دلالة التعبير بالردّ في ﴿ثُمَّ رُدُّوا إِلَى اللَّهِ مَوْلَاهُمُ الْحَقِّ﴾؟","answer":"يستعمل القرآن الردّ للكافرين، واستعمله هنا في خطاب عموم الخلق من المكلفين. ومما يوضح ذلك أنه يستعمل الفعل «ردّ» في العقوبات والعذاب، ولم يستعمل «رجع» في ذلك، كقوله في السورة نفسها: ﴿وَلَا يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص49.","url":""}]},{"id":"s6-1443","number":1443,"surah":6,"verses":[63],"references":[{"surah":6,"verses":[63]}],"verseLabel":"الأنعام: 63","question":"ما سر التعبير بـ﴿تَضَرُّعًا وَخُفْيَةً﴾ من الخفاء، وفي الأعراف ﴿تَضَرُّعًا وَخِيفَةً﴾ من الخوف؟","answer":"الدعاء والذكر في آيتي الأعراف في مقام العبادة، والخوف فيهما من الله. أما آية الأنعام ففي مقام الخوف مما يحيط بالناس في ظلمات البر والبحر، فلو ذكر الخوف لانصرف إلى هذه الأمور المخوفة لا إلى الخوف من الله، فذكر الخُفية وهي نقيض الجهر.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص70–71.","url":""}]},{"id":"s6-1444","number":1444,"surah":6,"verses":[73],"references":[{"surah":6,"verses":[73]}],"verseLabel":"الأنعام: 73","question":"ما سر التعبير بصيغة «عالِم» في ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ﴾، وبصيغة «علّام» في ﴿عَلَّامُ الْغُيُوبِ﴾؟","answer":"لم يرد «عالم» في القرآن إلا مع «الغيب» مفردًا، ولم يرد «علّام» إلا مع «الغيوب» جمعًا. فلما جمع الغيوب جاء بصيغة المبالغة «علّام» الدالة على الكثرة، ولما أفرد الغيب جاء باسم الفاعل «عالم»، فطابقت الصيغة ما تعلّقت به إفرادًا وجمعًا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص35.","url":""}]},{"id":"s6-1445","number":1445,"surah":6,"verses":[78],"references":[{"surah":6,"verses":[78]}],"verseLabel":"الأنعام: 78","question":"ما سر قول إبراهيم ﴿إِنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ﴾، وفي الزخرف ﴿إِنَّنِي بَرَاءٌ مِّمَّا تَعْبُدُونَ﴾؟","answer":"إبراهيم في الأنعام في مقام الحيرة والبحث عن الحقيقة، ظنّ الكوكب ربه ثم القمر ثم الشمس ثم أعلن البراءة. أما في الزخرف فهو نبي مرسل في مقام التبليغ أعلن حربه على الشرك، فكانت البراءة هناك أشد، فأكّدها من جهتين: زيادة النون في «إنني»، والعدول من الصفة «بريء» إلى المصدر «براء».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص358–359؛ والتعبير القرآني، ص37.","url":""}]},{"id":"s6-1446","number":1446,"surah":6,"verses":[83],"references":[{"surah":6,"verses":[83]}],"verseLabel":"الأنعام: 83","question":"ما سر تقديم «الحكيم» على «العليم» في ﴿إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ﴾؟","answer":"حيثما اجتمع الاسمان في سورة الأنعام قُدِّم «الحكيم»، لأن المقام فيها مقام تشريع وأحكام، كتحليل الأنعام وتحريمها، والحكمة أنسب بذلك. أما في سورة يوسف فقُدِّم «العليم» لأن المقام مقام علم، كعلم تأويل الأحاديث ورؤيا الملك. وقد نقل السامرائي هذا التوجيه عن صاحب البرهان.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص232.","url":""}]},{"id":"s6-1447","number":1447,"surah":6,"verses":[83,86],"references":[{"surah":6,"verses":[83,86]}],"verseLabel":"الأنعام: 83، 86","question":"ما سر ترتيب الأنبياء في قوله ﴿وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ … وَلُوطًا﴾؟","answer":"يذكر ثلاثة ثم يرجع إلى من سبقهم: نوحًا ثم إلياس ثم لوطًا. والرابط بين كل اثنين متجاورين ظاهر: إبراهيم وإسحاق ويعقوب أب وأبناء، وداود وسليمان أب وابن جمعهما الملك، وسليمان وأيوب كلاهما ﴿نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾ فهذا الغني الشاكر وذاك الفقير الصابر، وأيوب ويوسف ابتُليا ثم أُنعم عليهما، ويوسف وموسى رسولان متعاقبان، وموسى وهارون أخوان.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص60–61.","url":""}]},{"id":"s6-1448","number":1448,"surah":6,"verses":[84,86],"references":[{"surah":6,"verses":[84,86]}],"verseLabel":"الأنعام: 84، 86","question":"ما سر اختلاف خواتيم الآيات: ﴿وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ﴾، ﴿كُلٌّ مِّنَ الصَّالِحِينَ﴾، ﴿وَكُلًّا فَضَّلْنَا عَلَى الْعَالَمِينَ﴾؟","answer":"كل خاتمة تناسب من ذُكروا فيها. فالآية الأولى في الذين جُوزوا في الدنيا بالملك أو بالغنى بعد البلاء أو بالنصر، فختمها بـ﴿نَجْزِي الْمُحْسِنِينَ﴾. والثانية في زكريا ويحيى وعيسى وإلياس، وقد قُتلوا أو كادوا، فلم يُجزوا في الدنيا فقال ﴿مِّنَ الصَّالِحِينَ﴾. والثالثة في إسماعيل واليسع ويونس ولوط، أُعطوا الرسالة والتفضيل من غير ملك ولا قتل، فقال ﴿فَضَّلْنَا عَلَى الْعَالَمِينَ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص63–65.","url":""}]},{"id":"s6-1449","number":1449,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما سر حذف الضمير في ﴿أُولَٰئِكَ الَّذِينَ هَدَى اللَّهُ﴾، وذكره في الزمر ﴿أُولَٰئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ﴾؟","answer":"ذكر الهداية مع هؤلاء الأنبياء بكل أنواع التعدية: بالاسم الظاهر ﴿وَنُوحًا هَدَيْنَا﴾، وبالضمير ﴿وَهَدَيْنَاهُمْ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ﴾. ثم حذف المفعول في ﴿هَدَى اللَّهُ﴾ فاتسع المعنى ليحتمل: هداهم الله، وهدى الله بهم. فهم مهديّون وهادون، وهذا أوسع وأمدح لهم من ذكر الضمير الذي يقصر المعنى على وجه واحد.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص21–23.","url":""}]},{"id":"s6-1450","number":1450,"surah":6,"verses":[91],"references":[{"surah":6,"verses":[91]}],"verseLabel":"الأنعام: 91","question":"ما سر وصف التوراة بالنور في ﴿نُورًا وَهُدًى لِّلنَّاسِ﴾، ووصفها بالضياء في الأنبياء ﴿وَضِيَاءً وَذِكْرًا لِّلْمُتَّقِينَ﴾؟","answer":"النور أعم من الضياء. وجعلها في الأنعام ﴿لِّلنَّاسِ﴾ وهم أعم من المتقين، فناسب العامُّ العامَّ. أما في الأنبياء فجعلها ﴿لِّلْمُتَّقِينَ﴾ وهم أخص، فناسبهم الضياء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص133–134.","url":""}]},{"id":"s6-1451","number":1451,"surah":6,"verses":[94],"references":[{"surah":6,"verses":[94]}],"verseLabel":"الأنعام: 94","question":"ما سر ذكر ﴿فُرَادَىٰ﴾ و﴿وَتَرَكْتُم مَّا خَوَّلْنَاكُمْ وَرَاءَ ظُهُورِكُمْ﴾ هنا، وخلوّ آية الكهف ﴿لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ﴾ منهما؟","answer":"آية الأنعام في الموت في الدنيا، حين يفارق الإنسان أهله وماله فيبقى المال للورثة، فذكر أنه جاء فردًا وترك ما خُوِّل وراء ظهره. أما آية الكهف ففي العرض على الله يوم القيامة، وقد سُوِّيت الأرض ولم يبق عليها شيء، فلا معنى لذكر ما تُرك وراء الظهور.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص48–49.","url":""}]},{"id":"s6-1452","number":1452,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما سر تقديم «شركاء» على «الجن» في ﴿وَجَعَلُوا لِلَّهِ شُرَكَاءَ الْجِنَّ﴾؟","answer":"التقديم هنا يوسّع المعنى: فهو إنكار أن يكون لله شريك أصلًا، ثم بيّن الشركاء بقوله «الجن». ولو قيل: وجعلوا الجن شركاء لله، لوقع الإنكار على كون الجن خاصة شركاء، فلو كان غيرهم شريكًا لم يدخل في الإنكار. وقد استشهد السامرائي في ذلك بكلام عبد القاهر في «دلائل الإعجاز».","sources":[{"label":"فاضل السامرائي، الجملة العربية والمعنى، ص186–187.","url":""}]},{"id":"s6-1453","number":1453,"surah":6,"verses":[100],"references":[{"surah":6,"verses":[100]}],"verseLabel":"الأنعام: 100","question":"ما دلالة التعبير بـ«خرقوا» في ﴿وَخَرَقُوا لَهُ بَنِينَ وَبَنَاتٍ بِغَيْرِ عِلْمٍ﴾؟","answer":"الخَرْق يجمع إلى الاختلاق والافتراء معنى الحمق والإفساد، فهو قطع الشيء على سبيل الفساد من غير تفكر ولا تدبّر. فالتعبير يصوّر أنهم افتروا ذلك بغير علم افتراءً مشوبًا بالحمق والإفساد، فهو أبلغ في ذمّهم من مجرد الاختلاق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص49.","url":""}]},{"id":"s6-1454","number":1454,"surah":6,"verses":[117],"references":[{"surah":6,"verses":[117]}],"verseLabel":"الأنعام: 117","question":"ما سر حذف الباء في ﴿إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ﴾، وذكرها في القلم ﴿أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ﴾؟","answer":"معنى آية الأنعام: الله يعلم أيّ المأمورين يضل عن سبيله، وهذا يقتضيه ما قبلها ﴿وَإِن تُطِعْ أَكْثَرَ مَن فِي الْأَرْضِ يُضِلُّوكَ﴾، فهو يعلم من الذي يغوونه ومن لا يتمكنون منه. أما مع الباء فالمعنى العلم بحال من ضلّ: كيف كان ابتداء ضلاله وما يؤول إليه. وهذا التوجيه نقله السامرائي عن الخطيب الإسكافي في «درة التنزيل».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص32–33.","url":""}]},{"id":"s6-1455","number":1455,"surah":6,"verses":[122],"references":[{"surah":6,"verses":[122]}],"verseLabel":"الأنعام: 122","question":"ما سر قوله ﴿نُورًا يَمْشِي بِهِ فِي النَّاسِ﴾، وفي الحديد ﴿نُورًا تَمْشُونَ بِهِ﴾ دون «في الناس»؟","answer":"اكتنف آيةَ الأنعام ذكرُ الناس ومعاملاتهم وافتراءاتهم وضلالهم وإضلالهم، فهي في سياق الناس وأحوالهم فناسب ذكرهم. أما آية الحديد فعامة في الدنيا ويوم القيامة، ونور يوم القيامة خاص بكل مؤمن لا يُمشى به في الناس، وقد تقدّمها ذكر الرهبانية والرأفة والرحمة، فأطلق المشي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص300–301.","url":""}]},{"id":"s6-1456","number":1456,"surah":6,"verses":[130],"references":[{"surah":6,"verses":[130]}],"verseLabel":"الأنعام: 130","question":"ما سر التعبير بـ﴿يَقُصُّونَ عَلَيْكُمْ آيَاتِي﴾، وفي الزمر ﴿يَتْلُونَ عَلَيْكُمْ آيَاتِ رَبِّكُمْ﴾؟","answer":"القَصّ أعم من التلاوة، فهو يشمل الرسل جميعًا من أُنزل عليه كتاب يُتلى ومن لم يُنزَل. وآية الأنعام خطاب لمعشر الجن والإنس عامة، فناسبها اللفظ الأعم، مع ما في السورة من ذكر أخبار الأمم السابقة. أما آية الزمر فتُقال لكل زُمرة على حدة، فناسبها الأخصّ وهو التلاوة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص65–66؛ وج2، ص50–51.","url":""}]},{"id":"s6-1457","number":1457,"surah":6,"verses":[135],"references":[{"surah":6,"verses":[135]}],"verseLabel":"الأنعام: 135","question":"ما سر اقتران الفاء بـ«سوف» في ﴿إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ﴾، وتركها في هود ﴿سَوْفَ تَعْلَمُونَ﴾؟","answer":"الفاء تزيد الكلام توكيدًا وربطًا. والتهديد في الأنعام والزمر من الله تعالى، يأمر رسوله بتبليغه ﴿قُلْ يَا قَوْمِ﴾، فكان أشد وآكد، فجاء بالفاء. أما في هود فالكلام من قول شعيب عليه السلام لقومه، فلم يؤكده هذا التوكيد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص92.","url":""}]},{"id":"s6-1458","number":1458,"surah":6,"verses":[141],"references":[{"surah":6,"verses":[141]}],"verseLabel":"الأنعام: 141","question":"ما سر قوله ﴿كُلُوا مِن ثَمَرِهِ إِذَا أَثْمَرَ﴾ هنا، وفي الآية 99 ﴿انظُرُوا إِلَىٰ ثَمَرِهِ إِذَا أَثْمَرَ وَيَنْعِهِ﴾؟","answer":"سياق الآية 99 في بيان قدرة الله وآياته الباهرة، فذكر إنزال الماء وإخراج نبات كل شيء والحب المتراكب وطلع النخل وقنوانه، وأمر بالنظر والتأمل، وختم بـ﴿إِنَّ فِي ذَٰلِكُمْ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ﴾. أما الآية 141 ففي سياق الأطعمة وما يحلّله المشركون ويحرّمونه افتراءً، فذكر ﴿مُخْتَلِفًا أُكُلُهُ﴾ وأمر بالأكل وختم بـ﴿وَلَا تُسْرِفُوا﴾، فناسب كل تعبير سياقه.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص81–83.","url":""}]},{"id":"s6-1459","number":1459,"surah":6,"verses":[145],"references":[{"surah":6,"verses":[145]}],"verseLabel":"الأنعام: 145","question":"ما سر تقديم ﴿لِغَيْرِ اللَّهِ﴾ على ﴿بِهِ﴾ في ﴿أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ﴾؟","answer":"السياق في الأنعام في الذين يفترون على الله الكذب ويشرّعون باسمه، ويجعلون لشركائهم نصيبًا أوفر مما يجعلونه لله. فالمقام مقام إبطال ما كان لغير الله، فقدّم ﴿لِغَيْرِ اللَّهِ﴾ لأنه محط الاهتمام والإنكار.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص74–75.","url":""}]},{"id":"s6-1460","number":1460,"surah":6,"verses":[148],"references":[{"surah":6,"verses":[148]}],"verseLabel":"الأنعام: 148","question":"ما سر التعبير بـ﴿لَوْ شَاءَ اللَّهُ مَا أَشْرَكْنَا﴾، وفي النحل ﴿مَا عَبَدْنَا مِن دُونِهِ مِن شَيْءٍ﴾؟","answer":"لو قيل «ما عبدنا» وحده لكان رفضًا لأصل العبادة، ولو قيل «ما عبدنا من شيء» لدخل فيه الله سبحانه، فاحتاج التعبير في النحل إلى ﴿مِن دُونِهِ﴾. أما ﴿مَا أَشْرَكْنَا﴾ فتامة المعنى بنفسها لا تحتاج إلى زيادة، فأوجز هنا وفصّل هناك بحسب حاجة المعنى.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص268.","url":""}]},{"id":"s6-1461","number":1461,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"ما سر التعبير العام ﴿وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ﴾، وفي الإسراء ﴿وَلَا تَقْرَبُوا الزِّنَىٰ﴾؟","answer":"لما كان الخطاب في الأنعام للفقراء، والفقير قد يقع في فواحش كثيرة ليسدّ حاجته، جاء باللفظ العام الشامل لكل فاحشة. ويناسب ذلك أيضًا ما سبق في السورة من قوله ﴿وَذَرُوا ظَاهِرَ الْإِثْمِ وَبَاطِنَهُ﴾، أما سياق الإسراء فمختلف فخصّ الزنى.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص284.","url":""}]},{"id":"s6-1462","number":1462,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما سر الإضافة في ﴿جَعَلَكُمْ خَلَائِفَ الْأَرْضِ﴾، وفي فاطر ﴿خَلَائِفَ فِي الْأَرْضِ﴾؟","answer":"الإضافة أعم من التعبير بـ«في»، فهي تشمل الاستخلاف في الأرض وما فيها على وجه العموم. وسياق الأنعام سياق عام شامل، فناسبته الإضافة، أما سياق فاطر فأخصّ فناسبه التعبير بحرف الظرفية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص55–56.","url":""}]},{"id":"s6-1463","number":1463,"surah":6,"verses":[165],"references":[{"surah":6,"verses":[165]}],"verseLabel":"الأنعام: 165","question":"ما سر إدخال اللام على المغفرة دون العقاب في ﴿إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ﴾، وفي الأعراف ﴿لَسَرِيعُ الْعِقَابِ﴾؟","answer":"سياق الأعراف سياق عقوبات معجّلة في الدنيا، فأكّد سرعة العقاب باللام. أما سورة الأنعام فمبنية على الإمهال وتأخير العقوبة وسعة الرحمة ﴿كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ الرَّحْمَةَ﴾، فأكّد المغفرة والرحمة باللام ولم يؤكد سرعة العقاب، فكان الختام موافقًا لجو السورة من أولها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص260 (وانظر ص190).","url":""}]},{"id":"s7-1","number":1,"surah":7,"verses":[1],"references":[{"surah":7,"verses":[1]}],"verseLabel":"الأعراف: السورة","question":"ما مناسبة مجيء سورة الأعراف بعد الأنعام، وكيف تفصل ما أُجمل فيها؟","answer":"تأتي الأعراف بعد الأنعام لتفصيل ما أُجمل فيها من أحوال الأمم والرسل وقصة آدم وإبليس ومشاهد الرحمة والعذاب؛ فكانت بسطًا لمقاصد سبقتها إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص198–199، تحت «مناسبة السورة الكريمة مع السورة بعدها»","url":""}]},{"id":"s7-2","number":2,"surah":7,"verses":[1],"references":[{"surah":7,"verses":[1]}],"verseLabel":"الأعراف: 1","question":"ما وجه افتتاح الأعراف بالحروف المقطعة ﴿المص﴾؟","answer":"من وجوه تفسيرها التنبيه إلى إعجاز القرآن؛ فهو مؤلف من الحروف التي يعرفها العرب ويستعملونها، ومع ذلك يعجزون عن الإتيان بمثله. ويذكر المصدر تعدد الأقوال في هذه الحروف، فلا يجزم بتعيين معنى واحد لكل حرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–691، تحت «شرح المفردات: ﴿المص﴾»","url":""}]},{"id":"s7-3","number":3,"surah":7,"verses":[1,2],"references":[{"surah":7,"verses":[1,2]}],"verseLabel":"الأعراف: 1–2","question":"ماذا توحي الحروف المقطعة ﴿المص﴾ في مطلع سورة الأعراف؟","answer":"توقظ السامع وتلفته إلى القرآن، وتشير إلى أن هذا الكتاب المعجز مؤلف من الحروف التي يعرفها العرب ومع ذلك عجزوا عن الإتيان بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص690–691، تحت عنوان «شرح المفردات: ﴿المص﴾»","url":""}]},{"id":"s7-4","number":4,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما الأغراض البلاغية لتنكير ﴿كتاب﴾ في مطلع السورة؟","answer":"يفيد التعظيم والتنويه بجلال القرآن، ويشير إلى أنه كتاب من جنس الكتب التي ينزلها الله على رسله، فيرد استبعادهم نزول الوحي على بشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص693، تحت عنوان «الأغراض البلاغية لتنكير لفظ ﴿كتاب﴾ بناء على تعدد المعاني»","url":""}]},{"id":"s7-5","number":5,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ بناء ﴿أنزل إليك﴾ للمجهول؟","answer":"بُني ﴿أنزل﴾ للمفعول لأن فاعل الإنزال متعين معلوم، وهو الله تعالى، فاستغني عن التصريح به اختصارًا. ويذكر المصدر جريان الأسلوب على سنن الكبرياء، مع ما توحي به مادة الإنزال من الوحي الآتي من العالم العلوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص695، تحت «نكتة بناء الفعل ﴿أنزل﴾ لما لم يسم فاعله»","url":""}]},{"id":"s7-6","number":6,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يكن في صدرك حرج منه﴾، دون أن يقال: فلا تحرج منه؟","answer":"وُجه النهي ظاهرًا إلى الحرج نفسه مبالغة في نفيه، كأنه منهي عن أن يحل بصدر الرسول ﷺ. فالتعبير يقتلع الضيق من أصله، ويقوي معنى انشراح صدره لتبليغ الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص699–700، تحت «نكتة توجيه النهي إلى الحرج في الآية الكريمة»","url":""}]},{"id":"s7-7","number":7,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"لماذا جعل القرآن الحرج في الصدر بقوله: ﴿فلا يكن في صدرك حرج منه﴾؟","answer":"عبّر بالصدر عن موطن الشعور، وصوّر الحزن والضيق النفسي كأنه مكان ضيق يحبس صاحبه؛ فنهى عن الاستسلام لهذا الأثر عند تبليغ الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698–699، تحت عنوان «بلاغة الاستعارة في قوله: ﴿فلا يكن في صدرك حرج منه﴾»","url":""}]},{"id":"s7-8","number":8,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ تقديم ﴿في صدرك﴾ على اسم ﴿يكن﴾؟","answer":"قُدّم ﴿في صدرك﴾ للاهتمام بصدر الرسول ﷺ، ولتقوية معنى ألا يكون محلًا لأي حرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698، تحت «غرض تقديم شبه الجملة في ﴿فلا يكن في صدرك﴾»","url":""}]},{"id":"s7-9","number":9,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"إلى ماذا يعود الضمير في ﴿منه﴾: إلى الكتاب أم إلى الإنذار؟","answer":"يحتمل عوده إلى الكتاب، وهو الأقرب لفظًا، أي لا يكن حرج بسببه أو من تبليغه؛ ويدخل فيه الإنذار الذي أنزل لأجله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص698، تحت «بلاغة المجاز أو الكناية في قوله: ﴿فلا يكن في صدرك حرج منه﴾»","url":""},{"label":"موسوعة التفسير البلاغي، ج12، ص700، تحت «معنى (من) في قوله تعالى: ﴿حرج منه﴾؛ وتعلق الجار في شبه الجملة ﴿منه﴾ وصلة الفاء به»","url":""}]},{"id":"s7-10","number":10,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لتنذر به وذكرى للمؤمنين﴾، فعبّر عن الإنذار بالفعل وعن التذكير بالاسم؟","answer":"جاء ﴿لتنذر﴾ فعلًا مقترنًا بلام التعليل ليبين غاية إنزال الكتاب إلى الرسول ﷺ. وجاءت ﴿ذكرى﴾ مصدرًا، وهو أدل على أن التذكير من مهام القرآن الأساسية في حياة المؤمنين، فيبرز اختلاف الصياغة مهمة الإنذار ومهمة التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص703، تحت «نكتة العدول الصرفي بين المعطوف والمعطوف عليه»","url":""}]},{"id":"s7-11","number":11,"surah":7,"verses":[2],"references":[{"surah":7,"verses":[2]}],"verseLabel":"الأعراف: 2","question":"لماذا خُص المؤمنون بالذكرى مع أن الكتاب أُنزل للناس؟","answer":"لأن المؤمنين هم الذين ينتفعون بالتذكير، وفي التصريح بهم تنويه بشأنهم ومكانتهم عند الله، وتعريض بالكافرين الذين لا ينتفعون به. فالتخصيص يكرم أهل القبول مع عموم رسالة الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص701، تحت «بلاغة التصريح بمتعلق ﴿وذكرى﴾ دون متعلق ﴿لتنذر﴾»","url":""}]},{"id":"s7-12","number":12,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا انتقل من خطاب النبي في ﴿إليك﴾ إلى خطاب الناس: ﴿اتبعوا ما أنزل إليكم﴾؟","answer":"انتقل من خطاب الرسول ﷺ متلقي الكتاب إلى خطاب الناس المكلفين باتباعه؛ فالتبليغ للنبي والاتباع للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص709، تحت «فائدة العدول من ضمير المخاطب المفرد إلى الجمع ﴿إليكم﴾»","url":""}]},{"id":"s7-13","number":13,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا عُبّر عن القرآن بقوله تعالى: ﴿ما أنزل إليكم من ربكم﴾؟","answer":"ليعلق وجوب الاتباع بوصف الإنزال من الرب، ويعم كل ما أنزله من هداية وأحكام، فيستدعي تلقيه بالطاعة لا بمجرد المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص708، تحت عنوان «نكتة التعبير بالاسم الموصول ﴿ما﴾ عن الكتاب»","url":""}]},{"id":"s7-14","number":14,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا اختير اسم الرب في ﴿من ربكم﴾؟","answer":"اختير ﴿ربكم﴾ لاستمالتهم إلى الاتباع بتذكيرهم بأن المنزل مربيهم والمنعم عليهم والعالم بمصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص710، تحت «نكتة مجيء لفظ الرب وإضافته إلى ضمير (هم)»","url":""}]},{"id":"s7-15","number":15,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لماذا عُطف النهي ﴿ولا تتبعوا﴾ على الأمر ﴿اتبعوا﴾؟","answer":"ليجمع طريق الهداية من جهتيه: ملازمة الوحي وترك كل ولاية تخالفه؛ فاتباع الحق لا يكتمل مع طاعة من يصرف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص710، تحت عنوان «بلاغة عطف النهي ﴿ولا تتبعوا﴾ على الأمر ﴿اتبعوا﴾»","url":""}]},{"id":"s7-16","number":16,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿من دونه أولياء﴾، دون أن يقال: غيره؟","answer":"تصور ﴿من دونه﴾ الإعراض عن الله باتباع ما لم يأذن به، مع أن المشركين كانوا يزعمون أنهم يقصدون التقرب إليه بعبادة أصنامهم. فالتعبير يكشف أن هذا الاتباع إعراض عما أمر به، لا طريق قرب إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص712، تحت «نكتة الاستعارة في قوله تعالى: ﴿من دونه﴾»","url":""}]},{"id":"s7-17","number":17,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"لم نُهي عن اتباع ﴿أولياء﴾ دون الاقتصار على تسمية الشركاء والآلهة؟","answer":"الولاية تتضمن القرب والنصرة والاتباع، والمقصود هنا النهي عن اتباع غير الوحي في الهداية والدين والأحكام. فلفظ الأولياء يلائم هذا الاتباع، ولا يقصر النهي على دعوى الشراكة في الألوهية وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص715–716، تحت «(أولياء) و(شركاء) و(أنداد) و(آلهة)»","url":""}]},{"id":"s7-18","number":18,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما دلالة لفظ ﴿قليلًا﴾ في قوله تعالى: ﴿قليلًا ما تذكرون﴾؟","answer":"يوبخهم على ندرة اتعاظهم؛ فلو استحضروا نعمة الرب وحقيقة الوحي لما اتبعوا أولياء من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص713–714، تحت عنوان «بلاغة لفظ ﴿قليلًا﴾ في سياق الآية الكريمة»","url":""}]},{"id":"s7-19","number":19,"surah":7,"verses":[3],"references":[{"surah":7,"verses":[3]}],"verseLabel":"الأعراف: 3","question":"ما سرّ التعبير هنا في قوله تعالى ﴿تذكرون﴾، وفي الآية 10 ﴿تشكرون﴾؟","answer":"جاء ﴿تذكرون﴾ بعد الأمر باتباع الوحي لأن المطلوب الاتعاظ، و﴿تشكرون﴾ بعد التمكين والمعايش لأنها نعم تستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص764، تحت «نكتة التعبير بالشكر في هذا الموضع والتذكر في الموضع السابق»","url":""}]},{"id":"s7-20","number":20,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وكم من قرية أهلكناها﴾، والمراد أهلها؟","answer":"أُطلقت القرية وأريد أهلها بعلاقة المحل والحال؛ وفي ذلك تصوير للهلاك مستوعبًا المكان ومن فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص721–722، تحت «دلالة قوله: ﴿أهلكناها﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-21","number":21,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا اختيرت ﴿كم﴾ الخبرية؟","answer":"﴿كم﴾ الخبرية للتكثير، فتستحضر كثرة القرى الهالكة للتهديد والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص720، تحت «فائدة مجيء (كم) الخبرية»","url":""}]},{"id":"s7-22","number":22,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا ذُكر إهلاك القرية قبل مجيء البأس في قوله: ﴿وكم من قرية أهلكناها فجاءها بأسنا﴾؟","answer":"لأن الإهلاك ذُكر أولًا حكمًا مجملًا، ثم فُصلت كيفيته بمجيء البأس؛ فالترتيب في عرض الخبر لا في وقوع الحدث.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص722–723، تحت عنوان «علة تقديم الإهلاك على مجيء البأس في الآية الكريمة»","url":""}]},{"id":"s7-23","number":23,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا صُوّر البأس بأنه يأتي القرية؟","answer":"شُبه البأس بوافد يأتي القرية ويداهمها، تجسيمًا لشدة وقوعه ومباغتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص723، تحت «بلاغة الاستعارة في الفعل (فجاءها)»","url":""}]},{"id":"s7-24","number":24,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿بياتًا أو هم قائلون﴾، فعبّر مرة بالمصدر ومرة بالجملة؟","answer":"جاء ﴿بياتًا﴾ حالًا مفردة تبين وقت مباغتتهم، ثم جاءت ﴿هم قائلون﴾ جملة اسمية تصف هيئتهم عند نزول البأس وقت القيلولة. وفي الانتقال إلى الجملة زيادة تصوير لحالهم، مع تنويع التعبير عن الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص724–725، تحت «نكتة التعبير بالحال المفرد ﴿بياتًا﴾ والحال الجملة ﴿هم قائلون﴾»","url":""}]},{"id":"s7-25","number":25,"surah":7,"verses":[4],"references":[{"surah":7,"verses":[4]}],"verseLabel":"الأعراف: 4","question":"لماذا اختير وقتا الليل والقيلولة لنزول البأس؟","answer":"لأنهما وقتا سكون وغفلة واطمئنان، فيكون مجيء البأس فيهما أشد مباغتة وأوقع في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص725، تحت «سر اختيار وقتي البيات والقيلولة دون غيرهما»","url":""}]},{"id":"s7-26","number":26,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كان دعواهم﴾، وسمّى اعترافهم دعوى؟","answer":"تحتمل الدعوى معنى الدعاء؛ فلم يجدوا عند البأس دعاء ينجيهم، وانتهى قولهم إلى الاعتراف بالظلم. وتحتمل الادعاء؛ أي انقطعت دعاواهم الباطلة في آلهتهم ولم يبق إلا الإقرار ببطلانها وبظلم أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص727–728، تحت «معنى الدعوى ونكتتها في نوع الاستثناء بين الاتصال والانقطاع»","url":""}]},{"id":"s7-27","number":27,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"لماذا جاء التعبير بطريق القصر: ﴿إلا أن قالوا إنا كنا ظالمين﴾؟","answer":"القصر يصور انقطاع كل حجة؛ فلم يبق عند معاينة البأس إلا الاعتراف بالظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص726، تحت «بلاغة القصر في الاستثناء بعد النفي»","url":""}]},{"id":"s7-28","number":28,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"لماذا أكدوا اعترافهم بـ﴿إنّا﴾؟","answer":"أكدوا بـ﴿إنّا﴾ لأن المقام إقرار حاسم بعد طول إنكار، فثبتوا الظلم على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729، تحت «بلاغة المؤكدات في قوله تعالى: ﴿إنا كنا ظالمين﴾»","url":""}]},{"id":"s7-29","number":29,"surah":7,"verses":[5],"references":[{"surah":7,"verses":[5]}],"verseLabel":"الأعراف: 5","question":"ما الغرض من قولهم عند نزول البأس: ﴿إنا كنا ظالمين﴾؟","answer":"هو اعتراف بالذنب ممتزج بالندم والتحسر؛ فقد انهارت حجتهم وأقروا بالظلم حين لم يعد الاعتراف ينجيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص729، تحت عنوان «غرض الخبر ﴿إنا كنا ظالمين﴾ في الآية الكريمة»","url":""}]},{"id":"s7-30","number":30,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"لماذا عُطف سؤال المرسلين على سؤال الأمم في قوله: ﴿ولنسألن المرسلين﴾؟","answer":"ليكتمل مشهد الحساب من الطرفين: تُسأل الأمم عن استجابتها، ويُسأل الرسل عن تبليغهم، فيظهر العدل وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص737، تحت عنوان «دلالة العطف في قوله تعالى: ﴿ولنسألن المرسلين﴾»","url":""}]},{"id":"s7-31","number":31,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"ما سرّ تقديم سؤال الأمم على سؤال المرسلين؟","answer":"قُدمت الأمم لأن السياق في تهديد المكذبين، ولأن سؤالهم عن الاستجابة هو المقصود الأول في المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص736، تحت «فائدة تقديم ذكر ﴿أرسل إليهم﴾ على ﴿المرسلين﴾»","url":""}]},{"id":"s7-32","number":32,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"لماذا عُبر عن الأمم بقوله تعالى: ﴿الذين أرسل إليهم﴾؟","answer":"ليجعل إرسال الرسل أساس مساءلتهم؛ فقد بلغتهم الحجة، فصار موقفهم من الرسالة هو موضع السؤال والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص735–736، تحت عنوان «غرض التعبير بالاسم الموصول في ﴿الذين أرسل إليهم﴾»","url":""}]},{"id":"s7-33","number":33,"surah":7,"verses":[6],"references":[{"surah":7,"verses":[6]}],"verseLabel":"الأعراف: 6","question":"ما أثر المؤكدات في قوله تعالى: ﴿فلنسألن الذين أرسل إليهم﴾؟","answer":"تقطع الشك في وقوع السؤال يوم القيامة، وتصور الحساب وعدًا ووعيدًا محققًا لا احتمالًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص735، تحت عنوان «دلالة المؤكدات في قوله تعالى: ﴿فلنسألن الذين أرسل إليهم﴾»","url":""}]},{"id":"s7-34","number":34,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لماذا يسأل الله الذين أرسل إليهم مع علمه بالجواب؟","answer":"ليس السؤال لاكتساب علم، بل لتقريرهم وإقامة الحجة عليهم وإظهار عدله حين يشهدون على أنفسهم بما فعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص737، تحت عنوان «نكتة السؤال لـ﴿الذين أرسل إليهم﴾ مع علم الله بالجواب»","url":""}]},{"id":"s7-35","number":35,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لم قدم ﴿عليهم﴾ على ﴿بعلم﴾ في قوله: ﴿فلنقصن عليهم بعلم﴾؟","answer":"لزيادة الاهتمام بالرسل وأممهم الذين يقع عليهم السؤال والقص، فهم المقصودون بهذه المواجهة. فالتقديم يبرز المخاطبين بنتيجة أعمالهم قبل بيان أن القص قائم على العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص739، تحت «سر تقديم شبه الجملة ﴿عليهم﴾ في قوله: ﴿عليهم بعلم﴾»","url":""}]},{"id":"s7-36","number":36,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"ما دلالة تنكير ﴿علم﴾ في قوله تعالى: ﴿فلنقصن عليهم بعلم﴾؟","answer":"يفيد علمًا عظيمًا كاملًا محيطًا بتفاصيل أحوالهم، فيأتي القص والحساب على الحقيقة من غير نقص أو ظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص740، تحت عنوان «نكتة تنكير لفظ ﴿بعلم﴾ وتنوينه»","url":""}]},{"id":"s7-37","number":37,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"ما دلالة دخول ﴿كان﴾ في قوله تعالى: ﴿وما كنا غائبين﴾؟","answer":"تفيد دوام انتفاء الغيبة وعدم انقطاعه، لا نفيها في زمن مضى فقط؛ فعلم الله محيط في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص740، تحت عنوان «نكتة دخول (كان) في قوله تعالى: ﴿وما كنا غائبين﴾»","url":""}]},{"id":"s7-1560","number":1560,"surah":7,"verses":[7],"references":[{"surah":7,"verses":[7]}],"verseLabel":"الأعراف: 7","question":"لماذا عُبّر بنون العظمة في أفعال قوله تعالى: ﴿فلنقصن عليهم بعلم وما كنا غائبين﴾؟","answer":"لإبراز كمال علم الله وقدرته على إحصاء الأعمال وعرضها بالحق، فيجيء الحساب من الإله العظيم الذي لا يخفى عليه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص741، تحت عنوان «بلاغة التعبير بنون العظمة في أفعال الآية»","url":""}]},{"id":"s7-38","number":38,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿والوزن يومئذ الحق﴾، وما الذي يوزن؟","answer":"الوزن يوم القيامة عدل لا جور فيه، والميزان محمول هنا على الحقيقة. ومن شواهده وزن صحائف العمل، كما في حديث البطاقة والسجلات؛ فتظهر حقيقة الأعمال ومقاديرها في الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص745–746، تحت «لفظ الوزن بين الحقيقة والمجاز»","url":""}]},{"id":"s7-39","number":39,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا عُرّف ﴿الوزن﴾ في قوله تعالى: ﴿والوزن يومئذ الحق﴾؟","answer":"للدلالة على الوزن المعهود في يوم القيامة، وهو وزن الأعمال الذي ينتظره السياق، لا أي وزن آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص745، تحت عنوان «دلالة (الـ) في لفظ الوزن»","url":""}]},{"id":"s7-1561","number":1561,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا عُرّف ﴿الحق﴾ في قوله تعالى: ﴿والوزن يومئذ الحق﴾؟","answer":"ليدل على أن ذلك الوزن هو الحق الكامل المطابق للعدل، لا يدخله محاباة ولا نقص ولا باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص747، تحت عنوان «دلالة (الـ) في لفظ ﴿الحق﴾ من قوله: ﴿والوزن يومئذ الحق﴾»","url":""}]},{"id":"s7-40","number":40,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿ثقلت موازينه﴾ بالجمع؟","answer":"جمع الموازين باعتبار تعدد الموزونات أو الصحائف أو موازين الخلق، مع اتحاد حقيقة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص748–749، تحت «إيراد لفظ الموازين بالجمع»","url":""}]},{"id":"s7-41","number":41,"surah":7,"verses":[8],"references":[{"surah":7,"verses":[8]}],"verseLabel":"الأعراف: 8","question":"لماذا أظهر ضمير الفصل: ﴿فأولئك هم المفلحون﴾؟","answer":"ضمير الفصل يقوي الحكم ويفيد القصر: أصحاب الموازين الثقيلة هم المحققون للفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص750–751، تحت «بلاغة أساليب القصر في قوله: ﴿فأولئك هم المفلحون﴾»","url":""}]},{"id":"s7-42","number":42,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"هل ثقل الموازين وخفتها في الآية حقيقة أم مجاز؟ وما أثر الصورة؟","answer":"يحتمل الحقيقة في ميزان الأعمال، ويحتمل المجاز عن رجحان الحسنات أو فقدها؛ وفي الحالتين تجعل الصورة قيمة العمل ونتيجته محسوسة أمام القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص748، تحت عنوان «بلاغة ثقل الموازين وخفتها بين الحقيقة والمجاز»","url":""}]},{"id":"s7-43","number":43,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى عن أصحاب الموازين الخفيفة: ﴿خسروا أنفسهم﴾؟","answer":"جعل أنفسهم رأس مالهم، فلما أوردوها موارد العذاب كانوا كمن أضاع رأس ماله وخسر كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص752، تحت «بلاغة المجاز في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s7-44","number":44,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا بآياتنا يظلمون﴾ بتقديم ﴿بآياتنا﴾؟","answer":"قُدم ﴿بآياتنا﴾ للاهتمام بالآيات؛ إذ تكون بحسب موقف الناس منها سببًا في النجاة أو الهلاك، وفي التقديم كذلك مراعاة للفاصلة القرآنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص753، تحت «بلاغة تقديم شبه الجملة ﴿بآياتنا﴾»","url":""}]},{"id":"s7-45","number":45,"surah":7,"verses":[9],"references":[{"surah":7,"verses":[9]}],"verseLabel":"الأعراف: 9","question":"لماذا عُدّ تكذيب الآيات ظلمًا في قوله تعالى: ﴿بآياتنا يظلمون﴾؟","answer":"لأنهم جحدوا الآيات بعد قيام الحجة، فجمع فعلهم التكذيب ووضع الحق في غير موضعه؛ ولذلك ضُمّن الظلم معنى الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص754، تحت عنوان «التضمين في فعل ﴿يظلمون﴾ وتعديته بالباء»","url":""}]},{"id":"s7-46","number":46,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"ما دلالة قوله تعالى: ﴿ولقد مكناكم في الأرض﴾، ولماذا هو أوسع من الإسكان؟","answer":"التمكين يجعل الأرض قرارًا مع القدرة على التصرف والانتفاع والتعمير، لا مجرد وجود الإنسان فيها؛ فهو نعمة ومسؤولية معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص759، تحت عنوان «بلاغة المجاز أو الكناية في ﴿مكناكم﴾»","url":""}]},{"id":"s7-47","number":47,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"لم قدم ﴿لكم﴾ على ﴿فيها﴾ في قوله: ﴿وجعلنا لكم فيها معايش﴾؟","answer":"للعناية بالمخاطبين الذين قصد إكرامهم بالمعايش، والمسارعة إلى بيان أن المنفعة لهم. ثم ذكر الأرض موضعًا لهذه النعمة، فقدم من أنعم عليهم على محل الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص761–762، تحت «معنى اللام وعلة تقديم ﴿لكم﴾ على ﴿فيها﴾»","url":""}]},{"id":"s7-48","number":48,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"ما نكتة التعبير بالجمع ﴿معايش﴾؟","answer":"للدلالة على تنوع أسباب العيش من طعام وشراب وزراعة وتجارة وصناعة وسائر ما تقوم به الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص762، تحت عنوان «نكتة التعبير بـ﴿معايش﴾»","url":""}]},{"id":"s7-49","number":49,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"لماذا خُتمت بـ﴿قليلًا ما تشكرون﴾، لا: تذكرون كما في الآية 3؟","answer":"لأن المقام تعداد نعم التمكين والمعايش فناسبه الشكر؛ أما الآية 3 فمقام أمر ونهي يناسب التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص764، تحت «نكتة التعبير بالشكر في هذا الموضع والتذكر في الموضع السابق»","url":""}]},{"id":"s7-50","number":50,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا تعلّق فعلا الخلق والتصوير بضمير المخاطبين مع أن الخلق الأول كان لآدم؟","answer":"لأن خلق أصلهم وتصويره نعمة جارية على ذريته، ولأنهم كانوا مقدرين فيه؛ فنُسب إلى الجميع ما بدأ بأصلهم وشمل أثره وجودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص770–771، تحت عنوان «نكتة تعلق فعلي الخلق والتصوير بضمير المخاطبين»","url":""}]},{"id":"s7-51","number":51,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا عُطف التصوير على الخلق في قوله تعالى: ﴿خلقناكم ثم صورناكم﴾؟","answer":"لأن الخلق إيجاد الأصل والبنية، أما التصوير فمنحها الهيئة المميزة؛ فذكر التصوير بعد الخلق يلفت إلى تمام النعمة ودقة الإبداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص771، تحت عنوان «فائدة عطف التصوير على الخلق»","url":""}]},{"id":"s7-52","number":52,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم قلنا للملائكة اسجدوا لآدم﴾؟","answer":"تفيد التراخي في الرتبة والانتقال من نعمة الخلق والتصوير إلى مشهد التكريم بالسجود، لا ترتيب خلق كل فرد زمنيًا قبل الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص772، تحت عنوان «دلالة (ثم) في قوله: ﴿ثم قلنا للملائكة﴾»","url":""}]},{"id":"s7-53","number":53,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"ما مناسبة قصة خلق آدم وسجود الملائكة لما قبلها من تذكير بالتمكين والمعايش؟","answer":"بعد تذكير البشر بنعم الأرض أعادهم إلى أصل خلقهم وتكريم أبيهم، ليصل النعمة الأولى بمسؤوليتهم ويحذرهم من عداوة إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص767، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-55","number":55,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"لماذا قيل عن إبليس: ﴿لم يكن من الساجدين﴾ بدل: لم يسجد؟","answer":"لينفي دخوله في زمرة المطيعين، لا مجرد صدور سجدة منه؛ فالتعبير يصور انفصاله عن الجماعة التي امتثلت أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص773، تحت عنوان «الموقع النحوي والبياني لقوله: ﴿لم يكن من الساجدين﴾»","url":""}]},{"id":"s7-56","number":56,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿ما منعك ألا تسجد﴾، وظاهر الكلام أن المتوقع: أن تسجد؟","answer":"من أوجه التفسير أن «لا» زائدة للتوكيد، والمعنى: ما منعك أن تسجد؛ فالزيادة تحقق معنى الفعل الذي وبخ على تركه، ولا تنفي طلب السجود. ومن الأوجه تضمين المنع معنى الحمل، أي: ما حملك على ألا تسجد؟ والمقصود إنكار امتناعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص782–784، تحت «سر تأكيد المعنى وتقريره بزيادة (لا) في ﴿ما منعك ألا تسجد﴾»","url":""}]},{"id":"s7-57","number":57,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا ذُكّر إبليس بلفظ ﴿أمرتك﴾ في سؤال امتناعه عن السجود؟","answer":"لأن موجب السجود هو امتثال أمر الله، لا أن يزن إبليس آدم بقياسه الفاسد؛ فالمخالفة عصيان للأمر قبل أن تكون موقفًا من آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص786، تحت عنوان «نكتة التعبير بلفظ ﴿أمرتك﴾»","url":""}]},{"id":"s7-58","number":58,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا أجاب إبليس: ﴿أنا خير منه﴾ بدل أن يصرح بما منعه من السجود؟","answer":"ذكر العلة التي توهمها لا جواب السؤال المباشر؛ فكشف أن الكبر وادعاء الخيرية والقياس الفاسد هي التي منعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص789، تحت عنوان «مجيء الجواب على خلاف مقتضى الظاهر»","url":""}]},{"id":"s7-59","number":59,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"ما وجه فساد قياس إبليس النار بالطين في قوله: ﴿خلقتني من نار وخلقته من طين﴾؟","answer":"جعل إبليس الفضل تابعًا لمادة الخلق، وادعى أن النار أفضل من الطين. والمصدر يبين فساد هذه الدعوى، وأن تفضيل آدم كان بما خصه الله به من الخلق والتكريم والاستعداد، لا بمجرد أصله المادي؛ فذكر الأصلين لا يثبت الخيرية التي ادعاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص790–791، تحت «الطباق بين النار والطين، وبيان أن قياس إبليس حجة عليه»","url":""}]},{"id":"s7-60","number":60,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"كيف تبين جملتا ﴿خلقتني من نار وخلقته من طين﴾ مراد إبليس بقوله: ﴿أنا خير منه﴾؟","answer":"تفصلان دعواه المجملة، وتكشفان أن مراده بالخيرية فضل مادة خلقه في زعمه. فهما بيان لحجته، أو جواب عن سؤال يثيره قوله: ما وجه كونك خيرًا منه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص790، تحت «جملتا الخلق بين عطف البيان والاستئناف البياني»","url":""}]},{"id":"s7-61","number":61,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"كيف تخدم الجملة الاسمية ﴿أنا خير منه﴾ دعوى إبليس؟","answer":"صاغ دعواه في جملة اسمية ليعرض الخيرية كأنها وصف ثابت له، ويبني عليها امتناعه عن السجود. ثم فسر هذا الفضل المزعوم باختلاف مادتي الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص789–790، تحت «مناسبة التعبير بالجملة الاسمية في قوله: ﴿أنا خير منه﴾»","url":""}]},{"id":"s7-62","number":62,"surah":7,"verses":[12],"references":[{"surah":7,"verses":[12]}],"verseLabel":"الأعراف: 12","question":"لماذا حُذف نداء إبليس واسمه في الأعراف، وذُكرا في مواضع أخرى؟","answer":"لقرب ذكر إبليس من الخطاب في الأعراف فاستغني عن النداء والاسم، بينما طال الفصل في بعض المواضع الأخرى فأعيد اسمه لإيضاح المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص775–776، تحت عنوان «بلاغة المتشابه اللفظي مع آيات السجود الأخرى»","url":""}]},{"id":"s7-63","number":63,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا كان جزاء استكبار إبليس هو الهبوط؟","answer":"لأن الهبوط يقابل طلبه العلو بغير حق؛ فمن تكبر عن أمر الله أُنزل من منزلته وأُبعد عن موضع الكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص794، تحت عنوان «نكتة التعبير بلفظ الهبوط»","url":""}]},{"id":"s7-64","number":64,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"إلى ماذا يعود الضمير في ﴿منها﴾: إلى الجنة أم السماء أم المنزلة؟","answer":"يحتمل عوده إلى الجنة أو السماء أو المنزلة؛ ويجمعها معنى الإخراج من مقام الكرامة والعلو الذي كان فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص795، تحت «مناسبة عود الضمير على غير مذكور في قوله: ﴿منها﴾»","url":""}]},{"id":"s7-65","number":65,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"ما دلالة النفي في قوله تعالى: ﴿فما يكون لك أن تتكبر فيها﴾؟","answer":"ينفي استحقاق إبليس للتكبر وإمكان قبوله منه في ذلك المقام، فهو أبلغ من نهي مجرد يقول: لا تتكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص796، تحت عنوان «دلالة النفي في قوله: ﴿فما يكون لك﴾»","url":""}]},{"id":"s7-66","number":66,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا كرر الأمر بالخروج بعد الهبوط: ﴿فاخرج﴾؟","answer":"يحتمل أن يكون ﴿فاخرج﴾ تأكيدًا للأمر بالهبوط، لأن الهبوط من الجنة خروج منها. ويحتمل أن يؤسس معنى آخر، فيكون الهبوط زوالًا عن موضع الكرامة، والخروج طردًا مقرونًا بالذل أو إبعادًا عن المكان؛ فيشتد به بيان العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص800–801، تحت «دلالة قوله تعالى: ﴿فاخرج﴾ بين التأكيد والتأسيس»","url":""}]},{"id":"s7-67","number":67,"surah":7,"verses":[13],"references":[{"surah":7,"verses":[13]}],"verseLabel":"الأعراف: 13","question":"لماذا ناسب ذكر الصغار جزاء إبليس بعد تكبره؟","answer":"لأن الجزاء من جنس الذنب؛ فمن طلب العلو بغير حق عوقب بالذل والهوان، فانتقل من التكبر إلى أن يكون من الصاغرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص802، تحت عنوان «مناسبة ذكر الصغار في الآية الكريمة»","url":""}]},{"id":"s7-68","number":68,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ماذا يكشف طلب إبليس الإنظار بدل المغفرة عن موقفه بعد المعصية؟","answer":"يكشف إصراره على التمرد؛ فلم يتجه إلى التوبة وطلب المغفرة، بل طلب إطالة بقائه ليواصل إغواء بني آدم. وهكذا حوّل مهلة العمر إلى امتداد للعداوة بدل أن يجعلها سبيلًا للرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص10، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s7-69","number":69,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"لماذا اختير ﴿أنظرني﴾، لا: أمهلني؟","answer":"الإنظار تأخير إلى أجل معلوم، أما الإمهال فأعم وقد لا يذكر معه حد؛ فوافق لفظه طلب تحديد الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص17، تحت «الفروق المعجمية: الإنظار والإمهال»","url":""}]},{"id":"s7-70","number":70,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم يبعثون﴾، دون أن يقال: إلى يوم القيامة؟","answer":"حدد يوم البعث لأنه يوم إحياء الخلق الذي يعقبه الخلود؛ فأراد امتداد بقائه إلى ذلك اليوم ليفلت من الموت. لذلك كانت تسمية البعث كاشفة عن غرضه من تحديد الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص12، تحت «مناسبة تحديد الإنظار في قوله تعالى: ﴿إلى يوم يبعثون﴾»","url":""}]},{"id":"s7-71","number":71,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"لماذا جاء ﴿يبعثون﴾ بالبناء للمجهول؟","answer":"بُني للمجهول لتوجيه النظر إلى حدث بعث الخلق وعظمته، لا إلى إسناد الفعل إلى فاعله المعلوم، وفيه إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص12، تحت «نكتة مجيء لفظ البعث على صيغة المبني للمفعول»","url":""}]},{"id":"s7-72","number":72,"surah":7,"verses":[14],"references":[{"surah":7,"verses":[14]}],"verseLabel":"الأعراف: 14","question":"ما سرّ مجيء طلب إبليس في الأعراف: ﴿أنظرني﴾، وفي الحجر وص: ﴿رب فأنظرني﴾؟","answer":"اقتصر مقام الأعراف على مجرد الإخبار بالاستنظار، فناسبه الإيجاز في ﴿أنظرني﴾. وفي الحجر وص جاء الطلب بعد ذكر الطرد والحرمان، فناسب مقام الضراعة أن ينادي بلفظ ﴿رب﴾ قبل طلب الإنظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص15–16، تحت عنوان «مقام الاستنظار يقتضي إظهار الضراعة بلفظ الربوبية»","url":""}]},{"id":"s7-73","number":73,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"لماذا جاء جواب إبليس جملة اسمية: ﴿إنك من المنظرين﴾؟","answer":"تفيد الجملة الاسمية ثبوت الحكم واستقراره؛ فلا تعرضه كفعل إنظار عابر، بل تقرر دخوله في حكم مقدر إلى الأجل المعلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13–14، تحت عنوان «بلاغة التعبير بالاسمية في قوله: ﴿إنك من المنظرين﴾»","url":""}]},{"id":"s7-1562","number":1562,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"لماذا قيل لإبليس: ﴿من المنظرين﴾ بصيغة الجمع؟","answer":"ليدل على أنه داخل في طائفة سبق تقدير تأخير آجالها، لا أنه مُنح إنظارًا خاصًا استجابة كاملة لطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13–14، تحت عنوان «نكتة جمع ﴿المنظرين﴾»","url":""}]},{"id":"s7-74","number":74,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"ما سرّ حذف غاية الإنظار من الجواب مع أن إبليس طلب تحديدها؟","answer":"حذف الغاية ليبين أنه لم يُجب إلى اليوم الذي طلبه؛ فكونه من المنظرين يتحقق بتأخيره إلى الوقت المعلوم، وهو قبل بعث الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص13، تحت «مناسبة الجواب في قوله تعالى: ﴿إنك من المنظرين﴾»","url":""}]},{"id":"s7-75","number":75,"surah":7,"verses":[15],"references":[{"surah":7,"verses":[15]}],"verseLabel":"الأعراف: 15","question":"ما سرّ مجيء الجواب في الأعراف: ﴿إنك من المنظرين﴾، وفي الحجر وص بالفاء: ﴿فإنك﴾؟","answer":"جاء الكلام في الأعراف استئنافًا غير مسبب عما قبله، فناسبه حذف الفاء. وفي الحجر وص جاء الاستنظار عقب الحكم بالطرد واللعنة، على معنى: إذا حكمت علي بذلك فأنظرني؛ فناسب هذا التسببَ اقترانُ الجواب بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص16–17، تحت «الفاء قرينة التسبب عما قبلها في جملة ﴿فإنك من المنظرين﴾»","url":""}]},{"id":"s7-76","number":76,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما دلالة نسبة إبليس الغواية إلى الله في قوله: ﴿فبما أغويتني﴾؟","answer":"نسب الغواية إلى الله على سبيل الاعتراض والتمرد، فجعل ما انتهى إليه من الضلال أساسًا لوعيده بإغواء البشر. ويذكر المصدر من توجيه كلامه أنه عد الأمر بالسجود سببًا في ظهور إبائه وتكبره، فنسب الإغواء إلى ما اتخذه سببًا لغوايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص22، تحت «دلالة صيغة ﴿أغويتني﴾ في جملة ﴿فبما أغويتني لأقعدن لهم﴾»","url":""}]},{"id":"s7-77","number":77,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما دلالة الباء و﴿ما﴾ في ﴿فبما أغويتني﴾؟","answer":"الباء للسببية أو للقسم، و﴿ما﴾ مصدرية: بسبب إغوائك إياي، أو أقسم بإغوائك؛ وعلى الوجهين بنى وعيده على غوايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص21–22، تحت «دلالة الباء في قوله تعالى: ﴿فبما أغويتني﴾؛ دلالة (ما) المصدرية في جملة ﴿فبما أغويتني﴾»","url":""}]},{"id":"s7-78","number":78,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا أكد وعيده باللام والنون: ﴿لأقعدن لهم﴾؟","answer":"اللام واقعة في جواب القسم، ونون التوكيد الثقيلة تؤكد الفعل؛ فاجتماعهما يحقق وعيده بالقعود على الصراط، ويظهر شدة عزمه على إغواء الناس واستمراره فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص23، تحت «دلالة تتابع التأكيد في قوله: ﴿لأقعدن لهم﴾»","url":""}]},{"id":"s7-79","number":79,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا صوّر الإضلال بالقعود على الطريق؟","answer":"استعار القعود للملازمة والترصد؛ كقاطع الطريق يقعد للمارين ليصدهم عن وجهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص22–23، تحت «لفظ القعود بين الكناية والاستعارة التمثيلية»","url":""}]},{"id":"s7-80","number":80,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿صراطك المستقيم﴾، فأضاف الصراط إلى الله؟","answer":"إضافة الصراط إلى الله تخصصه بأنه الطريق الذي نصبه لعباده ليوصلهم إلى مرضاته. ففي الإضافة بيان أن بلوغ رضوانه يكون باتباع هذا الصراط، وهو الذي أراد إبليس صد الناس عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص25، تحت «دلالة الإضافة في قوله تعالى: ﴿صراطك﴾ من الآية الكريمة»","url":""}]},{"id":"s7-81","number":81,"surah":7,"verses":[16],"references":[{"surah":7,"verses":[16]}],"verseLabel":"الأعراف: 16","question":"لماذا عُدّي القعود للصراط بنفسه من غير ﴿على﴾ أو ﴿في﴾؟","answer":"من توجيهاته أن ﴿أقعدن﴾ ضمن معنى «ألزمن»، فتعدى إلى الصراط مباشرة، أو أن الجار حذف والتقدير: على صراطك. ويحتمل نصبه على الظرفية؛ وعلى هذه الأوجه يرسم التعبير ملازمة الطريق والترصد لسالكيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص24–25، تحت «نكتة تعدي ﴿لأقعدن﴾ إلى المفعول ﴿صراطك﴾»","url":""}]},{"id":"s7-82","number":82,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم لآتينهم﴾ بـ﴿ثم﴾ بعد ﴿لأقعدن﴾؟","answer":"﴿ثم﴾ للترتيب الرتبي: بعد أصل الملازمة والقعود ينتقل إلى مباشرة إتيانهم من وجوه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص25–26، تحت «دلالة حرف العطف (ثم) في قوله: ﴿ثم لآتينهم﴾»","url":""}]},{"id":"s7-83","number":83,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا ذكر الجهات الأربع: الأمام والخلف واليمين والشمال، ولم يذكر الفوق والتحت؟","answer":"تمثل الجهات الأربع الطرق التي يعتاد العدو أن يهجم منها، فصورت محاولات الإغواء المتنوعة بصورة هجوم محيط بالإنسان. أما الفوق والتحت فليستا من جهات هجوم العدو المعتادة في هذا التمثيل؛ فالمراد استيعاب مسالك الوسوسة غالبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29، تحت «بلاغة الاستعارة التمثيلية في هذه الآية الكريمة»","url":""}]},{"id":"s7-1563","number":1563,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"كيف يخدم الطباق بين الأمام والخلف واليمين والشمال تصوير إحاطة الوسوسة؟","answer":"يجمع الطباق الجهات المتقابلة في صورة واحدة، فيوحي بتنوع مداخل إبليس ومحاولته الإحاطة بالإنسان من مسالك متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29، تحت «بديع الطباق في الآية الكريمة»","url":""}]},{"id":"s7-84","number":84,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿من بين أيديهم ومن خلفهم﴾ بـ﴿من﴾، ثم ﴿عن أيمانهم وعن شمائلهم﴾ بـ﴿عن﴾؟","answer":"﴿من﴾ تلائم الابتداء والجهتين الممتدتين أمامًا وخلفًا، و﴿عن﴾ تلائم المجاوزة والميل من جانبي اليمين والشمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص26–27، تحت «نكتة المخالفة في حروف الجر ﴿من بين أيديهم ومن خلفهم﴾»","url":""}]},{"id":"s7-85","number":85,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما دلالة جمع ﴿أيمانهم﴾ و﴿شمائلهم﴾ في وصف إتيان إبليس؟","answer":"جاء الجمع ملائمًا لجماعة من يأتيهم إبليس؛ فيأتي كل واحد من جهة يمينه وشماله، ويوحي بتكرر التعرض وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص27–28، تحت «مناسبة جمع اليمين والشمال في ﴿وعن أيمانهم وعن شمائلهم﴾»","url":""}]},{"id":"s7-1564","number":1564,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا تعددت سبل إغواء إبليس بينما وُصف صراط الله بالاستقامة والوحدة؟","answer":"لأن الباطل تتشعب مسالكه بحسب الشهوات والشبهات، أما طريق الحق فوجهته واحدة تصل العبد بمرضاة الله؛ فكثرة المداخل لا تجعلها طرقًا مساوية للصراط المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص27–28، تحت «سبل إبليس كثيرة متنوعة، وصراط الله مستقيم واحد»","url":""}]},{"id":"s7-86","number":86,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"لماذا ختم إبليس وعيده بقوله: ﴿ولا تجد أكثرهم شاكرين﴾، لا: مؤمنين؟","answer":"نفي الشكر كناية عن الكفر؛ إذ اتباع صراط الله هو الإيمان وشكر نعمته، ومقصود إبليس صرفهم عنه. فعدل في وعيده إلى نفي الشكر، وفيه أيضًا إظهار قبح جحود النعمة التي أنعم الله بها عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص29–30، تحت «بلاغة الكناية في جملة ﴿ولا تجد أكثرهم شاكرين﴾»","url":""}]},{"id":"s7-87","number":87,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لماذا أعيد الأمر بالخروج: ﴿اخرج منها﴾ بعد قوله في الآية 13: ﴿فاخرج﴾؟","answer":"أعيد بعد ظهور إصراره ووعيده لتجديد الطرد وتأكيد أنه لا مقام له فيها بعد هذه المجاوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31–32، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-88","number":88,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما الفرق الدلالي بين ﴿مذءومًا﴾ و﴿مدحورًا﴾ في جزاء إبليس؟","answer":"المذءوم هو المعيب البالغ في الذم والمقت، والمدحور هو المطرود المبعد على سبيل الإهانة؛ فجمع اللفظان الذم والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص31، تحت «شرح المفردات: ﴿مذءومًا﴾ و﴿مدحورًا﴾»","url":""}]},{"id":"s7-1565","number":1565,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لماذا قُيّد خروج إبليس بحالي ﴿مذءومًا مدحورًا﴾؟","answer":"ليبين أن خروجه لم يكن انتقالًا مجردًا، بل خروجًا مصحوبًا بالمقت والمهانة والطرد، فيكتمل تصوير الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص33، تحت «دلالة مجيء الخروج مقيدًا بالحال»","url":""}]},{"id":"s7-89","number":89,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"لم اختير وصف ﴿مذءومًا﴾ في الأمر بخروج إبليس؟","answer":"لأن الذأم أشد من الذم، فناسب الوصف شدة عزمه على الإغواء والتمرد؛ إذ بالغ في العداوة، فجيء بما يدل على بلوغه الغاية في المقت والعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص33، تحت «علة إيثار لفظ ﴿مذءومًا﴾ في هذا الموضع»","url":""}]},{"id":"s7-90","number":90,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما الذي يكشفه الوعيد: ﴿لأملأن جهنم منكم﴾ عن عاقبة مشروع إبليس؟","answer":"يكشف أن مشروع الإغواء لا يغير سلطان الله ولا يفلت أتباع إبليس من الجزاء؛ فالاجتماع على العصيان ينتهي إلى الاجتماع في جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص35، تحت «نكتة التعبير بقوله تعالى: ﴿لأملأن جهنم منكم﴾»","url":""}]},{"id":"s7-1566","number":1566,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما دلالة ختم الوعيد بكلمة ﴿أجمعين﴾؟","answer":"تؤكد شمول الوعيد لإبليس ومن اتبعه، فلا يستثني اجتماعهم في العصيان أحدًا ممن ثبت عليه الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص36، تحت «دلالة قوله تعالى: ﴿أجمعين﴾»","url":""}]},{"id":"s7-91","number":91,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"إلى من يعود ضمير الجمع في ﴿منكم﴾؟","answer":"يعود إلى إبليس وأتباعه من الجن والإنس؛ ودل جمع الخطاب على إدخال من اتبعه معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص35–36، تحت «بلاغة التغليب في قوله: ﴿منكم﴾»","url":""}]},{"id":"s7-92","number":92,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكن أنت وزوجك الجنة﴾، فأظهر ﴿أنت﴾ بعد ضمير الفعل؟","answer":"جاء ﴿أنت﴾ توكيدًا للضمير المستتر في ﴿اسكن﴾، وفيه تقرير الامتنان على آدم والتنويه بمقامه. وفي سياق طرد إبليس يعرض الضمير بإكرام آدم الذي أُمر إبليس بالسجود له، فتزداد المقابلة بين إسكان آدم وإخراج إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص41، تحت «بلاغة التعريض بالضمير المنفصل»","url":""}]},{"id":"s7-93","number":93,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لم خص آدم بالخطاب في ﴿اسكن أنت وزوجك الجنة﴾، وجعل زوجه معطوفة عليه؟","answer":"لأن آدم هو الأصيل في تلقي الوحي ومعاني الأمر، فجاء الخطاب موجهًا إليه، وعطفت زوجه عليه لتشاركه حكم السكن. فالصياغة تجمع بين تخصيصه بالخطاب وشمول النعمة لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص40، تحت «نكتة تخصيص الخطاب بآدم، وعطف زوجه عليه»","url":""}]},{"id":"s7-94","number":94,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿فكلا من حيث شئتما﴾، ولم يحدد لهما موضعًا؟","answer":"أطلق لهما الأكل من أي موضع شاءا توسعةً وإباحةً عامة، فلم يحتج إلى تحديد إلا في الشجرة المستثناة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص43، تحت «مناسبة العموم في قوله تعالى: ﴿من حيث شئتما﴾»","url":""}]},{"id":"s7-95","number":95,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا جاء النهي: ﴿ولا تقربا هذه الشجرة﴾، لا: لا تأكلا منها؟","answer":"النهي عن القرب أبلغ وأحوط من النهي عن الأكل؛ لأنه يسد الطرق المؤدية إليه ويبعدهما عن موضع الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص46–47، تحت «نكتة التعبير بلفظ: ﴿تقربا﴾ في ﴿ولا تقربا هذه الشجرة﴾»","url":""}]},{"id":"s7-96","number":96,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا أشار إلى الشجرة بـ﴿هذه﴾؟","answer":"اسم الإشارة يعين الشجرة تعيينًا مشاهدًا حتى لا يلتبس المحظور، ويشعر بقربها المكاني منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص43، تحت «دلالة اسم الإشارة في قوله تعالى: ﴿هذه الشجرة﴾»","url":""}]},{"id":"s7-97","number":97,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"ما سر التعبير بـ﴿فتكونا من الظالمين﴾، دون: فتكونا ظالمين؟","answer":"في إدخالهما في زمرة الظالمين مبالغة في التحذير من مخالفة أمر الله؛ فالنسبة إلى أهل الوصف تقوي معنى الاتصاف به وشدة التنفير منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص352، تحت عنوان «التعبير بـ﴿من الظالمين﴾ دون ﴿فتكونا ظالمين﴾ للمبالغة في التحذير»","url":""}]},{"id":"s7-99","number":99,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا عُطف الأكل بالفاء ﴿فكلا﴾ في الأعراف، وبالواو ﴿وكلا﴾ في البقرة؟","answer":"الفاء في الأعراف تفيد ترتب الأكل مباشرة على السكن والإذن، والواو في البقرة لمطلق الجمع مع توسع السياق في ذكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص45–46، تحت «تنوع التعبير بين الواو والفاء تفاوت في ذكر مطلق الأكل ونوعه»","url":""}]},{"id":"s7-100","number":100,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا حُذفت ﴿رغدًا﴾ من آية الأعراف وذُكرت في البقرة؟","answer":"جاءت ﴿رغدًا﴾ في البقرة لزيادة بيان سعة النعمة؛ فالسياق يعدد ما امتن الله به على آدم. أما الأعراف فالسياق يعرض عداوة إبليس والتحذير من مخالفته، فاكتفى بإباحة الأكل حيث شاءا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص45–46، تحت عنوان «تنوع التعبير بين الواو والفاء، تفاوت في ذكر مطلق الأكل ونوعه»","url":""}]},{"id":"s7-101","number":101,"surah":7,"verses":[19],"references":[{"surah":7,"verses":[19]}],"verseLabel":"الأعراف: 19","question":"لماذا تقدّم ﴿منها﴾ على ﴿حيث شئتما﴾ في البقرة، بينما جاء في الأعراف: ﴿من حيث شئتما﴾؟","answer":"في البقرة يعود الضمير في ﴿منها﴾ إلى الجنة باعتبار مطاعمها، فصرح بمصدر الأكل، ثم عمم مكانه بقوله: ﴿حيث شئتما﴾. وفي الأعراف دخلت ﴿من﴾ على ﴿حيث﴾ لتجعل ابتداء الأكل من أي موضع شاءا، مع إشعار بسعة المأكل والتوسعة عليهما.","sources":[{"label":"[موضع المقارنة في البقرة] موسوعة التفسير البلاغي، ج1، ص350، تحت «فن الاستخدام»","url":""},{"label":"موسوعة التفسير البلاغي، ج13، ص42–43، تحت «نكتة التعبير بـ﴿من﴾؛ مناسبة العموم في قوله تعالى: ﴿من حيث شئتما﴾»","url":""}]},{"id":"s7-102","number":102,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"كيف يصور قوله ﴿فوسوس لهما الشيطان﴾ طريقة خداعه لآدم وزوجه؟","answer":"يسمي إلقاءه إليهما وسوسة لأنها تسويل خفي بالغ في الإسرار، سواء كان بكلام أو بإلقاء في النفس. فخفي حديثه عن غيرهما، وأظهر لهما صورة الناصح ليخدعهما، مع أن غايته إغواؤهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص50–51، تحت «دلالة التعبير بقوله تعالى: ﴿فوسوس لهما الشيطان﴾»","url":""}]},{"id":"s7-103","number":103,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا عُلّلت الوسوسة بقوله: ﴿ليبدي لهما ما ووري عنهما من سوآتهما﴾؟","answer":"اللام للعاقبة والصيرورة على وجه؛ إذ لم يكن مقصوده المباشر كشف العورة، لكن وسوسته آلت إليه؛ ويجوز أن تكون للتعليل باعتبار قصده سلب النعمة وإيذاءهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص51–52، تحت «توجيه اللام بين العاقبة والتعليل في جملة ﴿ليبدي لهما﴾»","url":""}]},{"id":"s7-104","number":104,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"ما دلالة التعبير بالمواراة في ﴿ما ووري عنهما﴾؟","answer":"المواراة ستر الشيء عن النظر، والتعبير يبرز شدة ستر عورتيهما حتى كانتا محجوبتين عن نفسيهما. ويذكر المصدر وجه المبالغة في صيغة المفاعلة، ووجه الدلالة على أصل الستر؛ فالمعنى يصور تمام الستر قبل انكشافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص52–53، تحت «دلالة صيغة: ﴿ما ووري عنهما﴾ من الآية الكريمة»","url":""}]},{"id":"s7-105","number":105,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا جُمعت ﴿سوآتهما﴾؟","answer":"وضع الجمع موضع التثنية تخفيفًا، كما يرد في العربية عند إضافة أعضاء الاثنين إليهما. وفيه تعظيم شأن انكشاف العورة، حتى يصور كشف عورة كل واحد كأنه كشف لسوءات كثيرة؛ ويذكر المصدر أيضًا اعتبار العورة من الأمام والخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص53، تحت «سر التعبير بالجمع في قوله تعالى: ﴿من سوآتهما﴾»","url":""}]},{"id":"s7-106","number":106,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"ما دلالة قصر الشيطان علة النهي في قوله: ﴿ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين﴾؟","answer":"القصر كذب به إبليس ليصور النهي كأنه لا علة له إلا منع رتبة الملك أو الخلود، فيصرفهما عن حكمة الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص55، تحت «مناسبة الحصر في جملة الاستثناء في قوله ﴿إلا أن تكونا ملكين﴾»","url":""}]},{"id":"s7-107","number":107,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لماذا اختار فتنتين: الملك والخلود؟","answer":"أغراهما بما يظنان أنه يرفعهما فوق حالهما: رتبة الملائكة، أو البقاء والخلود في الجنة. فحصر لهما المطمع في أمرين يرغبان فيهما ليقوي إقبالهما على الأكل ويخفي حقيقة الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص56، تحت «نكتة العطف بـ﴿أو﴾»","url":""}]},{"id":"s7-108","number":108,"surah":7,"verses":[20],"references":[{"surah":7,"verses":[20]}],"verseLabel":"الأعراف: 20","question":"لم قال الشيطان ﴿ربكما﴾ في معرض إغوائه لآدم وزوجه؟","answer":"استعمل لفظ الربوبية ليوهمهما أن نصحه منسجم مع إنعام ربهما عليهما، ويهون عليهما مخالفة النهي. وأبعد نفسه عن الخطاب فقال ﴿ربكما﴾، مظهرًا لهما صورة الناصح مع ما في قوله من الكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص54، تحت «نكتة التعبير بلفظ ﴿ربكما﴾»","url":""}]},{"id":"s7-109","number":109,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وقاسمهما﴾ بصيغة المفاعلة مع أن المقسم هو إبليس؟","answer":"المفاعلة هنا للمبالغة في القسم وتكريره، أو لأنهما قابلا قسمه بالقبول والتصديق فكأن المشاركة حصلت من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص58–59، تحت «دلالة صيغة المفاعلة في قوله تعالى: ﴿وقاسمهما﴾»","url":""}]},{"id":"s7-110","number":110,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"لماذا أكد كذبه بـ﴿إني لكما لمن الناصحين﴾؟","answer":"واجه إبليس شكهما بالقسم و﴿إن﴾ واللام والجملة الاسمية، فتتابعت المؤكدات ليقرر نصحه المزعوم ويقرب باطله إلى نفسيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص59–60، تحت «مناسبة تتابع المؤكدات في ﴿وقاسمهما إني لكما لمن الناصحين﴾»","url":""}]},{"id":"s7-111","number":111,"surah":7,"verses":[21],"references":[{"surah":7,"verses":[21]}],"verseLabel":"الأعراف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿من الناصحين﴾، لا: ناصح؟","answer":"ادعى أنه واحد من جماعة عُرفت بالنصح، لا ناصح منفرد؛ ليقوي الثقة بقوله ويبالغ في التلبيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص60، تحت «توجيه التعبير بقوله ﴿لمن الناصحين﴾، ودلالته على المراوغة»","url":""}]},{"id":"s7-112","number":112,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا عبّر عن إهباطهما إلى المعصية بقوله: ﴿فدلاهما بغرور﴾؟","answer":"استعيرت التدلية لإنزالهما من مقام الطاعة والنعمة بالتدرج في الخداع؛ كمن يدلي غيره في بئر بحبل يغره ثم يقطعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص64، تحت «بلاغة الاستعارة التمثيلية في الفعل ﴿فدلاهما﴾»","url":""}]},{"id":"s7-113","number":113,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا عُدّي التدلية بالباء في ﴿بغرور﴾؟","answer":"الباء للسببية أو الملابسة: أنزلهما بسبب غروره، أو مصاحبين لما كرره من الخداع والقسم الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص64–65، تحت «الباء بين السببية والملابسة في لفظ ﴿بغرور﴾»","url":""}]},{"id":"s7-114","number":114,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا قيل: ﴿ذاقا الشجرة﴾، لا: أكلا منها؟","answer":"الذوق أول الأكل وأقله؛ فالتعبير يبين أن أثر المخالفة ظهر بمجرد تناول يسير، ويعظم شأن النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص66، تحت «علة التعبير بلفظ ﴿ذاقا﴾»","url":""}]},{"id":"s7-115","number":115,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿بدت لهما سوآتهما﴾ بعد أن كانت مواراة؟","answer":"قابل الظهور بالمواراة السابقة: سقط عنهما اللباس الذي كان يسترهما فظهرت عوراتهما لهما، فبادرا إلى الستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص63، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-116","number":116,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا اختير ﴿وطفقا﴾ في تصوير مبادرتهما إلى الستر؟","answer":"تفيد ﴿طفقا﴾ الشروع والمبادرة؛ فما إن ظهرت السوأتان حتى أخذا في الستر من غير إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص69، تحت «نكتة التعبير بالفعل ﴿وطفقا﴾»","url":""}]},{"id":"s7-1567","number":1567,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما أثر المضارع في قوله: ﴿يخصفان عليهما من ورق الجنة﴾؟","answer":"يستحضر المضارع هيئة الخصف المتجدد أمام السامع، فيصور حركتهما المتتابعة وهما يلصقان الورق طلبًا للستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص67، تحت «نكتة التعبير بالفعل المضارع في ﴿يخصفان﴾»","url":""}]},{"id":"s7-117","number":117,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا قيل: ﴿يخصفان عليهما﴾ مع أن المقصود ستر السوأتين؟","answer":"يرجع الضمير إلى جسميهما على وجه المبالغة، كأن شدة الحياء حملتهما على طلب ستر الجسد كله، لا موضع العورة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص69، تحت «مجيء الكلام على خلاف مقتضى الظاهر في ﴿يخصفان عليهما﴾»","url":""}]},{"id":"s7-118","number":118,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة اختيار النداء في قوله: ﴿وناداهما ربهما﴾؟","answer":"يشعر النداء ببعد حالهما عن مقام القرب بعد المخالفة، ويجعل العتاب مواجهة توقظهما إلى ما وقعا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص68، تحت «إيثار التعبير بالنداء»","url":""}]},{"id":"s7-1568","number":1568,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا جاء العتاب بلفظ ﴿ربهما﴾؟","answer":"ليذكرهما بأن الله مالك أمرهما ومدبر أحوالهما ومربيهما؛ فيبقى معنى التربية والإنعام حاضرًا حتى في مقام العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص70، تحت «نكتة التعبير بقوله ﴿ربهما﴾ دون سواه من الأسماء والصفات»","url":""}]},{"id":"s7-119","number":119,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة الاستفهام في قوله: ﴿ألم أنهكما عن تلكما الشجرة﴾؟","answer":"هو استفهام تقريري يثبت النهي الذي خالفاه، ويوقظهما إلى وضوح الأمر الذي سبق أن تلقياه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص68، تحت «مجاز الاستفهام في قوله: ﴿ألم أنهكما﴾»","url":""}]},{"id":"s7-1569","number":1569,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"ما دلالة الاستفهام في تذكيرهما بعداوة الشيطان؟","answer":"يقرر التحذير الذي سبق لهما ويكشف أن الوقوع لم يكن لغياب التنبيه، بل مع معرفة عداوة من أغواهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص71، تحت «دلالة الاستفهام المجازي في ﴿وأقل لكما إن الشيطان لكما عدو﴾»","url":""}]},{"id":"s7-1570","number":1570,"surah":7,"verses":[22],"references":[{"surah":7,"verses":[22]}],"verseLabel":"الأعراف: 22","question":"لماذا جُمع في العتاب بين النهي عن الشجرة والتحذير من الشيطان؟","answer":"لأن الأول يقرر موضع المخالفة، والثاني يقرر سبب الوقوع فيها؛ فاجتمع بيان الحكم وبيان العدو الذي زين مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص72، تحت «دلالة عطف ﴿وأقل لكما﴾ على جملة الاستفهام»","url":""}]},{"id":"s7-120","number":120,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا افتتح آدم وزوجه اعترافهما بالنداء: ﴿ربنا﴾؟","answer":"افتتحا به إظهارًا للعبودية والافتقار، وتهيئةً للاعتراف وطلب المغفرة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص76، تحت «نكتة النداء بـ﴿ربنا﴾»","url":""}]},{"id":"s7-1571","number":1571,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما دلالة إضافة الرب إليهما في قولهما: ﴿ربنا﴾؟","answer":"تستحضر الإضافة رعاية الله وتربيته ورحمته، فيتوسلان بربوبيتهما مع إقرارهما بظلم النفس وحاجتهما إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص76، تحت «مناسبة الإضافة في قوله تعالى: ﴿ربنا﴾»","url":""}]},{"id":"s7-121","number":121,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا سمّى آدم وزوجه ذنبهما ظلمًا للنفس؟","answer":"لأن تبعة المعصية عائدة عليهما؛ فقد أوقعا نفسيهما في الحرمان والتعب بعد نعمة الجنة. وفي هذا التعبير اعتراف بأن ضرر الذنب يصيب صاحبه، لا أنه يضر الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص77، تحت «مناسبة تسمية الذنب ظلمًا للنفس»","url":""}]},{"id":"s7-1572","number":1572,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"لماذا قالا: ﴿ظلمنا أنفسنا﴾ بالجمع مع أنهما اثنان؟","answer":"جيء بالجمع بدل التثنية إشعارًا بأن قلبيهما أصابهما أثر المعصية، ولأن جمع النفس شائع عند الإضافة إلى مثنى، وفيه استحضار لما دخلهما من ندم واضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص77، تحت «سر التعبير بالجمع في لفظ ﴿أنفسنا﴾ مع أنهما مثنى»","url":""}]},{"id":"s7-122","number":122,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما سرّ تقديم المغفرة على الرحمة: ﴿وإن لم تغفر لنا وترحمنا﴾؟","answer":"قُدمت المغفرة لأنها إزالة أثر الذنب، ثم تأتي الرحمة بتحصيل الخير والفضل؛ فالتخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص79–80، تحت «مناسبة الترتيب بين المغفرة والرحمة في السياق»","url":""}]},{"id":"s7-123","number":123,"surah":7,"verses":[23],"references":[{"surah":7,"verses":[23]}],"verseLabel":"الأعراف: 23","question":"ما أثر توكيد قولهما: ﴿لنكونن من الخاسرين﴾؟","answer":"يقرر التوكيد يقينهما بأن الخسران لازم إن لم تتداركهما مغفرة الله ورحمته، ويكشف صدق خوفهما وشدة افتقارهما إلى النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص81، تحت «دلالة نتائج التأكيد في قوله تعالى: ﴿لنكونن﴾»","url":""}]},{"id":"s7-124","number":124,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"لماذا جاء أمر الهبوط بصيغة الجمع: ﴿اهبطوا﴾ بعد خطاب آدم وزوجه؟","answer":"يشمل الجمع آدم وحواء وإبليس، ويدخل فيه من يتبعهم بحسب توجيه السياق؛ فانتقل الخطاب من الزوجين إلى أطراف العداوة التي ستعيش في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص87، تحت «معنى واو الجمع في قوله تعالى: ﴿اهبطوا﴾»","url":""}]},{"id":"s7-125","number":125,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿بعضكم لبعض عدو﴾، فأفرد ﴿عدو﴾؟","answer":"أفرد لأنه مصدر أو اسم جنس يصدق على الواحد والجمع، أو لأن كل بعض عدو للبعض الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص90، تحت «سر التعبير بالمفرد ﴿عدو﴾ دون (أعداء)»","url":""}]},{"id":"s7-126","number":126,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ تقديم الاستقرار على المتاع: ﴿مستقر ومتاع إلى حين﴾؟","answer":"قدم المستقر لأنه أعم؛ فهو يشمل مكث الإنسان حيًا في الأرض ومكثه بعد الموت، أما المتاع فانتفاع بملذات الحياة ينتهي بانتهائها. فالتقديم يجري من العام إلى الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص92، تحت «سر تقديم (المستقر) على (المتاع)»","url":""}]},{"id":"s7-127","number":127,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما دلالة حرف الغاية في قوله: ﴿ومتاع إلى حين﴾؟","answer":"تجعل ﴿إلى﴾ الاستقرار والمتاع منتهيين إلى أجل، فتقطع توهم الدوام وتذكر بأن الانتفاع في الدنيا محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص92، تحت «نكتة التعبير بحرف الجر في: ﴿إلى حين﴾»","url":""}]},{"id":"s7-1573","number":1573,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"لماذا قُيّد المتاع بلفظ ﴿حين﴾ من غير تحديد الأجل؟","answer":"لأن ﴿حين﴾ يصدق على زمن يطول أو يقصر، فيشمل اختلاف آجال الأفراد وانتهاء الدنيا بقيام الساعة، مع بقاء الأجل مستورًا عن الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص93، تحت «مناسبة التعبير بلفظ ﴿حين﴾»","url":""}]},{"id":"s7-128","number":128,"surah":7,"verses":[24],"references":[{"surah":7,"verses":[24]}],"verseLabel":"الأعراف: 24","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿اهبطوا بعضكم لبعض عدو﴾ بصيغة الجمع، وفي طه: ﴿اهبطا منها جميعًا بعضكم لبعض عدو﴾ بصيغة التثنية؟","answer":"في الأعراف يتوجه الجمع إلى آدم وزوجه وذريتهما، ويدخل إبليس في خطاب الهبوط بحسب توجيه السياق. وفي طه حملت التثنية على فريقين متواجهين: آدم وذريته، وإبليس وأعوانه؛ فناسبت التثنية جمع كل طرف مع من يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص88، تحت «سر التعبير بالجمع هنا، وبالمثنى في سورة طه»","url":""}]},{"id":"s7-129","number":129,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قُدّم ﴿فيها﴾ في قوله: ﴿فيها تحيون﴾؟","answer":"للاهتمام بالأرض التي جُعلت موضع حياة بني آدم واستقرارهم، ولإبراز اختصاص حياتهم الدنيوية بها قبل الانتقال إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص97، تحت «بلاغة تقديم الجار والمجرور في جملة ﴿فيها تحيون﴾»","url":""}]},{"id":"s7-1574","number":1574,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قُدّم ﴿فيها﴾ في قوله: ﴿وفيها تموتون﴾؟","answer":"للاهتمام بالأرض بوصفها موضع الموت كما كانت موضع الحياة، وليكتمل نسق ارتباط الإنسان بها قبل إخراجه منها للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص99، تحت «بلاغة تقديم الجار والمجرور في قوله تعالى: ﴿وفيها تموتون﴾»","url":""}]},{"id":"s7-130","number":130,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لم عبر بالحياة في ﴿فيها تحيون﴾ بعد ذكر المعايش والاستقرار في الأرض؟","answer":"لأن الحياة أعم من المعيشة؛ فهي الأصل الذي يكون معه الانتفاع بالمعايش. وبعد بيان مكان الاستقرار جاء هذا التعبير ليبين شمول الأرض للحياة نفسها، ثم لما يليها من الموت والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص98–99، تحت «سر التعبير بالحياة في قوله تعالى: ﴿فيها تحيون﴾»","url":""}]},{"id":"s7-131","number":131,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا قيل: ﴿ومنها تخرجون﴾، لا: وفيها تبعثون؟","answer":"لأن الإخراج يصور البعث خروجًا محسوسًا من الأرض بعد الدفن، فيجعل مشهد انبعاث الأجساد من القبور حاضرًا في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100، تحت «سر التعبير بالإخراج في قوله تعالى: ﴿ومنها تخرجون﴾»","url":""}]},{"id":"s7-1575","number":1575,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"كيف تلخص الأفعال ﴿تحيون﴾ و﴿تموتون﴾ و﴿تخرجون﴾ رحلة الإنسان؟","answer":"تجمع الأفعال أطوار الإنسان في مقابلة موجزة: حياة في الأرض، ثم موت فيها، ثم خروج منها للبعث؛ فتربط البداية والنهاية والمصير بمشهد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100، تحت «بديع المقابلة بين الأفعال ﴿تحيون﴾ و﴿تموتون﴾ و﴿تخرجون﴾»","url":""}]},{"id":"s7-132","number":132,"surah":7,"verses":[25],"references":[{"surah":7,"verses":[25]}],"verseLabel":"الأعراف: 25","question":"لماذا بُني ﴿تخرجون﴾ للمجهول؟","answer":"بُني للمجهول للاهتمام بحدث الخروج وهوله، وللعلم بأن مخرِجهم هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص100–101، تحت «القراءات القرآنية وأثرها في ضبط لفظ ﴿تخرجون﴾»","url":""}]},{"id":"s7-133","number":133,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا افتتح النداء بـ﴿يا بني آدم﴾ بعد قصة أبويهم؟","answer":"جاء النداء عقب قصة أبويهم لينقل العبرة إلى ذريتهما ويحذرهم من فتنة الشيطان، ويذكرهم بنعمة اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص104–105، تحت «بلاغة النداء في قوله تعالى: ﴿يا بني آدم﴾»","url":""}]},{"id":"s7-134","number":134,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا عبّر عن خلق اللباس بقوله: ﴿أنزلنا عليكم لباسًا﴾؟","answer":"لأن أسبابه من رزق الله المنزل من السماء كالمطر الذي ينبت مواد اللباس، ولأن إظهاره للناس بقدرة الله يشبه إنزال النعمة عليهم. وفي التعبير تعظيم للمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص107، تحت «التعبير عن اللباس بالإنزال، مع أنه من الأرض في الظاهر لنا»","url":""}]},{"id":"s7-135","number":135,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا عُطف ﴿ريشًا﴾ على اللباس الذي يواري السوأة؟","answer":"للتفريق بين الضرورة والزينة: لباس يستر العورة، وريش يتجمل به الإنسان ويتسع به عيشه. فالعطف يجمع النعمتين مع اختلاف وظيفتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص111، تحت «دلالة العطف في قوله تعالى: ﴿وريشًا﴾»","url":""}]},{"id":"s7-136","number":136,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا سُميت الزينة ﴿ريشًا﴾؟","answer":"الريش في الأصل كسوة الطائر وزينته، فاستعير لما يتجمل به الإنسان من لباس ومال وهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص110–111، تحت «بلاغة الاستعارة في قوله تعالى: ﴿وريشًا﴾»","url":""}]},{"id":"s7-137","number":137,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"كيف تكون التقوى لباسًا؟","answer":"شبه تمكن التقوى من صاحبها وملازمتها له بملابسة الثوب للإنسان وإحاطته به؛ فاللباس يستر البدن، والتقوى تستر صاحبها من فضائح الذنوب وعواقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص112، تحت «بلاغة الاستعارة في قوله تعالى: ﴿ولباس التقوى﴾»","url":""}]},{"id":"s7-1576","number":1576,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"كيف يحمل قوله: ﴿ولباس التقوى ذلك خير﴾ حثًا من غير صيغة أمر؟","answer":"إخباره بأن لباس التقوى خير يتضمن الدعوة إلى تحصيله؛ فبيان خيريته يحرك الرغبة فيه ويحث على التقوى بأسلوب الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص113، تحت «إشعار الجملة الخبرية بالطلب»","url":""}]},{"id":"s7-138","number":138,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"ما أثر الإتيان باسم الإشارة في قوله: ﴿ولباس التقوى ذلك خير﴾؟","answer":"يُبرز اسم الإشارة لباس التقوى وينوه به، كأنه شيء حاضر متميز يُلفت إليه النظر ليُعرف قدره وخيريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص114، تحت «دلالة الإتيان باسم الإشارة في قوله تعالى: ﴿ذلك خير﴾»","url":""}]},{"id":"s7-1577","number":1577,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا أشير إلى لباس التقوى باسم البعيد ﴿ذلك﴾؟","answer":"ليس المراد بعدًا مكانيًا، بل تعظيم رتبته وعلو منزلته؛ فصيغة البعد ترفع شأن التقوى فوق الزينة الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص112، تحت «دلالة التعبير بصيغة البعد لاسم الإشارة ﴿ذلك﴾»","url":""}]},{"id":"s7-139","number":139,"surah":7,"verses":[26],"references":[{"surah":7,"verses":[26]}],"verseLabel":"الأعراف: 26","question":"لماذا خُتمت آية اللباس بقوله: ﴿لعلهم يذكرون﴾؟","answer":"ليتذكر بنو آدم نعمة الستر وقصة أبويهم، فيقابلوا النعمة بالشكر ويختاروا لباس التقوى ويحذروا فتنة الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص118، تحت «سر اختيار التعبير بالتذكر ﴿لعلهم يذكرون﴾»","url":""}]},{"id":"s7-140","number":140,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا قيل لبني آدم: ﴿لا يفتننكم الشيطان﴾؟","answer":"ظاهر اللفظ نهي للشيطان عن إيقاع الفتنة، والمقصود نهي بني آدم عن تمكينه منها باتباعه. فتوجيه النهي إلى سبب الفتنة يبالغ في التحذير منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص122، تحت «براعة التعبير بقوله تعالى: ﴿لا يفتننكم﴾ دون غيره»","url":""}]},{"id":"s7-141","number":141,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿كما أخرج أبويكم من الجنة﴾، مع أن المخرج حقيقة هو الله؟","answer":"نُسب الإخراج إليه سببيًا؛ لأنه أغراهما بالأكل فكان فعله سبب الخروج، أما المخرج حقيقة فهو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «بلاغة المجاز العقلي في قوله: ﴿أخرج أبويكم من الجنة﴾»","url":""}]},{"id":"s7-142","number":142,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا وصف آدم وحواء بـ﴿أبويكم﴾؟","answer":"سُميا أبويهم لأن البشر جميعًا من ذريتهما، وفي التعبير استثارة لعاطفة البنوة وأخذ العبرة من تجربتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «سر العدول عن لفظي (آدم) و(حواء) إلى لفظ ﴿أبويكم﴾»","url":""}]},{"id":"s7-143","number":143,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما أثر المضارع في قوله: ﴿ينزع عنهما لباسهما﴾؟","answer":"يستحضر المضارع صورة النزع كأنها تقع أمام السامع، ويجدد التحذير من فعل الشيطان وطرائق فتنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص126، تحت «نكتة التعبير بصيغة المضارع ﴿ينزع﴾»","url":""}]},{"id":"s7-1578","number":1578,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا اختير لفظ ﴿ينزع﴾ في وصف سلب اللباس؟","answer":"لأن النزع يصور سلب ستر كان ثابتًا وملازمًا، وفيه معنى الشدة وكشف ما كان مصونًا، فيقوي صورة الفتنة وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص127–128، تحت «سر التعبير: ﴿ينزع عنهما لباسهما﴾»","url":""}]},{"id":"s7-1579","number":1579,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة اللام في قوله: ﴿ليريهما سوآتهما﴾؟","answer":"تحتمل لام العاقبة؛ لأن كشف السوءات كان نتيجة الإغواء، وتحتمل التعليل بإسناد غاية الفعل إلى المتسبب فيه. وعلى الوجهين تشتد صورة التحذير من الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص128، تحت «دلالة اللام في قوله تعالى: ﴿ليريهما﴾»","url":""}]},{"id":"s7-144","number":144,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا أُكد الخبر: ﴿إنه يراكم هو وقبيله﴾؟","answer":"لتقوية التحذير من عدو يراقب بني آدم وهم لا يرونه، حتى يكون حذرهم دائمًا ولا يغفلوا عن مداخل فتنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص129، تحت «دلالة تأكيد رؤية الشيطان وقبيله لبني آدم»","url":""}]},{"id":"s7-1580","number":1580,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة ذكر ﴿هو﴾ في قوله: ﴿يراكم هو وقبيله﴾؟","answer":"يؤكد الضمير المستتر في ﴿يراكم﴾، ويعيد التنبيه إلى أن الشيطان الذي فتن الأبوين هو نفسه المتربص بذريتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص130، تحت «دلالة ذكر الضمير ﴿هو﴾ في قوله تعالى: ﴿هو وقبيله﴾»","url":""}]},{"id":"s7-145","number":145,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿من حيث لا ترونهم﴾، لا: وأنتم لا ترونهم؟","answer":"﴿من حيث﴾ تدل على جهة ووجه خفي لا تقع منه رؤيتهم أصلًا، فهي أبلغ من مجرد الحال ﴿وأنتم لا ترونهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص130–131، تحت «سر مجيء الظرف، والتعبير بعدم الرؤية في ﴿لا ترونهم﴾»","url":""}]},{"id":"s7-146","number":146,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"لماذا أعقب التحذير من الشيطان بقوله: ﴿إنا جعلنا الشياطين أولياء للذين لا يؤمنون﴾؟","answer":"ليبين أن ولاية الشياطين ليست أمرًا منفصلًا عن اختيار الإنسان؛ فهي عقوبة توافق إعراض من لا يؤمن، وتحذير من أن يقود ترك الإيمان إلى قبول ولايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص132–133، تحت «بلاغة موقع قوله تعالى: ﴿إنا جعلنا الشياطين أولياء﴾»","url":""}]},{"id":"s7-1581","number":1581,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما دلالة وصف أولياء الشياطين بأنهم ﴿الذين لا يؤمنون﴾؟","answer":"تعرّفهم الصلة بالسبب الذي هيأهم لهذه الولاية؛ فعدم الإيمان هو الأصل الذي يفتح باب اتباع الشيطان وقبول سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص133، تحت «مناسبة مجيء الاسم الموصول وصلته»","url":""}]},{"id":"s7-1582","number":1582,"surah":7,"verses":[27],"references":[{"surah":7,"verses":[27]}],"verseLabel":"الأعراف: 27","question":"ما أثر تذييل الآية ببيان أولياء الشياطين؟","answer":"يعمم المعنى ويقرره: الشياطين أولياء لمن لا يؤمنون. فيغدو ختام الآية قاعدة تحذيرية كلية بعد تصوير خطرهم الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص134، تحت «حسن التذييل في آخر الآية، وأثره في المعنى»","url":""}]},{"id":"s7-147","number":147,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا جاء الشرط بالماضي في قوله: ﴿وإذا فعلوا فاحشة﴾؟","answer":"جيء بالماضي لتصوير الفاحشة أمرًا متحقق الوقوع منهم ومتكررًا حتى صار عادة معروفة، لا مجرد احتمال بعيد؛ ولذلك بُني الرد على واقع فعلوه واحتجوا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص136، تحت «سر التعبير بالفعل الماضي في الشرط ﴿فعلوا﴾»","url":""}]},{"id":"s7-1583","number":1583,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا قيل: ﴿فعلوا فاحشة﴾، لا: عملوا فاحشة؟","answer":"الفعل أعم من العمل، وقد يقع من غير نظر في القصد والعاقبة؛ فاختياره يصور اندفاعهم إلى القبيح من غير تدبر، بخلاف العمل الذي يكثر اقترانه بالقصد والمعالجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص137، تحت «سر التعبير بـ﴿فعلوا﴾ دون عملوا»","url":""}]},{"id":"s7-1584","number":1584,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف سوّغ المشركون فعل الفاحشة لأنفسهم؟","answer":"جمعوا حجتين باطلتين: تقليد الآباء، ثم الافتراء بأن الله أمرهم بها. وعطف الثانية يكشف انتقالهم من اتباع الموروث إلى نسبة التشريع نفسه إلى الله، وهو أشد في البطلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص141، تحت «مناسبة العطف في قوله تعالى: ﴿والله أمرنا بها﴾»","url":""}]},{"id":"s7-148","number":148,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ما دلالة تقديم ﴿عليها﴾ في قولهم: ﴿وجدنا عليها آباءنا﴾؟","answer":"قُدّم ﴿عليها﴾ للاهتمام بالحال التي وجدوا آباءهم ملازمين لها، وتصوير شدة تعلقهم بالفاحشة وتقليدهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص140، تحت «نكتة تقديم قوله تعالى: ﴿عليها﴾ على ﴿آباءنا﴾»","url":""}]},{"id":"s7-149","number":149,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف أبطل القرآن احتجاجهم بأن الله أمرهم بالفاحشة؟","answer":"رد الدعوى من أصلها بنفي أن يأمر الله بالفحشاء، ثم واجههم بالاستفهام المنكر عن القول عليه بلا علم؛ فجمع بين إبطال المدعى وكشف أن حجتهم افتراء لا برهان له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص144، تحت «بلاغة الاحتجاج في سياق الآية الكريمة»","url":""}]},{"id":"s7-1585","number":1585,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"كيف انتظمت جملتا ﴿إن الله لا يأمر بالفحشاء﴾ و﴿أتقولون على الله ما لا تعلمون﴾ في جواب واحد؟","answer":"دخلتا معًا في مقول ﴿قل﴾: الأولى تقرر الحق الذي ينسف دعواهم، والثانية تنكر عليهم جرأتهم. فتم الرد بإثبات المبدأ ثم إلزامهم بنتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص146، تحت «سر مجيء جملة الاستفهام مع سابقتها مقول قول واحد»","url":""}]},{"id":"s7-150","number":150,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"لماذا اختيرت ﴿الفحشاء﴾ في الرد، لا ﴿فاحشة﴾ كما في أول الآية؟","answer":"عُرفت ﴿الفحشاء﴾ للجنس، فنفى أن يأمر الله بأي شيء من جنس القبائح؛ وهو أعم وأقوى من إعادة فاحشة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص144، تحت «سر التعبير بالإظهار في مقام الإضمار، فقال: ﴿بالفحشاء﴾»","url":""}]},{"id":"s7-151","number":151,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ما دلالة الاستفهام في قوله: ﴿أتقولون على الله ما لا تعلمون﴾؟","answer":"خرج الاستفهام إلى التوبيخ والإنكار؛ إذ لا حجة لهم على نسبة هذا التشريع إلى الله، فجعل مجرد نطقهم به موضع استنكار شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص145، تحت «بلاغة الاستفهام المجازي في قوله تعالى: ﴿أتقولون﴾»","url":""}]},{"id":"s7-1586","number":1586,"surah":7,"verses":[28],"references":[{"surah":7,"verses":[28]}],"verseLabel":"الأعراف: 28","question":"ماذا أفاد التعبير بـ﴿ما لا تعلمون﴾ في وصف قولهم على الله؟","answer":"عمم الموصول كل قول لا يستند إلى علم، وجعل جهلهم بالحكم نفسه حجة عليهم؛ فمن لا يعلم لا يملك أن ينسب إلى الله أمرًا أو تحريمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص146، تحت «دلالة ﴿ما﴾ في قوله تعالى: ﴿ما لا تعلمون﴾»","url":""}]},{"id":"s7-152","number":152,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"لماذا قابل الفحشاء بقوله: ﴿قل أمر ربي بالقسط﴾؟","answer":"القسط ضد الفحشاء والظلم، فجاء الأمر به ردًا جامعًا يثبت أن تشريع الله قائم على العدل والاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص151، تحت «نكتة التعبير بلفظ (القسط)»","url":""}]},{"id":"s7-153","number":153,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"ما الذي تصوره استعارة الإقامة في قوله: ﴿وأقيموا وجوهكم﴾؟","answer":"استعيرت الإقامة للتوجه المستقيم إلى عبادة الله مع الثبات والمداومة؛ فالمطلوب ليس حركة الوجه وحدها، بل استقامة العبد في قصده وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص153، تحت «بلاغة الاستعارة في قوله تعالى: ﴿وأقيموا﴾»","url":""}]},{"id":"s7-1587","number":1587,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"هل المراد بالوجوه في ﴿وأقيموا وجوهكم﴾ ظاهر الوجه فقط؟","answer":"يحتمل أن يراد بالوجه الذات كلها، بذكر أشرف الجزء وإرادة الكل، وأن يراد به القصد والوجهة. وفي الحالين ينتقل التعبير من الجارحة إلى إخلاص الإنسان كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص154، تحت «لفظ ﴿وجوهكم﴾ بين المجاز المرسل والاستعارة»","url":""}]},{"id":"s7-154","number":154,"surah":7,"verses":[29,31],"references":[{"surah":7,"verses":[29,31]}],"verseLabel":"الأعراف: 29؛ الأعراف: 31","question":"ما سر التعبير بقوله: ﴿عند كل مسجد﴾؟","answer":"يحتمل المسجد موضع الصلاة أو وقتها أو السجود نفسه، فيعم الأمر كل حال عبادة. ولفظ ﴿عند﴾ يربط إقامة الوجه بمقام التوجه إلى الله، لا ببناء مخصوص وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص154–155، تحت «دلالة قوله تعالى: ﴿عند كل مسجد﴾»","url":""}]},{"id":"s7-155","number":155,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿وادعوه مخلصين له الدين﴾، فقدم ﴿له﴾؟","answer":"قُدّم ﴿له﴾ للاختصاص: يكون الدين والدعاء خالصين لله وحده، لا نصيب فيهما لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص156، تحت «دلالة تقديم ﴿له﴾ في السياق»","url":""}]},{"id":"s7-156","number":156,"surah":7,"verses":[29],"references":[{"surah":7,"verses":[29]}],"verseLabel":"الأعراف: 29","question":"لماذا شُبه البعث بالبدء في قوله: ﴿كما بدأكم تعودون﴾؟","answer":"يجعل التشبيه الخلق الأول دليلًا مشاهدًا على الإعادة؛ فمن أنشأهم أول مرة قادر على بعثهم. وبذلك يقرب الغيب إلى العقل بما يقر به المخاطب من أصل وجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص157–158، تحت «بلاغة التشبيه في ﴿كما بدأكم﴾»","url":""}]},{"id":"s7-157","number":157,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا أسند الهدى إلى الله في ﴿فريقًا هدى﴾ ولم تسند إليه الضلالة؟","answer":"أسند الهدى إلى الله لأنه فضل ومنة، وحُذف إسناد الضلالة إليه أدبًا، مع بيان سببها في اختيارهم ولاية الشياطين؛ فلا يوهم التعبير أنهم أضلوا بلا مسؤولية منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص162، تحت «نكتة إسناد (الهدى) إلى الله دون (الضلالة)»","url":""}]},{"id":"s7-158","number":158,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما سرّ تقديم المفعول ﴿فريقًا﴾ في الجملتين؟","answer":"على إعراب ﴿فريقًا﴾ مفعولًا مقدمًا، يبرز التقديم اختصاص فريق بالهداية، ويشعر بأن الفريق المقابل لم يرد هدايته، ثم تصرح الجملة التالية بمآله. وبذلك يظهر التقسيم والتقابل قبل تفصيل حكم كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص161–162، تحت «الوقف القرآني وتعدد المعنى»","url":""}]},{"id":"s7-159","number":159,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿حق عليهم الضلالة﴾، لا: أضلهم؟","answer":"﴿حق﴾ تفيد ثبوت الضلالة واستحقاقها ولزومها لهم بعد أسبابها، لا نسبة الإضلال إليهم بلا بيان لمسؤوليتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص162–163، تحت «سر اختلاف التعبير بين ﴿حق عليهم الضلالة﴾ مقابل الهداية»","url":""}]},{"id":"s7-160","number":160,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا أكدت علة ضلالهم بـ﴿إنهم اتخذوا الشياطين أولياء﴾؟","answer":"جاء التوكيد ليقرر السبب الحقيقي لضلالهم ويربط الجزاء باختيارهم؛ فلم تقع الضلالة اعتباطًا، بل ثبتت عليهم لاتخاذهم الشياطين أولياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة التعبير بـ(إن) في سياق الآية الكريمة»","url":""}]},{"id":"s7-1588","number":1588,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ماذا يكشف لفظ ﴿اتخذوا﴾ في وصف ولايتهم للشياطين؟","answer":"يدل الاتخاذ على قصد وتمكن ومداومة؛ فهم لم تعرض لهم وسوسة عابرة، بل جعلوا الشياطين أولياء يتبعونهم، ولذلك استحقوا الضلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة التعبير بلفظ ﴿اتخذوا﴾ دون غيره»","url":""}]},{"id":"s7-1589","number":1589,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"ما الذي تضيفه عبارة ﴿من دون الله﴾ إلى وصف ولايتهم؟","answer":"تكشف أنهم لم يكتفوا باتباع الشياطين، بل آثروهم على ولاية الله وأعرضوا عن هدايته؛ فاجتمع في فعلهم اتخاذ الباطل وترك الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص165، تحت «دلالة الصفة في قوله تعالى: ﴿من دون الله﴾»","url":""}]},{"id":"s7-161","number":161,"surah":7,"verses":[30],"references":[{"surah":7,"verses":[30]}],"verseLabel":"الأعراف: 30","question":"لماذا خُتمت بـ﴿ويحسبون أنهم مهتدون﴾؟","answer":"يجمع الختام بين وقوعهم في الضلال واعتقادهم أنهم على الهدى؛ فهم يفعلون القبائح ويحسبونها طاعة وقربى. وبالجملة الاسمية في ﴿أنهم مهتدون﴾ يظهر رسوخ هذا الوهم في أنفسهم، فتشتد صورة ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص167–168، تحت «سر ختام الآية بقوله تعالى: ﴿ويحسبون أنهم مهتدون﴾»","url":""}]},{"id":"s7-162","number":162,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا جدد النداء بقوله: ﴿يا بني آدم﴾؟","answer":"جدد النداء لاستقلال الوصية الجديدة وعظمها، وليستحضر المخاطبون انتسابهم إلى آدم بعد التحذير من فتنة الشيطان؛ فيتهيؤوا لسماع ما يحفظ كرامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص171–172، تحت «نكتة إعادة النداء»","url":""}]},{"id":"s7-163","number":163,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا قيل: ﴿خذوا زينتكم﴾، لا: البسوا ثيابكم؟","answer":"ناسب ﴿خذوا﴾ حال من كانوا يلقون ثيابهم ويتعرون للطواف؛ فأمروا باستصحابها وارتدائها. واللفظ أوسع من مجرد اللبس، إذ يشمل إعداد الزينة للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص172–173، تحت «بلاغة التعبير بالأخذ دون فعل اللبس»","url":""}]},{"id":"s7-1590","number":1590,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا سميت الثياب هنا زينة، ولم تسم لباسًا؟","answer":"الزينة أبعث على الرغبة في الستر وتحسين الهيئة؛ فخوطبوا بما يحبب إليهم التجمل عند العبادة، بدل الاقتصار على معنى ستر العورة الذي يؤديه لفظ اللباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص174–175، تحت «سر التعبير بلفظ الزينة دون اللباس»","url":""}]},{"id":"s7-164","number":164,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا أضاف الزينة إليهم: ﴿زينتكم﴾؟","answer":"تنسب الزينة إلى المخاطبين بوصفها ملكًا لهم وفي متناولهم، فتحثهم على استعمالها ولا تترك لهم عذرًا في التخلي عنها. وفي الإضافة تحفيز وترغيب في حسن الهيئة عند الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص174–175، تحت «دلالة إضافة لفظ الزينة لكاف الخطاب»","url":""}]},{"id":"s7-166","number":166,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"كيف جمع نظم الآية بين أخذ الزينة والأكل والشرب في عبارة موجزة؟","answer":"ذكر أخذ الزينة أولًا فدل على اللباس، وذكر الأكل والشرب بعده فدل على سائر الانتفاع المباح؛ فجمع حاجات الظاهر والبدن، وحذف من كل جانب ما يدل عليه الآخر في نظم موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص176، تحت «بديع فن الاحتباك»","url":""}]},{"id":"s7-167","number":167,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"ما سر عطف ﴿ولا تسرفوا﴾ على إباحة الأكل والشرب؟","answer":"جاء النهي عقب الأمر حتى تبقى الإباحة في حد الاعتدال؛ فالانتفاع بالنعمة مشروع، أما مجاوزة الحاجة والتبذير فتحول الانتفاع إلى ضرر ومعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص177–178، تحت «دلالة عطف النهي على الأمر»","url":""}]},{"id":"s7-168","number":168,"surah":7,"verses":[31],"references":[{"surah":7,"verses":[31]}],"verseLabel":"الأعراف: 31","question":"لماذا زجر عن الإسراف بنفي المحبة في ﴿إنه لا يحب المسرفين﴾؟","answer":"نفي المحبة يحذر من الإسراف مع إبقاء باب الرجاء، ويستميل المخاطب إلى طلب محبة الله بالاعتدال. فهو أنسب بمقام الإرشاد من الاقتصار على إثبات الكراهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص178–179، تحت «نكتة إيثار نفي الحب على إثبات الكراهية»","url":""}]},{"id":"s7-169","number":169,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما دلالة الاستفهام في قوله: ﴿قل من حرم زينة الله﴾؟","answer":"هو استفهام إنكاري يطلب منهم سند التحريم فلا يجدونه؛ فيبطل حق البشر في منع ما أباحه الله، ويكشف أن تشريعهم قائم على الهوى لا البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص184–185، تحت «غرض الاستفهام»","url":""}]},{"id":"s7-170","number":170,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا أضيفت الزينة إلى الله: ﴿زينة الله﴾؟","answer":"إضافتها إليه لأنها خلقه وعطيته وتشريعه لعباده، فلا يملك غيره تحريمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص185–186، تحت «دلالات إضافة ﴿زينة﴾ إلى لفظ الجلالة»","url":""}]},{"id":"s7-171","number":171,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما سر التعبير بقوله: ﴿التي أخرج لعباده﴾؟","answer":"يصور الإخراج إبراز الزينة من أسبابها وإظهارها للعباد بعد خفائها في موادها؛ فيشعر بالعناية والتيسير، ويذكرهم بأن وصولها إليهم من تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص186، تحت «فائدة استعمال الفعل ﴿أخرج﴾»","url":""}]},{"id":"s7-172","number":172,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا جمع بين الزينة و﴿الطيبات من الرزق﴾؟","answer":"الزينة تصلح الظاهر وتجمله، والطيبات تقوم البدن وتلذه؛ فجمع نوعي النعمة ودفع تحريم المشركين لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص187–188، تحت «نكتة عطف الطيبات على الزينة»","url":""}]},{"id":"s7-173","number":173,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"كيف تكون الزينة والطيبات ﴿للذين آمنوا﴾ مع انتفاع الكافرين بها في الدنيا؟","answer":"اللام للاختصاص الأصلي والإباحة؛ فالمؤمنون هم المقصودون بهذه النعم لأنهم يشكرون المنعم ويستعملونها في طاعته، وإن شاركهم غيرهم فيها زمن الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص190–191، تحت «معنى اللام ودلالتها»","url":""}]},{"id":"s7-1591","number":1591,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا ذكر المؤمنون وحدهم في الدنيا مع أن غيرهم يشاركهم في الزينة والطيبات؟","answer":"اكتفى بذكر المؤمنين تنبيهًا إلى أنهم أهل الانتفاع المقصود بهذه النعم، وحذف ذكر غيرهم مع فهم مشاركتهم العارضة في الدنيا؛ ثم يخلص النعيم للمؤمنين في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص191، تحت «سر حذف المعطوف»","url":""}]},{"id":"s7-174","number":174,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما الذي يفيده وصف النعم بأنها ﴿خالصة يوم القيامة﴾؟","answer":"تفيد أنها خاصة بالمؤمنين يوم القيامة لا يشاركهم فيها الكافرون، وأنها نقية من منغصات الدنيا وكدرها؛ فيجتمع خلوص الملك وخلوص النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص182، تحت «شرح المفردات: ﴿خالصة﴾»","url":""}]},{"id":"s7-175","number":175,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ما وجه التشبيه في قوله: ﴿كذلك نفصل الآيات﴾؟","answer":"شبه هذا البيان المفصل للزينة والطيبات بما يجري عليه بيان سائر الأحكام؛ فكما اتضح الحكم هنا تتضح الآيات بالحجة والتفصيل، ليزول الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص192، تحت «بلاغة التشبيه المرسل المجمل»","url":""}]},{"id":"s7-1592","number":1592,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"ماذا تفيد اللام في قوله: ﴿لقوم يعلمون﴾؟","answer":"تفيد أن أهل العلم هم المنتفعون بهذا التفصيل والمقصودون به؛ لأنهم يتلقون الآيات بفهم وقبول، لا أن البيان محجوب عمن سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص192، تحت «فائدة اللام ودلالتها»","url":""}]},{"id":"s7-1593","number":1593,"surah":7,"verses":[32],"references":[{"surah":7,"verses":[32]}],"verseLabel":"الأعراف: 32","question":"لماذا خُص أهل العلم في قوله: ﴿لقوم يعلمون﴾؟","answer":"لأن العلم أثبت وأرسخ من الفهم العابر، وهو الذي يحمل صاحبه على تمييز الحلال من الحرام والعمل بالدليل؛ فناسب ختام آيات الأحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص193، تحت «سر التعبير بالعلم دون الفهم»","url":""}]},{"id":"s7-176","number":176,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"ما سر القصر في قوله: ﴿إنما حرم ربي﴾ بعد سؤال ﴿من حرم﴾؟","answer":"هو قصر إضافي يرد على المشركين: المحرمات الحقيقية هي ما ذكره الله، لا الزينة والطيبات التي منعوها. وجاءت ﴿إنما﴾ لتقرير ما يعرفونه في أصل الفطرة وتوبيخهم على مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص200–201، تحت «غرض القصر في سياق الرد على المشركين»","url":""}]},{"id":"s7-177","number":177,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا بدأت المحرمات بـ﴿الفواحش ما ظهر منها وما بطن﴾؟","answer":"بدأ بها لعظم خطرها وظهور فسادها في الفرد والمجتمع، ثم تدرج إلى بقية الأصول المحرمة. وجمع الظاهر والباطن ليشمل الفعل المعلن والخفي ولا يترك للهوى منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص203–204، تحت «نكتة ترتيب المحرمات في الآية»","url":""}]},{"id":"s7-178","number":178,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"ما الفرق بين الإثم والبغي في سياق المحرمات؟","answer":"الإثم اسم لما يجلب الذم والعقوبة من المعاصي، أما البغي فهو تجاوز الحق إلى ظلم الغير والاستطالة عليه. فذكرهما يجمع فساد المرء في نفسه واعتداءه على سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص209–210، تحت «الإثم والعدوان والبغي»","url":""}]},{"id":"s7-179","number":179,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا قُيّد البغي بـ﴿بغير الحق﴾ مع أن البغي لا يكون بحق؟","answer":"يبطل القيد دعوى من يتصور أن تعدي بعض الناس على بعض هو الحق، فيصرح بأن البغي المذكور ظلم. ويحتمل الاحتراز من مقابلة المعتدي بالحق واستيفاء القصاص المشروع، مما يشبه البغي في صورته ولا يكون بغيًا مذمومًا في حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص205–206، تحت «فائدة ذكر قيد ﴿بغير الحق﴾»","url":""}]},{"id":"s7-180","number":180,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"كيف يقوي قوله: ﴿ما لم ينزل به سلطانًا﴾ إبطال الشرك؟","answer":"ينفي عن الشرك أي حجة منزلة، لا ليفهم إمكان شريك يقوم عليه برهان، بل للتهكم بدعواهم؛ إذ يستحيل أن ينزل الله دليلًا يثبت له شريكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص206–207، تحت «بلاغة ذكر القيد»","url":""}]},{"id":"s7-1594","number":1594,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا يسمى البرهان سلطانًا؟","answer":"لأن الحجة الواضحة تقهر الباطل وتستولي على العقل بقوتها، كما ينفذ السلطان أمره. فنفي السلطان عن الشرك يصوره دعوى عاجزة لا سند لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص210، تحت «السلطان والحجة»","url":""}]},{"id":"s7-181","number":181,"surah":7,"verses":[33],"references":[{"surah":7,"verses":[33]}],"verseLabel":"الأعراف: 33","question":"لماذا جعل القول على الله بلا علم خاتمة المحرمات؟","answer":"جُعل خاتمة لأنه أصل عظيم تنشأ عنه البدع والتحليل والتحريم والشرك؛ ومن افترى على الله جمع أنواع الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص203–205، تحت «نكتة ترتيب المحرمات في الآية»","url":""}]},{"id":"s7-182","number":182,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا أضيف الأجل إلى الأمة في ﴿فإذا جاء أجلهم﴾ لا إلى أفرادها؟","answer":"لأن السياق في أجل الجماعة: مدة بقائها أو وقت حلول عقوبتها بعد التكذيب، فللأمم سنن وآجال عامة كما للأفراد آجال خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص217، تحت «غرض إضافة الأجل إلى ضمير الأمة»","url":""}]},{"id":"s7-1595","number":1595,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا عبر بـ﴿أمة﴾ في قوله: ﴿ولكل أمة أجل﴾؟","answer":"الأمة جماعة يجمعها شأن أو دين أو زمن، فيلائم اللفظ الحديث عن مصير جماعي وسنة تجري على المكذبين بوصفهم مجتمعًا، لا أفرادًا متفرقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص214، تحت «سر التعبير بأمة»","url":""}]},{"id":"s7-183","number":183,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما دلالة العموم في قوله: ﴿ولكل أمة أجل﴾؟","answer":"لفظ ﴿كل﴾ يقرر أن السنة لا تحابي أمة؛ فلكل جماعة أجل مقدر، ولا يخرج المكذبون من هذا القانون العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص213–214، تحت «دلالة العموم الصريح»","url":""}]},{"id":"s7-1596","number":1596,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما الذي أفاده حذف صفة الأمة في قوله: ﴿ولكل أمة أجل﴾؟","answer":"حذفت الصفة اعتمادًا على السياق، والتقدير: لكل أمة مكذبة معاندة أجل. فالإيجاز يبقي اللفظ عامًا، ويجعل الوعيد متجهًا إلى من تحققت فيهم صفة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص214–215، تحت «نكتة الإيجاز بحذف الصفة»","url":""}]},{"id":"s7-184","number":184,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا جاء أجلهم﴾، فجعل الأجل آتيًا؟","answer":"شُبه الأجل بغائب يأتي عند حلول وقته، فيصور حتميته وأنه يوافيهم لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص216، تحت «بلاغة الاستعارة في إسناد المجيء إلى الأجل»","url":""}]},{"id":"s7-185","number":185,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]},{"surah":10,"verses":[49]}],"verseLabel":"الأعراف: 34؛ يونس: 49","question":"ما أثر الجمع بين نفي الاستئخار ونفي الاستقدام؟","answer":"جمع النفي بين طرفي الزمن ليقرر ثبات الأجل من الجهتين: فلا يستطيعون دفعه بالتأخير ولا تغييره بالتقديم. ويشتد بذلك الوعيد بأن الموعد خارج عن تصرفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص218–219، تحت «بديع فن الطباق»","url":""}]},{"id":"s7-186","number":186,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سرّ تقديم الاستئخار على الاستقدام؟","answer":"قدم نفي الاستئخار لأن الغرض هنا بيان أنهم لن يجدوا خلاصًا من حلول العذاب ولا مهربًا منه بالتأخير. ثم نفى الاستقدام، فسوى بين الطرفين في الاستحالة وقرر ثبات الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص219، تحت «فائدة عطف الجمل»","url":""}]},{"id":"s7-187","number":187,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"لماذا نُكرت ﴿ساعة﴾؟","answer":"نُكرت للتقليل: لا يتأخرون أقل جزء من الزمن، فضلًا عن مدة طويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص218–219، تحت «سر التعبير بساعة عن أقل الوقت»","url":""}]},{"id":"s7-188","number":188,"surah":7,"verses":[34],"references":[{"surah":7,"verses":[34]}],"verseLabel":"الأعراف: 34","question":"ما سر انتقال الفاء في الأعراف والنحل إلى صدر الشرط، وبقائها في جواب الشرط في يونس؟","answer":"في الأعراف والنحل ترتب ذكر مجيء الأجل على الكلام السابق، فدخلت الفاء على ﴿إذا﴾ للتفريع والتعقيب. أما في يونس فجاء تقرير الأجل بعد نفي ملك الرسول الضر والنفع، فدخلت الفاء على جواب الشرط لتربط عدم الاستئخار بحلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص219–220، وج19، ص483، تحت «توجيه المتشابه اللفظي بين آية يونس والأعراف والنحل»","url":""}]},{"id":"s7-189","number":189,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لم جدد نداء ﴿يا بني آدم﴾ عند الحديث عن مجيء الرسل؟","answer":"لتجديد التنبيه والعناية بما سيلقى عليهم من عهد الرسل وسبيل النجاة، بعد الوصايا السابقة. فإعادة النداء تستدعي الإصغاء إلى هذا الأمر وتبرز أهميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «نكتة تكرار النداء»","url":""}]},{"id":"s7-190","number":190,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا قيل: ﴿إما يأتينكم﴾ بالمضارع مع تحقق مجيء الرسل؟","answer":"يستحضر المضارع مجيء الرسل متجددًا في أزمنة الأمم، ويصور البلاغ كأنه يقع أمام المخاطبين؛ فلا يراد الشك، بل تجديد العهد كلما جاء رسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «دلالة العدول عن الماضي إلى المضارع»","url":""}]},{"id":"s7-191","number":191,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا أكد فعل المجيء بنون التوكيد؟","answer":"النون تؤكد حتمية وصول الرسل والبلاغ إلى المخاطبين، وتلائم مقام العهد والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص224، تحت «بلاغة تأكيد الشرط»","url":""}]},{"id":"s7-192","number":192,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ما دلالة الجار والمجرور في الامتنان في قوله تعالى: ﴿رسل منكم﴾؟","answer":"﴿منكم﴾ تؤنسهم بالرسل وتجعل الحجة أبلغ؛ فهم بشر يعرفون لسان قومهم وأحوالهم ويمكن الاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص225–226، تحت «دلالة الجار والمجرور في الامتنان»","url":""}]},{"id":"s7-193","number":193,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا عبر عن تبليغ الوحي بقوله: ﴿يقصون عليكم آياتي﴾؟","answer":"القص أعم من مجرد التلاوة؛ فهو اتباع للخبر وبيان لمعناه، ويشمل ما يبلغ من صحيفة أو من غيرها. لذلك يلائم مهمة الرسل في عرض الآيات وشرحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص226–227، تحت «سر اختيار مفردة ﴿يقصون﴾ دون مرادفاتها»","url":""}]},{"id":"s7-1597","number":1597,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ماذا يفيد المضارع في قوله: ﴿يقصون عليكم آياتي﴾؟","answer":"يصور استمرار الرسل في التبليغ وتجدد بيانهم للناس، ويستحضر أداء الرسالة كأنه مشهد قائم؛ فتظهر ملازمتهم لوظيفتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص226، تحت «نكتة التعبير عن الصفة بالفعل المضارع»","url":""}]},{"id":"s7-194","number":194,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"لماذا قيل: ﴿فمن اتقى وأصلح﴾، ولم يقل: فمن صدق واتبع؟","answer":"عدل إلى التقوى والإصلاح ليبين ثمرة اتباع الرسل: اجتناب المعصية وإصلاح العمل. فالنجاة لا تتحقق بمجرد دعوى التصديق، بل بانقياد يغير حال الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص229، تحت «سر العدول عما يقتضيه الظاهر في جواب الشرط»","url":""}]},{"id":"s7-195","number":195,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ما الفرق بين الخوف والحزن في قوله: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"الخوف همّ يلحق الإنسان لشيء متوقع في المستقبل، والحزن غم يقع لما مضى وفات؛ فنفيهما يجمع لهم الأمن من آتي الزمن وصفاء النفس مما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص236، تحت «الخوف والحزن»","url":""}]},{"id":"s7-196","number":196,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"لماذا قابل المتقين بـ﴿الذين كذبوا بآياتنا واستكبروا عنها﴾؟","answer":"لأنهما يقابلان ﴿اتقى وأصلح﴾: التكذيب فساد الاعتقاد، والاستكبار امتناع عن الانقياد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص232–233، تحت «سر الاختلاف في التعبير بين المتقابلات»","url":""}]},{"id":"s7-197","number":197,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"كيف يبين قوله ﴿واستكبروا عنها﴾ سبب التكذيب بالآيات؟","answer":"ذكر الاستكبار بعد التكذيب يكشف أن امتناعهم عن قبول الآيات صادر عن الترفع والعناد، لا عن نقص بيانها. ففي العطف تفسير لعلة التكذيب، مع زيادة بيان قبح موقفهم وشناعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص233–234، تحت «فائدة عطف الاستكبار على التكذيب»","url":""}]},{"id":"s7-198","number":198,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿أولئك أصحاب النار﴾، فجعلهم أصحابًا لها؟","answer":"الصاحب ملازم لصاحبه؛ فالتعبير يدل على ملازمتهم النار وعدم انفكاكهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص234–235، تحت «دلالة اختيار لفظ الصحبة»","url":""}]},{"id":"s7-199","number":199,"surah":7,"verses":[36],"references":[{"surah":7,"verses":[36]}],"verseLabel":"الأعراف: 36","question":"ماذا أفاد قوله: ﴿هم فيها خالدون﴾ بعد وصفهم بأصحاب النار؟","answer":"الجملة الاسمية تؤكد دوام ملازمتهم النار وثبات الخلود، وإعادة الضمير تزيد التقرير، وتقديم ﴿فيها﴾ يقصر خلودهم على هذا المصير المهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص235–236، تحت «دلالة التوكيد بالجملة الاسمية»","url":""}]},{"id":"s7-200","number":200,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما غرض الاستفهام في قوله: ﴿فمن أظلم ممن افترى على الله كذبًا أو كذب بآياته﴾؟","answer":"الاستفهام للإنكار والنفي: لا أحد أشد ظلمًا ممن اختلق على الله قولًا أو رد آياته؛ وفيه تقريع وتحذير من بلوغ غاية الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص240، تحت «غرض الاستفهام وفائدته»","url":""}]},{"id":"s7-1598","number":1598,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ماذا أفاد الجمع بين الافتراء على الله والتكذيب بآياته؟","answer":"جمع الطرفين: إنشاء الباطل من عند النفس، ورد الحق حين يأتي من الله. فصور طريقَي محاربة الوحي، وبين أن كليهما ظلم عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص242، تحت «براعة التعبير في الجمع بين لفظ الافتراء والتكذيب»","url":""}]},{"id":"s7-201","number":201,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"لماذا عطف الافتراء والتكذيب بـ﴿أو﴾؟","answer":"يوجه المصدر ﴿أو﴾ هنا بمعنى الإضراب والترقي: بل كذب بآياته؛ فينتقل من افتراء الكذب على الله إلى تكذيب آياته، مبينًا شناعة كل من الوصفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص243، تحت «معنى حرف ﴿أو﴾»","url":""}]},{"id":"s7-202","number":202,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما سر التعبير بقوله: ﴿ينالهم نصيبهم﴾؟","answer":"صور النصيب كشيء يصل إليهم ويصيبهم حتمًا؛ فتجعل الاستعارة ما كتب لهم من رزق وأجل أو عذاب أمرًا لا يفوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص244، تحت «بلاغة الاستعارة المكنية»","url":""}]},{"id":"s7-1599","number":1599,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما المقصود بالكتاب في قوله: ﴿نصيبهم من الكتاب﴾؟","answer":"هو ما كتب وقدر لهم في اللوح من رزق وأجل وعمل، وقيل نصيبهم من العذاب. والتعريف يستحضر الكتاب المعلوم الذي أحصى الله فيه المقادير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص245، تحت «دلالة استعمال مفردة الكتاب ومعنى التعريف»","url":""}]},{"id":"s7-203","number":203,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا جاءتهم رسلنا يتوفونهم﴾، فجمع الرسل؟","answer":"المراد رسل الموت من الملائكة: ملك الموت وأعوانه؛ فالجمع باعتبار تعدد الملائكة الموكلين بالتوفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص247، تحت «نكتة التعبير بالرسل دون الملائكة»","url":""}]},{"id":"s7-204","number":204,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة سؤال الملائكة: ﴿أين ما كنتم تدعون من دون الله﴾؟","answer":"سؤال توبيخ وتقرير يظهر عجز المعبودات التي دعوها؛ لا طلبًا لعلم مكانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص248–249، تحت «غرض الاستفهام التهكمي»","url":""}]},{"id":"s7-205","number":205,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة جوابهم: ﴿ضلوا عنا﴾، وتصوير غياب آلهتهم بالضلال؟","answer":"أي غابوا وفقدوا فلم ينفعوا؛ فصور بطلان أثرهم كضياع من كانوا يرجون حضورهم ونصرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص250–251، تحت «سر استعمال لفظ الضلال»","url":""}]},{"id":"s7-206","number":206,"surah":7,"verses":[37],"references":[{"surah":7,"verses":[37]}],"verseLabel":"الأعراف: 37","question":"ما دلالة شهادتهم ﴿على أنفسهم أنهم كانوا كافرين﴾؟","answer":"شهدوا حين قامت الحجة وعاينوا الحق، فصار اعترافهم بالكفر إقرارًا على أنفسهم لا ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص251–252، تحت «غرض ذكر القيد»","url":""}]},{"id":"s7-207","number":207,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير بقوله تعالى: ﴿ادخلوا في أمم قد خلت من قبلكم﴾، ولم يقل: مع أمم؟","answer":"يذكر المصدر وجهين: أن تكون ﴿في﴾ بمعنى المصاحبة، أو أن تكون للظرفية، وهو الأوفق عنده؛ أي ادخلوا في جملة أمم سبقتكم. فالظرفية تصور اندراجهم في تلك الجماعات، ويتبع ذلك دخولهم النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص259، تحت «براعة استعمال حرف الجر ﴿في﴾»","url":""}]},{"id":"s7-208","number":208,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا جمع الجن والإنس في دخول النار؟","answer":"جمع الفريقين لأن التكليف والعصيان وقعا منهما، ولأن شياطين الجن وأتباعهم من الإنس اشتركوا في الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص261–262، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿من الجن والإنس﴾»","url":""}]},{"id":"s7-209","number":209,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿كلما دخلت أمة لعنت أختها﴾، وسمى الأمة الأخرى أختًا؟","answer":"سميت أختها لاشتراكهما في الملة والكفر والمصير، مع أن هذا الاشتراك لم يمنع التلاعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص263، تحت «نكتة الاستعارة التصريحية في قوله تعالى: ﴿أختها﴾»","url":""}]},{"id":"s7-210","number":210,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا اداركوا فيها جميعًا﴾، واختار صيغة الادّارك؟","answer":"الادّراك تتابع اللحاق حتى يجتمع آخرهم بأولهم في النار؛ وصيغته تصور تدارك بعضهم بعضًا واجتماعهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص256–257، 264، تحت «المعنى الإجمالي؛ لطيفة في توجيه الإدغام في قوله: ﴿اداركوا﴾»","url":""}]},{"id":"s7-211","number":211,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا سمت الأمة المتبوعة ﴿أولاهم﴾ والتابعة ﴿أخراهم﴾؟","answer":"الأولى المتقدمة زمانًا والمتبوعة في الضلال، والأخرى المتأخرة التابعة التي جاءت بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص256–257، تحت «شرح المفردات»","url":""}]},{"id":"s7-212","number":212,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا طلب الأتباع لقادتهم ﴿عذابًا ضعفًا﴾؟","answer":"طلبوا مضاعفة عذابهم انتقامًا ممن أغووهم، وفي العبارة كناية محتملة عن تمني أن يكون عذاب الأتباع أخف بالمقارنة مع عذاب القادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص265–266، تحت «براعة الكناية في قوله تعالى: ﴿فآتهم عذابًا ضعفًا من النار﴾»","url":""}]},{"id":"s7-1600","number":1600,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا نسب الأتباع الضلال إلى قادتهم فقالوا: ﴿هؤلاء أضلونا﴾؟","answer":"نسبوا الضلال إليهم لأنهم سببوه بالدعوة والتزيين، مع أن الأتباع اختاروا الاستجابة؛ فذكر السبب مكان الفعل الذي نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص265، تحت «نكتة المجاز المرسل في ﴿أضلونا﴾»","url":""}]},{"id":"s7-213","number":213,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ماذا حذف من قوله: ﴿لكل ضعف﴾؟","answer":"حذف المضاف إليه اعتمادًا على السياق؛ أي لكل فريق أو لكل أمة ضعف من العذاب. فالإيجاز يعم الفريقين ويقطع توهم اختصاص القادة بالمضاعفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص267، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-1601","number":1601,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"ماذا أفاد الاستدراك في قوله: ﴿ولكن لا تعلمون﴾؟","answer":"يرفع توهم الأتباع أن عذابهم أخف من عذاب القادة؛ فلكل نصيبه المضاعف، لكنهم لا يحيطون بمقادير الجزاء التي قدرها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص267، تحت «دلالة استعمال ﴿ولكن﴾»","url":""}]},{"id":"s7-1602","number":1602,"surah":7,"verses":[38],"references":[{"surah":7,"verses":[38]}],"verseLabel":"الأعراف: 38","question":"لماذا حذف متعلق العلم في قوله: ﴿ولكن لا تعلمون﴾؟","answer":"حذفه يعمم جهلهم: لا يعلمون مقدار عذاب كل فريق ولا حكمته ولا ما أعد للآخرين؛ فيشتد تقريعهم على الحكم بغير علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص268، تحت «نكتة حذف معمول ﴿تعلمون﴾»","url":""}]},{"id":"s7-214","number":214,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"ما دلالة قول الأولى للأخرى: ﴿فما كان لكم علينا من فضل﴾؟","answer":"نفوا مزية الأتباع عليهم في استحقاق التخفيف؛ فقد اشترك الجميع في الكفر ولم تكن للتابعين حجة ترفع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص270، تحت «شرح المفردات: ﴿فضل﴾»","url":""}]},{"id":"s7-215","number":215,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"ما أثر ﴿من﴾ في قولهم: ﴿فما كان لكم علينا من فضل﴾؟","answer":"تؤكد ﴿من﴾ النفي وتفيد استغراق أي فضل؛ فالمتبوعون ينفون أن تكون للأتباع مزية عليهم توجب أن يكون عذابهم أخف. وليس المراد تسمية زيادة العذاب فضلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص273، تحت «فائدة ﴿من﴾ في قوله تعالى: ﴿من فضل﴾»","url":""}]},{"id":"s7-216","number":216,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]}],"verseLabel":"الأعراف: 39","question":"لماذا خُتم الحوار بـ﴿فذوقوا العذاب بما كنتم تكسبون﴾؟","answer":"الخطاب يقطع جدالهم ورد التبعة بعضهم على بعض؛ فكل فريق يذوق جزاء ما كان يكتسبه باختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص275–276، تحت «دلالة اجتماع فعل الكون والمضارع: ﴿كنتم تكسبون﴾»","url":""}]},{"id":"s7-217","number":217,"surah":7,"verses":[39],"references":[{"surah":7,"verses":[39]},{"surah":8,"verses":[35]}],"verseLabel":"الأعراف: 39؛ الأنفال: 35","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كنتم تكسبون﴾، وفي الأنفال: ﴿بما كنتم تكفرون﴾؟","answer":"في الأعراف: 39 جاء ﴿تكسبون﴾ لأن السياق يجمع الكفر والضلال والإضلال، فناسب التعبير بالكسب لتعدد الأعمال الموجبة للعذاب. أما في الأنفال: 35 فجاء ﴿تكفرون﴾ لأن الكلام في عذاب المشركين وعبادتهم الباطلة عند البيت؛ فصرح بالكفر الذي استحقوا به ذلك العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص277، وج16، ص110–111، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-218","number":218,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تفتح لهم أبواب السماء﴾، وما الذي كان ينتظر أن يصعد؟","answer":"لا تفتح لصعود أرواحهم أو أعمالهم ودعائهم، ولا لنزول الرحمة عليهم؛ فالعبارة تصور حرمانهم من القبول والكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص285–286، تحت «براعة النظم في الجمع بين الحقيقة والمجاز»","url":""}]},{"id":"s7-219","number":219,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"ما وجه تضعيف الفعل في ﴿لا تُفَتَّح لهم أبواب السماء﴾؟","answer":"من وجوه التضعيف الإشارة إلى كثرة الأبواب، أو تأكيد نفي الفتح وتحقيقه. ويذكر المصدر وجهًا آخر يجعل المنفي ذلك الفتح القوي الذي يكون للمؤمنين وأعمالهم؛ فتبرز شدة الحرمان من القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص285، تحت «نكتة تضعيف الفعل ﴿تفتح﴾»","url":""}]},{"id":"s7-220","number":220,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا شُبّه استحالة دخولهم الجنة بولوج الجمل في سم الخياط؟","answer":"عُلّق دخولهم الجنة على أمر مستحيل في العادة: أن يدخل الجمل الضخم في ثقب الإبرة الدقيق. فالتعليق يصور انتفاء دخول المكذبين المستكبرين المذكورين، ويؤكد خلود حرمانهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص286–287، تحت «بلاغة تعليق النجاة بالمستحيل»","url":""}]},{"id":"s7-221","number":221,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا اختير ﴿الجمل﴾ و﴿سم الخياط﴾؟","answer":"الجمل مشهور بعظم الجرم، وسم الخياط غاية في الضيق؛ فاجتماعهما يصنع أوضح صورة للتعذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص287، تحت «نكتة تخصيص الجمل دون غيره»","url":""}]},{"id":"s7-222","number":222,"surah":7,"verses":[40],"references":[{"surah":7,"verses":[40]}],"verseLabel":"الأعراف: 40","question":"لماذا خُتمت بـ﴿وكذلك نجزي المجرمين﴾، لا: المكذبين؟","answer":"يصفهم ختام الآية بكمال الإجرام، ويجعل ما ذكر من الحرمان جزاءً يجري على أمثالهم من المجرمين المكذبين. ففي التذييل تعميم للحكم في هذا الصنف، وتقرير لاستحقاقهم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص288–289، تحت «بلاغة التذييل في الآية»","url":""}]},{"id":"s7-223","number":223,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"ما سرّ وصف جهنم بأنها ﴿مهاد﴾ مع أن المهاد موضع الراحة؟","answer":"وصف جهنم بالمهاد تهكم ومقابلة؛ فما يفترشونه ليس موضع راحة بل نار تحيط بهم من أسفل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص292، تحت «سر التعبير بقوله: ﴿مهاد﴾ دون عذاب»","url":""}]},{"id":"s7-224","number":224,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"كيف أغنى ذكر ﴿من جهنم﴾ مع المهاد عن إعادته مع الغواشي؟","answer":"هذا من الاحتباك: ذكر ﴿من جهنم﴾ مع المهاد يدل على أن الغواشي من جهنم أيضًا، وذكر ﴿من فوقهم﴾ مع الغواشي يدل على أن المهاد من تحتهم. فدل المذكور في كل جانب على المحذوف في الآخر، وأوجز تصوير إحاطة النار بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص293، تحت «فن الاحتباك في الآية»","url":""}]},{"id":"s7-225","number":225,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"لم صرّح بـ﴿من فوقهم﴾ مع الغواشي، ولم يقل: من تحتهم مهاد؟","answer":"يفهم من المهاد أنه يكون تحت صاحبه، فلا يحتاج إلى التصريح بالتحتية. أما ما يغشى الإنسان فقد يأتيه من جهات مختلفة؛ فذكر ﴿من فوقهم﴾ لتعيين جهة الغواشي وإتمام صورة إحاطة النار من فوقهم وتحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص292–293، تحت «براعة المقابلة بين ﴿مهاد﴾ و﴿فوقهم﴾»","url":""}]},{"id":"s7-226","number":226,"surah":7,"verses":[41],"references":[{"surah":7,"verses":[41]}],"verseLabel":"الأعراف: 41","question":"لماذا خُتمت بـ﴿وكذلك نجزي الظالمين﴾ بعد ﴿المجرمين﴾ في الآية السابقة؟","answer":"يجمع الختامان لهم وصفي الإجرام والظلم، ويناسب كل وصف سياقه: فقد قطعوا صلتهم بالآيات بالتكذيب والاستكبار، فذكر الإجرام مع حرمان الجنة؛ وظلموا أنفسهم بإيرادها الهلاك، فذكر الظلم مع إحاطة النار. وفي اختلاف الفاصلتين تنويع مع تحقيق الوصفين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص295–296، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-227","number":227,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"لماذا اعترض بين الإيمان والجنة بقوله: ﴿لا نكلف نفسًا إلا وسعها﴾؟","answer":"الجملة اعتراض يرفع توهم أن العمل الصالح المطلوب فوق الطاقة؛ فدخول الجنة مرتب على إيمان وعمل في حدود الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص302، تحت «براعة الإطناب بالاعتراض»","url":""}]},{"id":"s7-228","number":228,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"ما الذي يحدده لفظ ﴿وسعها﴾ في قوله: ﴿لا نكلف نفسًا إلا وسعها﴾؟","answer":"الوسع هو الطاقة؛ فالتكليف مقيد بما تطيقه النفس، ولا يطلب منها ما يجاوز قدرتها. وفي ذلك ترغيب في الطاعة، إذ ينال المؤمن النعيم العظيم بما يستطيعه من العمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص297، تحت «شرح المفردات: ﴿وسعها﴾»","url":""}]},{"id":"s7-229","number":229,"surah":7,"verses":[42],"references":[{"surah":7,"verses":[42]}],"verseLabel":"الأعراف: 42","question":"ماذا أفاد القصر في قوله: ﴿أولئك أصحاب الجنة﴾؟","answer":"يقصر استحقاق الجنة على المؤمنين العاملين بالصالحات المذكورين، ويقرر أنهم أهلها الملازمون لها؛ فلا يشاركهم فيها من أعرض عن الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص303–304، تحت «غرض القصر في الآية»","url":""}]},{"id":"s7-230","number":230,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزعنا ما في صدورهم من غل﴾، فجعل الغل شيئًا يُنزع؟","answer":"استعير النزع لإزالة الغل إزالة تامة قوية؛ كأنه جسم متغلغل في الصدور يُقتلع منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص308–309، تحت «نكتة الاستعارة التصريحية»","url":""}]},{"id":"s7-231","number":231,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما وجه التعبير بالصدور في ﴿ونزعنا ما في صدورهم من غل﴾؟","answer":"يذكر المصدر وجه التعبير بالصدر عن القلب، وهو محل الغل، فيوحي التطهير بأنه بلغ القلب وما يجاوره. ويذكر وجهًا آخر يحمل الصدر على حقيقته، إذ يظهر فيه الانشراح والانقباض؛ فنزع الغل يورث صفاء النفس وانشراح الصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص310، تحت «نكتة التعبير بالصدور بدل القلوب»","url":""}]},{"id":"s7-232","number":232,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما أثر وصف الأنهار بالجريان في مشهد الجنة؟","answer":"يرسم الجريان حركة الماء وانسيابه المتصل، ويزيد المشهد حياة وجمالًا، كما يوحي بتجدد النعمة ووفرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص310، تحت «دلالة التعبير بوصف الأنهار بالجريان»","url":""}]},{"id":"s7-1603","number":1603,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"كيف أسند الجريان إلى الأنهار مع أن الجاري ماؤها؟","answer":"أسند الفعل إلى المحل الذي يجري فيه الماء، وفي ذلك مبالغة توحي بوفرة الماء حتى كأن الأنهار نفسها تجري، مع إيجاز الصورة وقوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص311، تحت «بلاغة المجاز العقلي في الآية»","url":""}]},{"id":"s7-233","number":233,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا وصف الله بقولهم: ﴿الذي هدانا لهذا﴾؟","answer":"جعلت الصلة الهداية سبب الحمد الظاهر، فاستحضر أهل الجنة نعمة ربهم التي أوصلتهم إلى النعيم، وربطوا الجزاء بالمنة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص313، تحت «سر الوصف بالاسم الموصول»","url":""}]},{"id":"s7-1604","number":1604,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"إلام يشير اسم الإشارة في قول أهل الجنة: ﴿هدانا لهذا﴾؟","answer":"يشير إلى ما هم فيه من الجنة والنعيم، أو إلى الطريق الذي أوصلهم إليه؛ فاستعملت الإشارة إلى الحاصل للدلالة على سببه وتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص314، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s7-234","number":234,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما دلالة ﴿لولا أن هدانا الله﴾، وكيف أغنى ما قبلها عن ذكر جوابها؟","answer":"تعلق ﴿لولا﴾ حصول الاهتداء بهداية الله، فيعترف أهل الجنة بأن الفضل له. وحذف جوابها لدلالة ﴿وما كنا لنهتدي﴾ عليه؛ أي لولا هداية الله ما اهتدينا، فأوجز الكلام مع وضوح تعلق النعمة بفضل المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص314–315، تحت «دلالة حذف الجواب»","url":""}]},{"id":"s7-235","number":235,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا أكد أهل الجنة قولهم: ﴿لقد جاءت رسل ربنا بالحق﴾؟","answer":"أكدوه فرحًا بتحقق الوعد بعد مشاهدته، وإظهارًا لصدق الرسل وإقرارًا بأن ما أخبروا به صار واقعًا مشهودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص315، تحت «نكتة التأكيد بلام القسم و﴿قد﴾»","url":""}]},{"id":"s7-1605","number":1605,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ماذا أفادت إضافة الرب إلى أهل الجنة في قولهم: ﴿رسل ربنا﴾؟","answer":"تستحضر إحسان الله إليهم وتربيته وهدايته، وتجعل مجيء الرسل من آثار عنايته بهم؛ فناسبت مقام الشكر بعد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص315–316، تحت «دلالة الإضافة في ﴿ربنا﴾»","url":""}]},{"id":"s7-236","number":236,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"لماذا نودوا: ﴿أن تلكم الجنة أورثتموها﴾، فجعلت الجنة ميراثًا؟","answer":"شبه حصول الجنة لهم بالميراث الذي يصير إلى صاحبه من غير بيع ولا شراء ولا غصب. وفي الصورة بيان عظم المنحة؛ فالعمل سبب لها بفضل الله، وليس عوضًا يستقل بمقابلة هذا النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص318–319، تحت «دلالة التعبير بالإرث»","url":""}]},{"id":"s7-237","number":237,"surah":7,"verses":[43],"references":[{"surah":7,"verses":[43]}],"verseLabel":"الأعراف: 43","question":"ما سرّ الجمع بين ﴿أورثتموها﴾ و﴿بما كنتم تعملون﴾؟","answer":"العمل سبب للدخول بتفضل الله، أما نفس الجنة وثوابها فميراث وفضل؛ فلا تعارض بين السببية والمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص319، تحت «معنى الباء في ﴿بما﴾»","url":""}]},{"id":"s7-238","number":238,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا نادى أصحاب الجنة أصحاب النار؟","answer":"نادوهم لإقامة الحجة وإظهار صدق وعد الله للفريقين، وزيادة الحسرة على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص329، تحت «دلالة التعبير بالمناداة ﴿ونادى﴾ دون القول»","url":""}]},{"id":"s7-239","number":239,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما دلالة التعبير بـ﴿ربنا﴾ و﴿ربكم﴾ في خطاب أصحاب الجنة لأصحاب النار؟","answer":"يشير ﴿ربنا﴾ إلى إحسان الله لأهل الإيمان في الدنيا بنعمه وهدايته، وإتمام هذا الإحسان لهم في الآخرة. ويذكر ﴿ربكم﴾ أهل النار بمن أنعم عليهم وهداهم إلى سبيل الرشاد في الدنيا، فقابلوا إحسانه بالجحود والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص331، تحت «دلالة التعبير بالربوبية دون الألوهية»","url":""}]},{"id":"s7-240","number":240,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا سأل أهل الجنة: ﴿فهل وجدتم ما وعد ربكم حقًا﴾ وهم يعلمون؟","answer":"السؤال للتقرير والتبكيت، ليقر أهل النار بألسنتهم بصدق الوعيد كما أقر أهل الجنة بصدق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص331–332، تحت «دلالة الاستفهام في قوله: ﴿فهل وجدتم﴾»","url":""}]},{"id":"s7-241","number":241,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما دلالة جواب أهل النار: ﴿قالوا نعم﴾؟","answer":"يثبت جوابهم صدق ما سئلوا عنه، فيقرون بأنهم وجدوا الوعيد حقًا. ويصور هذا الإقرار خزيهم وحسرتهم؛ فقد صار ما كانوا ينكرونه واقعًا لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص334، تحت «دلالة الجواب ﴿قالوا نعم﴾ في سياق الآية»","url":""}]},{"id":"s7-242","number":242,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿فأذن مؤذن بينهم﴾، ولم يُسمّ المؤذن؟","answer":"الفعل ﴿أذّن﴾ مبني للمعلوم وفاعله ﴿مؤذن﴾. ونُكر المؤذن لأن تعيين شخصه غير مقصود؛ فالعناية بالإعلام والحكم المعلن. وذكر الفاعل مع الفعل يبين أن المنادي جهة أخرى بين الفريقين، ويذكر المصدر أنه من الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص335، تحت «نكتة تنكير ﴿مؤذن﴾»","url":""}]},{"id":"s7-243","number":243,"surah":7,"verses":[44],"references":[{"surah":7,"verses":[44]}],"verseLabel":"الأعراف: 44","question":"لماذا كانت اللعنة ﴿على الظالمين﴾ لا على الكافرين؟","answer":"يعلل هذا الوصف استحقاقهم اللعنة؛ فظلمهم هو الذي أوردهم الهلاك. وهو وصف جامع يصل هذا الإعلان بما بعده من صدهم عن سبيل الله وابتغائها عوجًا وكفرهم بالآخرة؛ فلا يراد هنا فصل الظلم عن كفرهم، بل بيان موجب الجزاء وجمع أوصافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص337–338، تحت «دلالة (ال) في لفظ ﴿الظالمين﴾»","url":""}]},{"id":"s7-244","number":244,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]},{"surah":11,"verses":[19]}],"verseLabel":"الأعراف: 45؛ هود: 19","question":"لماذا وصف الظالمين بأنهم ﴿يصدون عن سبيل الله ويبغونها عوجًا﴾؟","answer":"في الأعراف: 45: هذه أوصاف تكشف تعدي ظلمهم إلى غيرهم: يمنعون الناس من طريق الله، ويحاولون إظهاره معوجًا لصدهم عنه.\n\nفي هود: 19: لم يكتفوا بضلال أنفسهم، بل منعوا غيرهم وصوروا الطريق المستقيم معوجًا؛ فجمعوا الصد والتحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص343–344، تحت «سر التعبير بالصد ﴿يصدون﴾ دون المنع»","url":""}]},{"id":"s7-245","number":245,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿يبغونها عوجًا﴾، فجعل العوج مطلوبًا؟","answer":"صورهم كأنهم يطلبون العوج ويبتغونه للسبيل المستقيم؛ أي يلتمسون الشبه ويصفونه بالانحراف أو يريدون الناس عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص346–347، تحت «بلاغة المجاز في قوله تعالى: ﴿ويبغونها عوجًا﴾»","url":""}]},{"id":"s7-246","number":246,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم بالآخرة كافرون﴾ بتقديم ﴿بالآخرة﴾؟","answer":"قُدّم للاهتمام بموضع كفرهم وتشنيعه؛ فالآخرة التي دل عليها الوحي هي خاصة ما يجحدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص349–350، تحت «دلالة تقديم الجار والمجرور»","url":""}]},{"id":"s7-247","number":247,"surah":7,"verses":[45],"references":[{"surah":7,"verses":[45]}],"verseLabel":"الأعراف: 45","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وهم بالآخرة كافرون﴾، وزاد في هود ضميرًا آخر فقال: ﴿وهم بالآخرة هم كافرون﴾؟","answer":"في هود تكرر ﴿هم﴾ لتقوية الحكم بكفرهم بالآخرة، وناسب ذلك مقام تسجيل إنكار البعث وما ينتظرهم من العقاب، وما سبق من الإطناب في ذكرهم. أما الأعراف فالمقام حكاية حال قوم دخلوا النار وظهر عقابهم، فناسبه الإيجاز دون هذا التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص348–349، تحت «سر ذكر الضمير المنفصل ﴿وهم﴾ مرة لا مرتين»","url":""}]},{"id":"s7-248","number":248,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما دلالة تقديم متعلق الخبر ﴿وبينهما﴾ على المسند إليه ﴿حجاب﴾؟","answer":"الحجاب يفصل بين الجنة والنار، وفوق أعاليه رجال يشرفون على الفريقين؛ فرتب المكان قبل ذكر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص357–358، تحت «تقديم متعلق الخبر ﴿وبينهما﴾ على المسند إليه ﴿حجاب﴾»","url":""}]},{"id":"s7-249","number":249,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"لماذا سُمي السور أو المكان ﴿الأعراف﴾؟","answer":"الأعراف جمع عُرف، وهو المكان المرتفع الظاهر من السور؛ سمي بذلك لعلوه وتمكن من عليه من معرفة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص357–358، تحت «سر التعبير بالأعراف دون السور»","url":""}]},{"id":"s7-250","number":250,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما دلالة التنوين في ﴿يعرفون كلًا بسيماهم﴾؟","answer":"التنوين عوض عن المضاف إليه الذي دل عليه السياق؛ أي يعرفون كل فريق من أصحاب الجنة وأصحاب النار، أو كل أصحاب الجنة وأصحاب النار، بعلاماتهم. فاستغني عن إعادة ذكر الفريقين لوضوح المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص360، تحت «دلالة التنوين في لفظ ﴿كلًا﴾»","url":""}]},{"id":"s7-251","number":251,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"لماذا نادوا أصحاب الجنة بالسلام مع أنهم ﴿لم يدخلوها وهم يطمعون﴾؟","answer":"يحيون أهل الجنة بعدما عرفوهم بعلاماتهم، وفي ندائهم تضرع ورجاء واسترحام. ثم يبين قوله ﴿لم يدخلوها وهم يطمعون﴾ أن أصحاب الأعراف لم يدخلوا الجنة بعد، مع شدة رجائهم في فضل الله ودخولها؛ فلا ينافي سلامهم بقاءهم منتظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص361–362، تحت «سر التعبير بـ﴿سلام﴾ دون غيرها في سياق الآية»","url":""}]},{"id":"s7-252","number":252,"surah":7,"verses":[46],"references":[{"surah":7,"verses":[46]}],"verseLabel":"الأعراف: 46","question":"ما دلالة المضارع في ﴿وهم يطمعون﴾؟","answer":"يصور المضارع تجدد طمع أصحاب الأعراف وشدة رجائهم في دخول الجنة. وتبين الجملة الحالية المعترضة حالهم وهم لم يدخلوها بعد، وقوة رغبتهم فيما عند الله من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص363–364، تحت «نكتة التعبير بالفعل المضارع ﴿يطمعون﴾»","url":""}]},{"id":"s7-253","number":253,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا صرفت أبصارهم تلقاء أصحاب النار﴾ بالبناء للمجهول؟","answer":"لا حاجة إلى تعيين الصارف؛ فالعناية بتصوير نظرهم إلى أصحاب النار وما يبعثه من الخوف. ويقابل هذا الصرف توجههم إلى الجنة برغبة؛ فهم لا يتعمدون التطلع إلى النار، بل تقع أبصارهم على ما حولهم وهم كارهون لرؤيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص367–368، تحت «سر بناء الفعل للمفعول في ﴿صرفت﴾»","url":""}]},{"id":"s7-254","number":254,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"لماذا اختير ﴿تلقاء﴾؟","answer":"﴿تلقاء﴾ تحدد الجهة المقابلة التي تقع فيها النار أمام أبصارهم، وتصور مواجهتهم المباشرة للمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص370، تحت «سر التعبير بقوله: ﴿تلقاء﴾ دون جهة»","url":""}]},{"id":"s7-255","number":255,"surah":7,"verses":[47],"references":[{"surah":7,"verses":[47]}],"verseLabel":"الأعراف: 47","question":"ما دلالة قولهم: ﴿ربنا لا تجعلنا مع القوم الظالمين﴾ بدلًا من: من أهل النار؟","answer":"ينفون عن أنفسهم مجرد المعية مع الظالمين، وهي أعم من أن يكونوا منهم؛ فيكون طلب النجاة من مصيرهم أولى. وذكر الظلم يبين سبب العذاب، فكأنهم يسألون الوقاية من العذاب ومن سببه الذي أورد أصحابه النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص372–373، تحت «سر التعبير بالمعية في قوله تعالى: ﴿مع القوم الظالمين﴾»","url":""}]},{"id":"s7-256","number":256,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"لماذا نادى أصحاب الأعراف رجالًا ﴿يعرفونهم بسيماهم﴾؟","answer":"نادوهم للتوبيخ والتقرير بعدما عرفوهم بعلامات الكبر والكفر، وإظهار انقلاب منزلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص375–376، تحت «سر التعبير بالمناداة ﴿ونادى﴾ وأثره في المعنى»","url":""}]},{"id":"s7-257","number":257,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"ما سرّ التعبير بقوله تعالى: ﴿ما أغنى عنكم جمعكم وما كنتم تستكبرون﴾؟","answer":"يحتمل الأسلوب النفي أو الاستفهام الإنكاري، ويؤدي في الحالين معنى التوبيخ والشماتة: لم ينفعهم جمع المال والرجال واستكبارهم، ولم يدفع عنهم العذاب. ففيه إبطال لما كانوا يعتزون به من قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص379–380، تحت «سر التعبير بقوله: ﴿ما أغنى﴾ دون غيرها في الآية»","url":""}]},{"id":"s7-258","number":258,"surah":7,"verses":[48],"references":[{"surah":7,"verses":[48]}],"verseLabel":"الأعراف: 48","question":"لماذا عبّر عن أتباعهم أو أموالهم بـ﴿جمعكم﴾؟","answer":"﴿جمعكم﴾ اسم جامع لما كانوا يجمعونه من مال ورجال وأتباع، وما اعتزوا به من قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص380–381، تحت «سر التعبير بلفظ ﴿جمعكم﴾ في أثناء السياق»","url":""}]},{"id":"s7-259","number":259,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"ما دلالة الاستفهام ﴿أهؤلاء﴾؟","answer":"الاستفهام للتقرير والتوبيخ: هؤلاء الضعفاء الذين حلفتم ألا تصيبهم الرحمة قد أكرمهم الله، فظهر بطلان حكمكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص386–387، تحت «دلالة الاستفهام ﴿أهؤلاء﴾»","url":""}]},{"id":"s7-260","number":260,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"لماذا عُدّيت الرحمة بفعل ﴿ينالهم﴾؟","answer":"النيل يصور الرحمة كعطاء يصل إليهم ويصيبهم فعلًا، فيقابل إنكار المستكبرين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص388–389، تحت «بلاغة الاستعارة التصريحية التبعية»","url":""}]},{"id":"s7-261","number":261,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"ما أثر مجيء ﴿ادخلوا الجنة﴾ مباشرة دون التصريح بفعل القول؟","answer":"يقرب حذف القول مشهد الإذن بالدخول، كأن السامع يتلقى البشارة مباشرة؛ إذ المقصود الإكرام والإنعام. ويذكر المصدر أن الخطاب يحتمل أصحاب الأعراف أو المؤمنين المستضعفين الذين كان المستكبرون يحتقرونهم، وفي الحالين يظهر بطلان حكم المستكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص391–392، تحت «دلالة عدم ذكر القول قبل قوله: ﴿ادخلوا الجنة﴾»","url":""}]},{"id":"s7-262","number":262,"surah":7,"verses":[49],"references":[{"surah":7,"verses":[49]}],"verseLabel":"الأعراف: 49","question":"لماذا جمع نفي الخوف والحزن بعد الأمر بالدخول؟","answer":"نفي الخوف يؤمنهم من المستقبل، ونفي الحزن يزيل ألم الماضي؛ فتم لهم الأمن عند الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص394–395، تحت «سر اختصاص نفي الخوف والحزن دون سواهما»","url":""}]},{"id":"s7-263","number":263,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"ما سرّ طلب أصحاب النار بلفظ ﴿أفيضوا علينا من الماء﴾ بدلًا من: أعطونا ماء؟","answer":"الإفاضة إعطاء بكثرة وانصباب، فاختاروها لشدة عطشهم وحاجتهم إلى وفرة الماء لا مجرد قدر يسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص399–400، تحت «سر التعبير بلفظ الإفاضة دون السقيا»","url":""}]},{"id":"s7-264","number":264,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"ما سرّ قولهم: ﴿أو مما رزقكم الله﴾ وإبهام سائر الرزق؟","answer":"أبهموا طمعًا في أي شيء من نعيم الجنة، فلا يهمهم نوع الرزق بعد الماء من شدة الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص403–404، تحت «دلالة حذف متعلق ﴿مما رزقكم الله﴾»","url":""}]},{"id":"s7-265","number":265,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"لماذا جاء الرد: ﴿إن الله حرمهما على الكافرين﴾، فثنى الضمير؟","answer":"الضمير للماء وما رزق الله أهل الجنة؛ فثنى ليشمل المطلوبين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص402–403، تحت «دلالة الجمع بين الماء والطعام»","url":""}]},{"id":"s7-266","number":266,"surah":7,"verses":[50],"references":[{"surah":7,"verses":[50]}],"verseLabel":"الأعراف: 50","question":"لماذا عُبّر عن المنع الأخروي بالتحريم؟","answer":"التحريم هنا المنع القطعي، لا حكم التكليف؛ أي قضى الله بحرمان الكافرين منهما في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص405، تحت «سر التعبير بالفعل حرم دون المنع في السياق»","url":""}]},{"id":"s7-267","number":267,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿اتخذوا دينهم لهوًا ولعبًا﴾، وفي الأنعام: ﴿لعبًا ولهوًا﴾؟","answer":"من التوجيهات التي يذكرها المصدر مراعاة ترتيب أطوار العمر: فاللعب يغلب في الصبا، واللهو في الشباب. وفي الأعراف يحكى حالهم يوم القيامة بعد انقضاء الدنيا، فجاء اللهو ثم اللعب على ترتيب ما مضى، من الأقرب إلى الأبعد؛ أما في الأنعام فجاء اللعب ثم اللهو وفق ترتيب هذين الطورين في الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص418، تحت «المتشابه اللفظي بين آية الأعراف51 وآية العنكبوت64»","url":""}]},{"id":"s7-268","number":268,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما سرّ تقديم اللهو هنا وأُخر في الأنعام؟","answer":"يوجه المصدر الفرق باختلاف جهة النظر إلى الدنيا: في الأعراف ينظر إليها من مشهد القيامة وقد مضت، فقدم اللهو الذي يغلب في الشباب على اللعب الذي يغلب في الصبا. وفي الأنعام روعي ترتيب الأطوار في الحياة، فقدم اللعب ثم اللهو. وهو وجه من وجوه التوجيه، لا حصر لمعنى الآيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص418، تحت «المتشابه اللفظي بين آية الأعراف51 وآية العنكبوت64»","url":""}]},{"id":"s7-269","number":269,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما المراد بقوله تعالى: ﴿فاليوم ننساهم كما نسوا لقاء يومهم هذا﴾، وهل النسيان هنا ذهول؟","answer":"النسيان من الله تركهم في العذاب وحرمانهم من الرحمة، لا ذهول العلم؛ جزاء إهمالهم الاستعداد للقاء يومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص414–415، تحت «دلالة النسيان بين الحقيقة والمجاز»","url":""}]},{"id":"s7-270","number":270,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"ما أثر إضافة اليوم إليهم والإشارة إليه في ﴿لقاء يومهم هذا﴾؟","answer":"إضافة اليوم إليهم تزيد تشنيع ترك الاستعداد لأمر يخصهم ويعود أثره عليهم. والإشارة بـ﴿هذا﴾ تقرعهم باليوم الحاضر الذي كانوا ينكرونه، وقد صار واقعًا مشاهدًا لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص416، تحت «بلاغة الإضافة في المركب الإضافي ﴿يومهم﴾»","url":""}]},{"id":"s7-271","number":271,"surah":7,"verses":[51],"references":[{"surah":7,"verses":[51]}],"verseLabel":"الأعراف: 51","question":"لماذا عطف ﴿وما كانوا بآياتنا يجحدون﴾ على نسيان اللقاء؟","answer":"جمعوا بين ترك الاستعداد للآخرة والجحود بالآيات؛ فالأول إعراض عملي والثاني إنكار اعتقادي، وكلاهما سبب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص417، تحت «دلالة ترتيب أوصاف الكافرين في هذه الآية وما قبلها»","url":""}]},{"id":"s7-272","number":272,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"ما وجه التعبير بـ﴿كتاب﴾ وتنكيره في ﴿ولقد جئناهم بكتاب﴾؟","answer":"يفيد لفظ الكتاب معنى يشمل جنس الكتب المنزلة، ويدخل فيه القرآن الذي واجههم بالحجة. وتنكيره للتعظيم: كتاب عظيم الشأن في هدايته وبيانه، ويحتمل التنويع؛ أي كتاب من جنس ما أنزل على الأمم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص425–426، تحت «غرض تنكير لفظ كتاب في قوله: ﴿بكتاب﴾»","url":""}]},{"id":"s7-273","number":273,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فصلناه على علم﴾، وما دلالة ﴿على﴾؟","answer":"﴿على﴾ تفيد التمكن والاستناد: فُصل الكتاب تفصيلًا قائمًا على علم محيط بالمصالح والحقائق، لا عن جهل أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص427–428، تحت «سر استعمال حرف الاستعلاء في قوله: ﴿فصلناه على علم﴾»","url":""}]},{"id":"s7-274","number":274,"surah":7,"verses":[52],"references":[{"surah":7,"verses":[52]}],"verseLabel":"الأعراف: 52","question":"لماذا وصف الكتاب بأنه ﴿هدى ورحمة لقوم يؤمنون﴾؟","answer":"هو هدى بما يرشد إليه ورحمة بما يثمره اتباعه؛ وخص المؤمنين لأنهم المنتفعون بهذين الأثرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص428–429، تحت «دلالة عطف الرحمة على الهدى»","url":""}]},{"id":"s7-275","number":275,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿هل ينظرون إلا تأويله﴾، واستعمل النظر بمعنى الانتظار؟","answer":"النظر هنا بمعنى الانتظار، وقد صور إعراضهم كحال من ينتظر وقوع الوعيد، تهكمًا بهم؛ فهم لا ينتظرونه حقيقة لأنهم يجحدونه. فكأنهم لم يبق لهم بعد إعراضهم عن الحجج إلا أن يعاينوا ما أنذروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص435–436، تحت «بلاغة الاستعارة التهكمية في التعبير بالنظر في قوله: ﴿ينظرون﴾»","url":""}]},{"id":"s7-276","number":276,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما معنى مجيء ﴿تأويل﴾ الكتاب؟","answer":"تأويله تحقق مآله ووقوع ما وعد به من البعث والحساب والثواب والعقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص432، تحت «شرح المفردات: ﴿تأويله﴾»","url":""}]},{"id":"s7-277","number":277,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"لماذا وُصفوا بأنهم ﴿نسوه من قبل﴾؟","answer":"أي تركوا العمل به والإيمان بمآله مع قيامه بينهم، فعوملوا معاملة من نسي شيئًا ولم يعتن به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص437–438، تحت «سر التعبير بالنسيان عن الترك»","url":""}]},{"id":"s7-278","number":278,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما مناسبة قولهم: ﴿قد جاءت رسل ربنا بالحق﴾ بعد مجيء التأويل؟","answer":"قالوه عند مشاهدة تحقق أخبار الرسل، إقرارًا متأخرًا بصدقهم لا ينفع بعد فوات زمن الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص438–439، تحت «توجيه تخصيص قول الناسين دون غيره من أقوالهم بالذكر»","url":""}]},{"id":"s7-279","number":279,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"لماذا طلبوا أولًا الشفعاء ثم طلبوا الرد إلى الدنيا؟","answer":"قدموا طلب الشفاعة لأنها تبدو لهم أقرب إلى إمكان الخلاص، أما الرد إلى الدنيا فأبعد وأشد تعذرًا. ويكشف الجمع بين الطلبين اضطرابهم وتعلقهم بأي سبيل للنجاة؛ فلا يلزم من ترتيب الكلام أن الطلب الثاني وقع بعد فراغهم من الأول واليأس منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص442–443، تحت «نكات تقديم طلب الشفاعة على الرد إلى الدنيا»","url":""}]},{"id":"s7-280","number":280,"surah":7,"verses":[53],"references":[{"surah":7,"verses":[53]}],"verseLabel":"الأعراف: 53","question":"ما وجه البلاغة في التعبير في قوله تعالى: ﴿خسروا أنفسهم﴾؟","answer":"أضاعوا أنفسهم بإدخالها النار، وغابت عنهم الآلهة والأقوال التي اختلقوها فلم يبق لافترائهم أثر ينفعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص445–446، تحت «بلاغة التعبير في قوله تعالى: ﴿خسروا أنفسهم﴾»","url":""}]},{"id":"s7-281","number":281,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"كيف يستدل بخلق السماوات والأرض في ﴿إن ربكم الله الذي خلق السماوات والأرض﴾ على استحقاقه العبادة؟","answer":"ذكر الخلق وصفًا يقرر أن الله هو الرب المنعم المدبر، فيلزم المخاطبين بإفراده بالعبادة. فالخلق حقيقة يقرون بها، فجعلت دليلًا على ما أعرضوا عنه من توحيد الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص457، تحت «مناسبة ذكر الخلق للربوبية والأمر للألوهية»","url":""}]},{"id":"s7-282","number":282,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]},{"surah":14,"verses":[19]},{"surah":15,"verses":[85]}],"verseLabel":"الأعراف: 54؛ إبراهيم: 19؛ الحجر: 85","question":"ما دلالة ذكر السماوات والأرض في الاستدلال بالخلق في الأعراف54 وإبراهيم19 والحجر85؟","answer":"في الأعراف54: يستدل بخلق السماوات والأرض على أن الخالق هو الرب المستحق للعبادة، فتقام الحجة على من يقرون بالخلق ويعرضون عن إفراده بالألوهية.\n\nفي إبراهيم19: يوجه النظر إلى هذين الخلقين العظيمين للاستدلال بسعة القدرة على خلق الناس وإهلاكهم والإتيان بغيرهم، وأن الخلق قائم بالحق والحكمة.\n\nفي الحجر85: يأتي ذكر السماوات والأرض وما بينهما في مقام يعم الخلق؛ فجمع السماوات يستوعبها جميعًا، والأرض هي المعهودة للمخاطبين، وكل ذلك مخلوق بالحق لا عبثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص455–456، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-283","number":283,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم استوى على العرش﴾، وما دلالة ﴿ثم﴾؟","answer":"الاستواء على العرش ثابت لله على الوجه اللائق به بلا تمثيل؛ و﴿ثم﴾ للترتيب في الخبر أو الرتبة وإظهار عظمة التدبير بعد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص457–458، تحت «دلالة حرف ﴿ثم﴾ في قوله: ﴿ثم استوى﴾»","url":""}]},{"id":"s7-284","number":284,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا صُور الليل بأنه ﴿يغشي﴾ النهار؟","answer":"شُبه الليل بغطاء يلبس النهار ويستره بظلمته، فصوّر التعاقب إحاطةً وتغطية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص458–459، تحت «جزالة التعبير البلاغي في قوله: ﴿يغشي الليل النهار﴾»","url":""}]},{"id":"s7-285","number":285,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"كيف يصور ﴿يطلبه حثيثًا﴾ تعاقب الليل والنهار؟","answer":"يصور تعاقبهما بمطاردة طالب لمطلوب لا يفتر عنها، فيطلب الليل النهار الذي سبقه، أو يتعاقبان في طلب أحدهما الآخر. و﴿حثيثًا﴾ تزيد معنى الطلب الحثيث المتصل، فتدل الصورة على سرعة اللحاق واستمرار التعاقب دون انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص459–460، تحت «أثر الاستعارة التمثيلية في تصوير المعنى»","url":""}]},{"id":"s7-286","number":286,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا عطف الشمس والقمر والنجوم منصوبة أو مرفوعة بحسب القراءة؟","answer":"في قراءة النصب تعطف الشمس والقمر والنجوم على السماوات، فتدخل في مفعول ﴿خلق﴾، وتكون ﴿مسخرات﴾ حالًا. وفي قراءة الرفع تكون الأسماء مبتدأ و﴿مسخرات﴾ خبرًا؛ فيستأنف بها تقرير خضوع هذه الأجرام لأمر الله. وكلا الوجهين ينتظم في الاستدلال على تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص460، تحت «دلالة الواو في قوله: ﴿والشمس﴾»","url":""}]},{"id":"s7-287","number":287,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]},{"surah":16,"verses":[12]}],"verseLabel":"الأعراف: 54؛ النحل: 12","question":"ما دلالة ﴿مسخرات بأمره﴾ في الأعراف54 والنحل12؟","answer":"في الأعراف54: يصور التسخير انقياد الشمس والقمر والنجوم لنظام مقدر لا تخرج عنه، و﴿بأمره﴾ ترد ذلك إلى قدرة الله وإرادته وتدبيره.\n\nفي النحل12: يبين التسخير انتظام هذه الأجرام في منافع العباد، و﴿بأمره﴾ تعني بأمره الكوني وقدرته، فلا تستقل هذه المخلوقات بتصرفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص461–462، تحت «دلالة الباء في قوله: ﴿بأمره﴾»","url":""}]},{"id":"s7-288","number":288,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا فُصل بين ﴿الخلق﴾ و﴿الأمر﴾: ﴿ألا له الخلق والأمر﴾؟","answer":"الخلق له وحده إيجادًا، والأمر له وحده حكمًا وتدبيرًا وتشريعًا؛ فجمع ملك الأعيان وملك التصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص463–464، تحت «موقع قوله: ﴿ألا له الخلق والأمر﴾ من الكلام السابق»","url":""}]},{"id":"s7-289","number":289,"surah":7,"verses":[54],"references":[{"surah":7,"verses":[54]}],"verseLabel":"الأعراف: 54","question":"لماذا خُتمت بـ﴿تبارك الله رب العالمين﴾؟","answer":"جاء التذييل بعد دلائل الخلق والتسخير إعلانًا لكثرة خير الله وعظمته واستحقاقه الربوبية للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص464–465، تحت «ربط جملة التذييل ﴿تبارك الله رب العالمين﴾»","url":""}]},{"id":"s7-290","number":290,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ادعوا ربكم﴾، واختار اسم الرب؟","answer":"اختير الرب لاستدعاء معنى التربية والإنعام والقرب من عباده، وهو أنسب بحال السائل المفتقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص471–472، تحت «سر التعبير بلفظ الربوبية في قوله: ﴿ادعوا ربكم﴾»","url":""}]},{"id":"s7-291","number":291,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"لماذا جمع بين ﴿تضرعًا وخفية﴾؟","answer":"التضرع ذل القلب وخضوعه، والخفية إسرار الصوت وإبعاده عن الرياء؛ فجمع حال الباطن وأدب الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص472–473، تحت «دلالة الجمع بين التضرع والخفية»","url":""}]},{"id":"s7-292","number":292,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"ما وجه التعبير بالتضرع مع الخفية، دون أن يقال: جهرًا وخفية؟","answer":"التضرع يصف ذل الداعي وخضوعه، والخفية تصف إسراره؛ فلا يتعارضان، بل يمكن أن يجتمعا. وإذا حمل التضرع على الدعاء الظاهر كان في اختياره بدل الجهر تنبيه إلى أدب العبودية؛ فالمقصود إظهار الحاجة والافتقار، لا مجرد رفع الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص472–473، تحت «فائدة وضع التضرع موضع الجهر»","url":""}]},{"id":"s7-293","number":293,"surah":7,"verses":[55],"references":[{"surah":7,"verses":[55]}],"verseLabel":"الأعراف: 55","question":"لماذا خُتمت بـ﴿إنه لا يحب المعتدين﴾، وما الاعتداء في الدعاء؟","answer":"يعلل الختام الأمر بأدب الدعاء، ويحذر من تجاوز حد العبودية والخضوع. ولم يقيد الاعتداء بنوع واحد؛ فيشمل الإخلال بأدب الدعاء وترك الطاعة واتباع غيرها، مع دخول مخالفة التضرع والخفية في النهي بحسب هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص474–475، تحت «بلاغة الفاصلة القرآنية»","url":""}]},{"id":"s7-294","number":294,"surah":7,"verses":[55,205],"references":[{"surah":7,"verses":[55,205]}],"verseLabel":"الأعراف: 55، 205","question":"ما الفرق بين قوله في الدعاء: ﴿تضرعًا وخُفية﴾، وقوله في الذكر آخر الأعراف: ﴿تضرعًا وخِيفة﴾؟","answer":"﴿خُفية﴾ في آية الدعاء من الإخفاء؛ فهي تصف إسرار الداعي مع خضوعه. أما ﴿خِيفة﴾ في آية الذكر فمن الخوف، فتصف ما يصاحب الذكر من خشية وهيبة. وقد ذكر خفاء الذكر هناك بقوله ﴿في نفسك﴾ و﴿دون الجهر من القول﴾؛ فجمع السياقان أدب القلب وأدب الصوت بألفاظ تلائم كل موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص468–469، تحت «شرح المفردات: ﴿خفية﴾»","url":""}]},{"id":"s7-295","number":295,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لم جاء النهي عن الإفساد في الأرض، دون الاكتفاء بالأمر بإصلاحها؟","answer":"في النهي عناية بترك الضرر؛ فدفع الفساد مقدم على تحصيل ما ينفع. والأرض مهيأة للصلاح، فينبه النهي إلى أن المطلوب صيانة ما أصلح وعدم تخريبه، كما أن ترك المنهي عنه أيسر من فعل المأمور به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص479–480، تحت «علة إيثار النهي عن الإفساد دون الأمر بالإصلاح»","url":""}]},{"id":"s7-296","number":296,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا قُيد النهي بقوله: ﴿بعد إصلاحها﴾؟","answer":"القيد يشدد القبح؛ فالإفساد بعد قيام الصلاح ونظامه نقض للنعمة وتخريب لما استقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص480، تحت «غرض التعبير بالظرف في قوله: ﴿بعد إصلاحها﴾»","url":""}]},{"id":"s7-297","number":297,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا جمع في الدعاء بين ﴿خوفًا وطمعًا﴾؟","answer":"يبين الوصفان باعثي الدعاء: خوف التقصير والعقاب، والطمع في المغفرة والرحمة والفضل. فيظل الداعي بين الخوف والرجاء، فلا يأمن العقاب ولا ييأس من الرحمة، ويجتهد في الطاعة طلبًا للإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص481–482، تحت «معنى الواو في قوله: ﴿خوفًا وطمعًا﴾»","url":""}]},{"id":"s7-298","number":298,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"ما دلالة الواو بين ﴿خوفًا وطمعًا﴾، وهل يلزم اجتماعهما في كل دعاء؟","answer":"يذكر المصدر وجه التقسيم: فقد يكون باعث الدعاء الخوف وطلب المغفرة، وقد يكون الطمع وطلب التوفيق والرحمة. ويجوز أن يجتمعا في الدعاء الواحد، لكن الجمع بينهما في الآية لا يوجب حضورهما معًا في كل دعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص482، تحت «معنى الواو في قوله: ﴿خوفًا وطمعًا﴾»","url":""}]},{"id":"s7-299","number":299,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إن رحمت الله قريب﴾، فوصف الرحمة المؤنثة بـ﴿قريب﴾؟","answer":"من الأوجه التي يذكرها المصدر مراعاة المعنى: أن الله قريب برحمته من المحسنين؛ فيعطى المضاف حكم المضاف إليه في التذكير. وفي العبارة تصوير لقرب حصول الرحمة ورجائه، وليس المقصود قرب مكان. وهذا توجيه من وجوه التعبير، لا قاعدة عامة تسوي بين المذكر والمؤنث في كل لفظ على وزن فعيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص482–483، تحت «نكتة تذكير لفظ ﴿قريب﴾»","url":""}]},{"id":"s7-300","number":300,"surah":7,"verses":[56],"references":[{"surah":7,"verses":[56]}],"verseLabel":"الأعراف: 56","question":"لماذا خُص المحسنون بقرب الرحمة؟","answer":"خُصوا لأن الإحسان امتثال الأمر وترك الإفساد والدعاء خوفًا وطمعًا؛ فمن حقق سببه كان أحق بقرب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص484، تحت «توجيه المخصوص بالذكر في لفظ ﴿المحسنين﴾»","url":""}]},{"id":"s7-301","number":301,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما وجه البلاغة في الاستعارة التمثيلية في قوله تعالى: ﴿يرسل الرياح بشرًا بين يدي رحمته﴾؟","answer":"جعل إرسال الرياح المتنوعة المتتابعة بشارةً تتقدم نزول المطر؛ فـ﴿بين يدي رحمته﴾ تمثيل لسبقها الرحمة، والرحمة هنا المطر وما ينشأ عنه من حياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص491–492، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s7-302","number":302,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا جُمعت ﴿الرياح﴾ هنا، وتأتي ﴿الريح﴾ مفردة في مواضع العذاب؟","answer":"يذكر المصدر أن الجمع يناسب اختلاف الرياح وتعاونها في منافع المطر، وأن الإفراد يكثر في مواضع العذاب لما يصور من قوة ريح ذات جهة واحدة. وهذا توجيه أغلبي لا قاعدة مطردة؛ فقد وردت الريح مفردة في الرحمة، مثل ﴿وجرين بهم بريح طيبة﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص504–505، تحت «الرياح والريح»","url":""}]},{"id":"s7-303","number":303,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا سُمي المطر ﴿رحمته﴾؟","answer":"سُمّي المطر رحمةً لأنه سبب الرحمة؛ فبه تحيا الأرض ويخرج الرزق، فأطلق اسم الأثر على سببه بيانًا لعظم النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص492–493، تحت «سر تسمية المطر رحمة»","url":""}]},{"id":"s7-304","number":304,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما وجه التعبير بـ﴿أقلت سحابًا ثقالًا﴾، بدل حملت؟","answer":"الإقلال حمل يشعر بخفة المحمول بالنسبة إلى حامله وقدرته عليه. فالسحاب ثقيل بما فيه من الماء، ومع ذلك تحمله الرياح المسخرة بسهولة؛ فجمع التعبير بين ثقل السحاب وخفته بالنسبة إلى ما سخّر لحمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص505–506، تحت «أقلت وحملت»","url":""}]},{"id":"s7-305","number":305,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا جُمع ﴿ثقالًا﴾ مع إفراد ﴿سحابًا﴾؟","answer":"﴿سحاب﴾ اسم جنس جمعي يدل على قطع السحاب، فروعِي معناه الجمعي في وصفه بـ﴿ثقالًا﴾؛ وثقلها بما تحمله من الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص493–494، تحت «بلاغة استعمال جمع التكسير في قوله: ﴿ثقالًا﴾»","url":""}]},{"id":"s7-306","number":306,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا انتقل من الغيبة إلى التكلم: ﴿سقناه لبلد ميت فأنزلنا﴾؟","answer":"الانتقال من الغيبة إلى التكلم بضمير العظمة يزيد العناية بالفعل ويؤكد أنه جار بقدرة الله وتقديره. فيتوجه الانتباه إلى سوق السحاب إلى المكان المحدد له، ثم إنزال الماء وإخراج الثمرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص495، تحت «نكتة الالتفات في قوله تعالى: ﴿سقناه﴾»","url":""}]},{"id":"s7-307","number":307,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما الصورة في وصف البلد بـ﴿ميت﴾؟","answer":"شبه البلد المجدب الخالي من النبات بالميت الذي لا تظهر فيه الحياة ولا ينتفع به. ففي وصفه بالموت تصوير لشدة جدبه، ويهيئ ذلك للمقابلة بين إحياء الأرض بالنبات وإخراج الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص496، تحت «بلاغة المجاز في الاستعمال والإسناد في وصف البلد بميت»","url":""}]},{"id":"s7-308","number":308,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"لماذا شُبه إخراج الموتى بإخراج الثمرات: ﴿كذلك نخرج الموتى﴾؟","answer":"إحياء الأرض بالماء مثال محسوس لإحياء الأجساد؛ فالذي أخرج النبات من الأرض الميتة قادر على إخراج الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص498–499، تحت «بلاغة التشبيه في قوله: ﴿كذلك نخرج الموتى﴾»","url":""}]},{"id":"s7-309","number":309,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما سرّ التعبير في قوله تعالى في الأعراف والروم: ﴿يرسل الرياح﴾ بالمضارع، وفي الفرقان وفاطر: ﴿أرسل الرياح﴾ بالماضي؟","answer":"في الأعراف جاء ﴿يرسل﴾ بالمضارع ملائمًا لما قبله من ﴿يغشي﴾ والأمر بالدعاء والنهي عن الإفساد، وما فيها من توجه إلى المستقبل. وفي الروم48 ناسب المضارع ما سبق في الروم46: ﴿أن يرسل الرياح﴾. أما الفرقان فجاء ﴿أرسل﴾ مع سياق الأفعال الماضية في ذكر النعم، وفاطر جاء فيها الماضي بعد تذكير الناس بالنعم الماضية وما صدر به من وصف الخالق؛ فناسب كل تعبير نسق سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص500–501، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-310","number":310,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما دلالة إضافة الرب إلى ضمير النبات في ﴿يخرج نباته بإذن ربه﴾؟","answer":"تشعر الربوبية بإنعام الله على النبات وتربيته وإمداده بما ينمو به. وتبين الإضافة عناية الخالق به، وأن خروجه الحسن إنما يكون بإذن ربه وتيسيره، فيلتفت السامع إلى نعمة الإنبات ومصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص517–518، تحت «سر إضافة ضمير النبات إلى لفظ الربوبية في قوله: ﴿بإذن ربه﴾»","url":""}]},{"id":"s7-311","number":311,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما وجه إسناد الخروج إلى النبات ثم تقييده بـ﴿بإذن ربه﴾؟","answer":"صور النبات كأنه يخرج بنفسه، ثم رد هذا الخروج إلى مشيئة الله بقوله ﴿بإذن ربه﴾؛ فلا يستقل النبات بإيجاد نفسه أو نموه. وفي الصورة إظهار لانقياده لربه وافتقاره إلى إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص515–516، تحت «المجاز العقلي في قوله: ﴿يخرج نباته﴾»","url":""}]},{"id":"s7-312","number":312,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"ما سرّ التعبير في قوله تعالى في البلد الخبيث: ﴿لا يخرج إلا نكدًا﴾، وحذف نباته؟","answer":"حُذف ﴿نباته﴾ لدلالة ما قبله عليه، ولتتجه العناية إلى هيئة الخروج: فلا يصدر من الأرض الخبيثة إلا خارج نكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص519–520، تحت «غرض الحصر في قوله: ﴿لا يخرج إلا نكدًا﴾»","url":""}]},{"id":"s7-313","number":313,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا اختير ﴿نكدًا﴾، لا: قليلًا؟","answer":"النكد ليس مجرد القلة، بل ما يخرج بعسر ويكون قليل الخير والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص525–526، تحت «النكد والسيئ»","url":""}]},{"id":"s7-314","number":314,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا صار اختلاف الأرض مثلًا لاختلاف القلوب؟","answer":"الأرض الطيبة تقبل الماء فتخرج النافع، والخبيثة لا تخرج إلا نكدًا؛ وكذلك القلوب: منها ما يقبل الوحي فيثمر، ومنها ما لا ينتفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص511–512، تحت «غرض التمثيل بالبلد الطيب والخبيث»","url":""}]},{"id":"s7-315","number":315,"surah":7,"verses":[58],"references":[{"surah":7,"verses":[58]}],"verseLabel":"الأعراف: 58","question":"لماذا خُتمت بـ﴿كذلك نصرف الآيات لقوم يشكرون﴾؟","answer":"خُتمت بالشكر لأن تصريف الدلائل وإنزال المطر وإخراج النبات نعم، ولا ينتفع بآياتها حقًا إلا من عرف المنعم وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص523–524، تحت «توجيه المخصوص بالذكر في قوله: ﴿لقوم يشكرون﴾»","url":""}]},{"id":"s7-316","number":316,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"لماذا افتتحت قصص الرسل بنوح؟","answer":"بدأت القصص بنوح، أول رسول إلى أهل الأرض المشركين، ثم تتتابع أخبار الرسل للاعتبار بمصائر المكذبين والمؤمنين وتسلية الرسول ﷺ وتثبيته أمام تكذيب قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص530، تحت «فوائد القصص القرآني وأغراضه»","url":""}]},{"id":"s7-317","number":317,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سرّ نداء نوح قومه بقوله: ﴿يا قوم اعبدوا الله﴾؟","answer":"في ﴿يا قوم﴾ استمالة بنداء القرابة والقرب، وإظهار لشفقة الرسول على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص533، تحت «فائدة إضافة ﴿يا قوم﴾ إلى ضمير المتكلم المحذوف»","url":""}]},{"id":"s7-318","number":318,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ما لكم من إله غيره﴾، دون أن يقال: لا إله إلا هو؟","answer":"ينفي الأسلوب أن يكون لهم أي إله مستحق للعبادة غير الله، و﴿من﴾ تؤكد استغراق النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص534–535، تحت «الفرق بين قوله: ﴿وما من إله إلا الله﴾ وقوله: ﴿ما لكم من إله غيره﴾»","url":""}]},{"id":"s7-319","number":319,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"ما سر التعبير بـ﴿إني أخاف عليكم﴾ دون: إني أحذركم؟","answer":"يظهر التعبير خوفه عليهم وحنوه وحرصه على نجاتهم، فيستميلهم بخطاب لين. فهو أنسب لإبراز شفقة الرسول من تحذير يشعر المخاطب بعلو المتكلم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص536، تحت «سر التعبير بقوله: ﴿أخاف﴾ دون: أحذركم»","url":""}]},{"id":"s7-320","number":320,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]},{"surah":39,"verses":[13]}],"verseLabel":"الأعراف: 59؛ الزمر: 13","question":"ما سر وصف اليوم بالعظمة في ﴿عَذَابَ يَوْمٍ عَظِيمٍ﴾ بدل وصف العذاب نفسه؟","answer":"في الأعراف59: وصف اليوم بالعظمة لعظم ما يقع فيه من العذاب والأهوال؛ فعظمة الظرف تدل على عظمة ما يحتويه.\n\nوفي الزمر13: المراد يوم القيامة، وتعظيم اليوم لما فيه من الدواهي والأهوال يستلزم تعظيم العذاب الواقع فيه، وتزيد إضافة العذاب إلى ذلك اليوم من تهويله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص537، تحت «دلالة وصف اليوم بالعظيم»","url":""}]},{"id":"s7-321","number":321,"surah":7,"verses":[59],"references":[{"surah":7,"verses":[59]}],"verseLabel":"الأعراف: 59","question":"لماذا بدأت قصة نوح في الأعراف بـ﴿لقد أرسلنا نوحًا﴾ بلا واو، وفي هود والمؤمنون بـ﴿ولقد أرسلنا نوحًا﴾؟","answer":"في الأعراف استؤنفت القصة للانتقال من إقامة الحجة وذكر النعم والوعيد إلى الاعتبار بأخبار الأمم، فجاءت ﴿لقد أرسلنا﴾ مفصولة. وفي هود جاءت الواو لربط القصة بما سبق من تقرير الرسالة والإنذار. وفي المؤمنون هي واو استئنافية تبدأ أخبار الأمم بعد دلائل التوحيد وذكر الفلك. فالمسألة ارتباط كل قصة بسياقها، ولا يكفي تعليل الفرق بكونها أول قصة في السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص530–531، تحت «علة فصل جملة: ﴿لقد أرسلنا﴾ عما قبلها»","url":""}]},{"id":"s7-322","number":322,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"لم أسند الرد على نوح إلى ﴿الملأ من قومه﴾ خاصة؟","answer":"لأن الملأ هم أشراف القوم وأصحاب الرأي والنفوذ فيهم، وهم أحرص على بقاء رئاستهم وأقدر على حمل العامة على مخالفة الرسول. فحكاية قولهم تبرز دور قادة القوم في مقاومة الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص541–542، تحت «علة إسناد القول إلى الملأ دون القوم»","url":""}]},{"id":"s7-323","number":323,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"ما دلالة تعبير الملأ بـ﴿لنراك﴾ في اتهام نوح بالضلال؟","answer":"الرؤية هنا قلبية بمعنى العلم، فكأنهم يدعون أنهم يعلمون ضلاله علمًا لا شك فيه. وأكدوا اتهامهم بإن واللام لإظهار الجزم بدعواهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص543، تحت «سر التعبير بالرؤية في قوله: ﴿لنراك﴾»","url":""}]},{"id":"s7-324","number":324,"surah":7,"verses":[60],"references":[{"surah":7,"verses":[60]}],"verseLabel":"الأعراف: 60","question":"ما سرّ تعبيرهم بقولهم: ﴿في ضلال﴾، فجعلوه محيطًا به؟","answer":"صوّروا الضلال ظرفًا يحيط به ويتمكن منه، مبالغةً في اتهامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص543–544، تحت «بلاغة المجاز المرسل في قوله: ﴿في ضلال مبين﴾»","url":""}]},{"id":"s7-325","number":325,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا أجاب نوح: ﴿ليس بي ضلالة﴾، ولم يقل: لست ضالًا؟","answer":"نفي أن تكون به ﴿ضلالة﴾ ينفي أن تلابسه أدنى خصلة من الضلال، وهو أبلغ من «لست ضالًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص548–549، تحت «سر العدول عن نفي الضلال المبين إلى نفي الضلالة»","url":""}]},{"id":"s7-326","number":326,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا أفرد ﴿ضلالة﴾ مع قولهم ﴿في ضلال﴾؟","answer":"أفرد ﴿ضلالة﴾ لينفي عنه فردًا واحدًا من جنس الضلال، فضلًا عن الغرق فيه كما زعموا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص548–549، تحت «سر العدول عن نفي الضلال المبين إلى نفي الضلالة»","url":""}]},{"id":"s7-327","number":327,"surah":7,"verses":[61],"references":[{"surah":7,"verses":[61]}],"verseLabel":"الأعراف: 61","question":"لماذا استدرك: ﴿ولكني رسول من رب العالمين﴾؟","answer":"الاستدراك يزيل تهمتهم ثم يثبت الحقيقة المقابلة: ليس به ضلالة، وإنما هو رسول من رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص550–551، تحت «بلاغة وصل جملة: ﴿ولكني رسول﴾ بما قبلها»","url":""}]},{"id":"s7-328","number":328,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿أبلغكم رسالات ربي﴾ بالجمع؟","answer":"جُمعت ﴿رسالات﴾ لتعدد ما يبلغه من أوامر ونواه ومواعظ وأخبار، أو لأن أجزاء الرسالة المتتابعة بمنزلة رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص556–557، تحت «نكتة الجمع في قوله: ﴿رسالات﴾»","url":""}]}]);
